/* 平成19年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h19.committeeSessions.push(...[{"id":"h19-20071009-4","meetingId":"h19-c-settlement","date":"2007年10月9日","dateIso":"2007-10-09","committee":"決算特別委員会","time":"午前１０時０２分～午後５時３６分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を158件整理しています。","topics":[{"id":"topic-01","title":"◯本多委員長 おはようございます。 ただいまより、決算特別委員会を開会いたします。 それでは、平成１８年度品川区一般会計歳入歳出決算","agenda":"◯本多委員長 おはようございます。 ただいまより、決算特別委員会を開会いたします。 それでは、平成１８年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"山内委員","kind":"質問・要望","question":"私は、１４７ページの防災生活圏促進事業について、国文学研究資料館について、改めていろいろとご意見をいただければなと考えています。そして、平成１９年度に入りましたけれども、平成１９年度までの国への働きかけというものを再度教えていただきたいなと思います。","respondent":"堀越行財政改革担当課長、伊勢住環境整備担当課長","answer":"先方の法人のほうといたしましても、文部科学省と協議を進めながら、私どもと取得の交渉を進めているというところです。こちらのほうといたしましても、今後とも交渉を引き続き続けていって、今年度中の取得を目指しています。 今、防災生活圏促進事業ということと、それから国文学資料館の関係ですが、取得した後に、戸越・豊町地区の防災生活圏につきましては、国文学資料館の入り口等の整備を予定しています。","id":"exchange-001"},{"speaker":"山内委員","kind":"質問・要望","question":"先日の総務費の中でも説明がございましたけれども、平成２０年からの区民への一時開放を行うと同時に、という説明がございました。これは、いわゆる平成２４年までの整備に向けての補助金というものがいただけるのかどうかというのを確認させていただきたいんですけれども。","respondent":"日下部企画財政課長","answer":"２ha以上の都市計画公園につきましては、都市計画事業ということで、標準的には大体事業費全体の４分の１が交付されるということになっております。財源的にはそのようなことで一定の見込みを立てているです。","id":"exchange-002"},{"speaker":"山内委員","kind":"質問","question":"先ほど課長の答弁の中で、入り口の整備をされるというのは、これはどういうことなのか、もっと具体的に教えていただけますか。","respondent":"伊勢住環境整備担当課長","answer":"戸越公園あるいは国文学資料館を含む５０haの事業でございまして、防災生活圏促進事業の対象になるということで、整備計画に盛り込んでいるところです。","id":"exchange-003"},{"speaker":"山内委員","kind":"質問","question":"それは使わないということになるんでしょうか。それとも、新たに、速やかな避難ができるような形での入り口をつけ加えるということなんか尋ねました。","respondent":"松代管理工事課長","answer":"整備方針というものを定めまして、先ほどの庁舎の免震工事に伴っての暫定利用が終わった後、本格的な整備になろうかと思います。そういったものは、今後きちんと計画を練り、また地域の方と、いろいろとお話を聞きながら、定めていきたいと、このように考えているところです。","id":"exchange-004"},{"speaker":"山内委員","kind":"質問","question":"建物について、この前一般質問の答弁の中でも、中にある三井文庫跡は残すという答弁がございました。まだその辺については、決定というか、見通しはついてないのか尋ねました。","respondent":"松代管理工事課長","answer":"建物につきましては、当面暫定的な利用ということで、使えるかどうか、今、検討されていると聞いております。できる限り撤去して、なるべく更地のような状態にして、公園整備を進めたいというのが基本的な考えです。","id":"exchange-005"},{"speaker":"山内委員","kind":"質問","question":"いよいよ設計という段階に入ってくるのかなと思うんですけれども、設計の仕方なんですが、これはプロポーザル方式をとられるのか尋ねました。","respondent":"松代管理工事課長","answer":"現在、整備方針ということで、定める際に、設計委託をいたしました。プロポーザル等々を含めて、少し検討の余地があるのかな、このように考えているところです。","id":"exchange-006"},{"speaker":"山内委員","kind":"質問","question":"今の段階では、何らかの形での青写真というものがあるわけですよね。平成２３年、例えば新たな設計をし直すとか、そのようなことが考えられるということなんか尋ねました。","respondent":"松代管理工事課長","answer":"次に、基本計画、実施設計という形に進んでまいります。実際これを細かく地域の方の声を聞きながら設計をする段階に入りますと、基本設計、実施設計と入ってまいります。","id":"exchange-007"},{"speaker":"山内委員","kind":"質問","question":"たしか、一部開放するという話がございましたよね。それとの兼ね合いというのはどうなるんか尋ねました。","respondent":"松代管理工事課長","answer":"今の１.４haぐらいの面積の中で、今、検討されています。その設計等につきましては、今回の調査委託をかける中で、もしくは、私ども直営部隊で、設計等は進めたいと、このように考えているところです。","id":"exchange-008"},{"speaker":"山内委員","kind":"意見","question":"だけど、今の答えだと、二重投資しますよと言っているようなものだと思うんですよ。その辺について、どう思いますかとの意見を述べました。","respondent":"松代管理工事課長","answer":"それ以外の土地をそのままでいいかということでありますと、やはり２年間、何も人が入れないというのはいかがなものかと。そういった形で、部分的な暫定開放ができないものかというところで、今、進めているものです。","id":"exchange-009"},{"speaker":"山内委員","kind":"質問","question":"その暫定の設計に対しての補助金というものは、つかないんか尋ねました。","respondent":"松代管理工事課長","answer":"そういったものは、つく予定はございません。","id":"exchange-010"},{"speaker":"山内委員","kind":"意見","question":"例えば隣にある戸越体育館、さらには戸越小学校、そして戸越公園があります。いわゆるその地区の本当の意味での防災の公園ならびに避難場所、そういうものというお考えはあるのか、説明を求めました。","respondent":"堀越行財政改革担当課長","answer":"これが基本です。構想としての検討も含めて行っていきたいと、今、考えてあります。","id":"exchange-011"},{"speaker":"浅野委員","kind":"質問","question":"商品の突出取締ほかとありますけれども、この部署というんでしょうか、この項目はどのような業務を実施されているのかというのが１点。そこら辺の件についてお伺いいたします。","respondent":"松嶋交通安全担当課長","answer":"随時実施しているところでございまして、そのときに早急に対応するとか、そういったものでやっているところです。常識を逸脱するようなもの、そういったものについては、厳しい対応にも踏み込まざるを得ないということで考えているところです。","id":"exchange-012"},{"speaker":"浅野委員","kind":"質問","question":"どうしても商品を前に出して、それによりまして、歩行者の安全を確保できない。平成１７年度に比べて２億円弱増加しておりますけれども、こちらの主な増加要因は何だったのか、説明を求めました。","respondent":"藤田道路公園課長","answer":"平成１７年度と平成１８年度の違いといったことですけれども、平成１７年度までは、維持管理についても積極的に進めてまいりました。あるいは樹木等の管理、こういった経費が増加して、約２億円ほどの増になったものです。","id":"exchange-013"},{"speaker":"浅野委員","kind":"質問","question":"清掃、除草等の実施頻度について、お伺いしたいと思います。そして、修繕費も約８,０００万円ほどかかっているんですけれども、主な内容についてお伺いいたします。","respondent":"藤田道路公園課長","answer":"事業実施しているわけですけれども、さらに区民の皆様に喜んでいただけるような維持管理を進めるということで、実施をしたところです。トイレの清掃などについては、毎日清掃を実施しています。","id":"exchange-014"},{"speaker":"浅野委員","kind":"質問","question":"修繕費、８,０００万円ほどかかっていますけれども、その主な内容についてお伺いします。","respondent":"藤田道路公園課長","answer":"失礼いたしました。上下水道、そういった工事を各公園の中で、区民の皆様に喜んでいただけるような形で補修工事を行っているところです。","id":"exchange-015"},{"speaker":"浅野委員","kind":"質問","question":"例えばたたいてやる場合もあるかと思うんですけれども、専門的な、そのような点検ですね。これはどのような項目で、頻度というんでしょうか、どの程度の頻度で実施しているのか、お伺いいたします。","respondent":"藤田道路公園課長","answer":"遊具に限らず、公園施設の点検、これは私ども、日常、管理する中で欠かすことができない項目だと考えています。少し穴を掘って確認するとか、さまざまな形で確認し、安全・安心のために行っているものです。","id":"exchange-016"},{"speaker":"浅野委員","kind":"質問・要望","question":"これは要望です。そのような点検確認をされたのかどうか、お伺いします。","respondent":"藤田道路公園課長","answer":"国のほうでも結構重要に受けとめておりまして、国土交通省のほうから、一斉点検をせよというような指示も出ているものです。区内については、こうした遊具については、なかったということで、確認をしています。","id":"exchange-017"},{"speaker":"浅野委員","kind":"質問","question":"公園は、子どものオアシスであるということも考慮して、これからもしっかりと安全な公園を維持、また管理してほしいと求めました。２回ほど延伸をされて、平成２１年度まで実施をすることになっておりますが、お伺いします。","respondent":"伊勢住環境整備担当課長","answer":"それから、広場の整備は、一定の成果が上がってきていると考えています。特にご高齢の方が多いだとか、あるいは権利関係が複雑だとか、こういうことで進まないということになってあります。","id":"exchange-018"},{"speaker":"浅野委員","kind":"意見","question":"平成１８年度、１,８７０万円の予算がありますけど、また平成１７年度も実績がないということ。これは進んでないということを意味しているかと思うんですけれども、その点の回答をお願いしますとの意見を述べました。","respondent":"伊勢住環境整備担当課長","answer":"引き続き、建て替えの促進につきましては、働きかけるとともに、あと、荏原町等でも、共同化の動き、最近出てきていると思いますので、その辺で……。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは、成果報告書の１４９ページの区営住宅管理費について伺いたいと思います。あわせて、地方公共団体が担う公営住宅の役割とは何なのか、あわせてご説明ほしいと求めました。","respondent":"齋藤住宅課長","answer":"昭和５５年になりまして、そういった方も入れる、こういう形になっております。この住宅が、公営住宅法に基づく住宅です。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"大家さんから出ていってほしいと言われたり、結婚して家族が増えても、とても引っ越すだけの力がない。そういったケースも増えていると思うんですけれども、こうした実態が広がっていることを実感されているのかどうか、伺いたいと思います。","respondent":"齋藤住宅課長","answer":"１００世帯に１.６世帯、住戸としては足りているのではないか、このように考えております。２倍ぐらいですので、そういう意味でいうと、住宅事情は上向いているのかなというふうな実感を持っております。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"長期基本計画の議論も進んでおりますけれども、その中で、具体化することもしっかり視野に入れるべきではないか。そう思いますけれども、いかがか尋ねました。","respondent":"齋藤住宅課長","answer":"低所得者層、住宅困窮者の方に対する住宅施策といいますのは、社会政策の問題でございまして、広域的に解決すべき課題だと認識しています。そこから品川区まで１時間半ほどはかかりますけれども、住宅を確保すること、それは必ずしも難しい時代ではなくなってきたんだです。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問","question":"この視点をなぜ持たないのか、そこを伺いたい。そう思いますけれども、そういう視点は全くないのかどうか、伺いたい。","respondent":"齋藤住宅課長","answer":"荏原のほうには公営住宅が２００戸ぐらいしかありませんので、荏原のほうで２,０００m2ぐらいの土地が出るかと申しますと、なかなか出ません。こういった事情はないと考えています。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"５,０００万円、さらには１億円を超える、あまりにもゆがんでいると思います。１つ、他の区に比べて遜色ないと言いますけれども、２３区の中で、品川区の公営住宅、一体何番目ぐらいになるのか、具体的に教えていただけますか。","respondent":"齋藤住宅課長","answer":"江東区、これらは１０％を超えておりまして、１０世帯に１世帯の方が公営住宅にお住まいです。割合で見ますと、平均が４.２９％になっておりますので、品川区は、真ん中より下ぐらいの数です。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"城南ブロックが２３区の中で下のほうだというのが、区民の願いに照らして、実態に照らしてどうなのかと。他の区に比べてもおくれていると思いますけれども、いかがか尋ねました。","respondent":"齋藤住宅課長","answer":"１６番目ですが、地価が日本で４番目に高い。こういうことから考えますと、戸数、頑張っているんじゃないかなという実感を持っております。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"２００倍を超えたもの、３００倍を超えたもの、それがどういう状況にあるのか。こうした事態が生まれている理由、背景、それをどう考えているのか、説明を求めました。","respondent":"齋藤住宅課長","answer":"募集倍率ということで説明いたします。むしろ、誇るべきことかなと考えております。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"北品川第二は、募集が２戸に対して５６２人ですから、２８１倍。区民の実態がどういうふうに置かれているのか、お考えを説明するよう求めました。","respondent":"齋藤住宅課長","answer":"お子さんが２人いて、５１０万円ぐらいまでの方が申し込めますので、わりと広く申し込めるという状況があります。これが理由だと思います。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問","question":"今話した説明の理由というのは、何か調査をした上で述べているんか尋ねました。","respondent":"齋藤住宅課長","answer":"そのときの国の説明に書いてあったのが、平成８年以降見直しをしていないので、上がってきてしまったと。だから、広く申し込みができるという実態がある、こういうことです。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問","question":"２万円の家賃は安くていいなと、きちんと意向調査というんですか、申し込んだ方々のいわゆる理由ですね。それはしっかりとまずは把握されることを実施すべきではないかと思いますけれども、いかがか尋ねました。","respondent":"齋藤住宅課長","answer":"こういう住宅もございまして、意向調査云々という問題ではございませんで、申し込みをする要件があれば、申し込みができる。それだけのことです。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問","question":"そこについて、申し込みの際に、申し込みをする理由や背景、それはまずきちんと調査すべきではないかと思います。理由の調査といいますか、それについてはいかがか尋ねました。","respondent":"齋藤住宅課長","answer":"答弁、繰り返しになりますが、公営住宅法は、要件がある方が入居できる、こういうものでございまして、意向調査をする考えはございません。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"今後、生活が苦しい、生活の基盤であります住宅に困窮する、こうした区民が当然増えてくると私は思っております。ぜひ区営住宅、都営住宅もあわせて、長期基本計画の中で、よく議論していただき、建設に向けた具体化を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"稲川委員","kind":"質問","question":"１４０ページにあります駅周辺等放置自転車対策事業、１４８ページの木造住宅耐震化経費助成について、お伺いいたします。撤去台数なんですか、前年度が２万８,７７３台ということで、どういう状況なのかを説明するよう求めました。","respondent":"松嶋交通安全担当課長","answer":"これは、有料化後に、それぞれ年２回ほど、放置禁止区域内の放置自転車台数なんですけれども、それは調査をしています。そういった関係で、撤去の台数が増えているということでご理解をいただきたいと思います。","id":"exchange-032"},{"speaker":"稲川委員","kind":"意見","question":"朝のラッシュ時になると、狭い間口のところに一斉に自転車が入っていく状況の中で、非常に危険な状況でもあります。検討をするとか、そういう思いがあるか、説明を求めました。","respondent":"松嶋交通安全担当課長","answer":"確かに地下駐輪場といいますのは、高機能を有する設備、施設でございまして、確かに利用者の利便性向上にはつながると考えています。それ以上に、検討するといたしましても、より極めて慎重にすべき問題かと考えているところです。","id":"exchange-033"},{"speaker":"稲川委員","kind":"質問","question":"次に、交通安全対策費なんですが、ここにもまた啓発という言葉が出てきております。実際、啓発とはどういうことか、説明を求めました。","respondent":"松嶋交通安全担当課長","answer":"交通安全に対する啓発、これにつきましては、いろいろな種類を実施しています。参加型の交通安全教室だとか、自転車教室だとか、いろいろ種々雑多にわたって実施しています。","id":"exchange-034"},{"speaker":"稲川委員","kind":"質問・要望","question":"厳しいという話を何回かお伺いをしたんですが、さまざまな要望とか相談をいただくんですが、お聞かせください。「止まれ」が本当に薄くなっていたりというのが多々見受けられるんですが、その辺を今後どうしていくか、答えるよう求めました。","respondent":"松嶋交通安全担当課長","answer":"それと、白線とか「止まれ」の表示の部分です。確かに薄くなる、見えづらいといったものは、事故防止上、問題があると思いますので、薄いところは、積極的に補正をしていっております。","id":"exchange-035"},{"speaker":"稲川委員","kind":"確認","question":"これはちょっと確認というか、お伺いをしたいのですが、私も一般質問の中でお伺いをしたんですが。診断という部分で５０万円近くかかってしまというのが現状なんですが、そういうご意見をいただいたんですが、その辺はどうか尋ねました。","respondent":"片田建築課長","answer":"そういうことになってくると、一般診断の結果を踏まえて、どこに補強材をどういう形で入れたらいいかということも検討していかなきゃいけない。１２万円の中でやっているのは、行政としてのアドバイス、これを行わせていただいているような状況です。","id":"exchange-036"},{"speaker":"稲川委員","kind":"質問","question":"なおかつ、促進事業のページを出ると、申請に必要な添付書類の中に、精密診断書と書いてあるんですよ。この２つを関連づけると、もちろんホームページもわかりやすくするべきだと思うんですが、いかがか尋ねました。","respondent":"片田建築課長","answer":"確かにホームページがわかりづらいところについては、今後、いろんなご意見を聞いた上で、工夫させていただきたいと思います。基本的には、一般診断の中で、一定の建物の判断が行われるということでご理解いただければと考えています。","id":"exchange-037"},{"speaker":"稲川委員","kind":"質問・要望","question":"地域の人から見れば、そういった支援助成があるということで、積極的にやっている方もいらっしゃいます。そのまま７５万円の支援をしていただいて、自分が１００万円なり２００万円を足せば、促進事業を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"大沢委員","kind":"質問","question":"１４２ページ、東急目黒線に関連して、あと、都市計画道路、そして、１４６ページ、都市開発費で、大崎駅周辺ということで、質問します。１４６ページの大崎駅周辺から伺わせていただきますけれども、大崎駅周辺では、さまざまなまちづくりが行われております。","respondent":"青木都市開発課長","answer":"計画説明をした後に、近隣の方々に説明会を開催したということで、一報をいただいております。ネズミ等の対策については、これまで同様に、各該当する事業者に指導を徹底してまいる所存です。","id":"exchange-039"},{"speaker":"大沢委員","kind":"質問","question":"それと、ご答弁の中で、ネズミの駆除の中で、必要性の基準という文言がありましたが、必要性の基準というのは何かをお教え願えますでしょうか。ネズミの駆除の必要性の基準ということです。","respondent":"青木都市開発課長","answer":"過去において、そういった苦情が寄せられた経験を踏まえて、殺鼠する必要があるということを認識した上で指導しているということでご理解ください。申しわけございません。","id":"exchange-040"},{"speaker":"大沢委員","kind":"質問・要望","question":"まず平塚橋の周辺の補助２６号線の拡幅された場所が一部あるんですが、地域の方、非常に興味を持たれている。これはあくまでも、両方とも、都が主体の事業ではありますけれども、区はどのようにかかわっていかれるのか、説明を求めました。","respondent":"阿部都市計画課長、松代管理工事課長","answer":"補助２６号線の件ですけれども、平成２０年の１月から３月にかけまして、開放していくと。隅切りの部分につきましては、みずほ銀行のところですけれども、そこにつきましては、来年度用地買収をする予定というふうに聞いております。 小山台公園の今後の計画の考え方です。林試の森公園と一体的な整備が一番望ましいということで考えてございまして、このように考えているところです。","id":"exchange-041"},{"speaker":"大沢委員","kind":"質問","question":"２６号線のほうから伺います。おおむね計画には５００ｍということになりますが、またご意思というのがあるのか、説明を求めました。","respondent":"阿部都市計画課長","answer":"計画としては、平塚橋のところは１８０ｍというふうに聞いてあります。隅切りの部分は、来年度買収をして、整備をしていくと聞いてあります。","id":"exchange-042"},{"speaker":"大沢委員","kind":"質問・要望","question":"温度差が２度違いますので、林試の森に隣接している公園の一部、緑地帯としてその特性を生かした場所づくりをしてほしいと求めました。それだけ、ちょっと端的に、答えるよう求めました。","respondent":"伊勢住環境整備担当課長","answer":"これは今年度につきましては、検討案の作成ということになっていまして……。","id":"exchange-043"},{"speaker":"金野委員","kind":"質問・要望","question":"やはり子どもですから、どうしてもあれば、子どもは使うのかな。改修というお話も伺っているんですが、地域住民の方の要望の遊具等々、ご要望を聞いてくださるのかどうか。","respondent":"藤田道路公園課長、松代管理工事課長","answer":"点検を進めているところですので、順次、よりよい形に変えていければなと思ってあります。まずは撤去をせざるを得ないという形で考えてございまして、その準備を進めているところですので、よろしくお願いいたします。 公園側の１ｍほどセットバックをするということで、計画を進めているところですが、説明をしています。遊具も含めた希望等を聞きまして、改修計画の中で実施していきたい、このように考えているところです。","id":"exchange-044"},{"speaker":"金野委員","kind":"質問・要望","question":"これは要望ですけれども、小学生高学年向きというんでしょうか、そのように思います。そういった意味で、このブロック、点字ブロックの総点検というんでしょうか、点検をしてほしいと求めましたが、その件に関していかがか尋ねました。","respondent":"藤田道路公園課長","answer":"そういったことがないように、これは当然頭の中に入れながら、維持管理に努めているところです。もしご指摘の場所、今、若干ございましたけれども、そういった箇所があれば、私ども、早急に点検をし、改善に努めていきたいと考えています。","id":"exchange-045"},{"speaker":"金野委員","kind":"質問・要望","question":"そういった意味からも、このまちづくりの１つとして、点字ブロックの総点検、また、新たに設置していただきたい場所等も要望をしたいと思います。いかがか尋ねました。","respondent":"藤田道路公園課長","answer":"点字ブロック等の点検の関係ですけれども、私ども、当然日々の点検、パトロールを実施しております。そういった中で、いろんな情報を仕入れながら、安心・安全に歩けるまちにしていきたいと考えています。","id":"exchange-046"},{"speaker":"金野委員","kind":"質問・要望","question":"１つ進捗状況、そして、要望をさせてほしいと求めました。るる要望をしてまいりましたけれども、その道路を少し提供するような声も伺っておるんですが、いかがなものでしょう。","respondent":"松代管理工事課長","answer":"もしその辺のところ、手を入れるとなると、西大井広場公園のほうにかなりの影響部分があります。そういったことから、西大井広場公園の改修等、先々、その辺のことを検討しながら、そこの部分も改善したいと思っているところです。","id":"exchange-047"},{"speaker":"渡部委員","kind":"質問","question":"１４１ページの交通安全施設整備事業、１４０ページ、放置自転車対策等について質問します。この会社に対して、区として役員等を出向なりの形で送り込んでいるのかどうか、ひとつ説明を求めました。","respondent":"阿部都市計画課長","answer":"割合ですけれども、発行済み株式に対する割合としては、品川区は１.９１％を保有しています。役員の派遣ですけれども、本間副区長が取締役として就任しています。","id":"exchange-048"},{"speaker":"渡部委員","kind":"質問","question":"役員も本間副区長が入っているということで、割引制度を区として、臨海高速鉄道に持っていくことというのはできないんでしょうか。その辺を説明するよう求めました。","respondent":"阿部都市計画課長","answer":"もう１点、収支を展望しているということでございまして、なかなか困難だとは思います。ただし、その点につきましては、私どもとしても臨海高速鉄道には申し入れをしていきたいと考えています。","id":"exchange-049"},{"speaker":"渡部委員","kind":"質問・要望","question":"特に交通安全施設整備事業等のところでお伺いしたいんですが、さきの一般質問においてもスクールゾーンの時間帯の変更のことをお伺いして。ちょっとお伺いできますか尋ねました。","respondent":"松代管理工事課長","answer":"今、委員ご指摘のとおり、警視庁国家公安委員会がつくる道交法に基づいた標識、それと、我々、道路管理者として設置する標識の２種類があります。ここにありますのは、私どもが設置している標識です。","id":"exchange-050"},{"speaker":"渡部委員","kind":"質問","question":"ちょっとその辺、例えば区のほうとして、道路管理者としてつける標識と警察の道交法上つける標識との違いというのは何かあるんでしょうか。教えていただけますか。","respondent":"松嶋交通安全担当課長","answer":"端的に言いますと、道路管理者がつけるものは、例えば警戒標識とか案内標識、そういったものでございまして、公安委員会がつくるものにつきましては、規制標識です。","id":"exchange-051"},{"speaker":"渡部委員","kind":"質問","question":"進んでいる中で、前回、大井の地区のほうで進んでいるという話を伺いました。荏原地区のほうの状況等、わかれば、スクールゾーンの時間変更等、教えていただけますか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"現在、現実に今進んでいるところは、浅間台小学校と品川小学校、それともう一校が伊藤学園、この部分が進んでいるところです。なお、荏原地区のほうにつきましても、今後、来年度以降に順次実施をしていきたいと考えております。","id":"exchange-052"},{"speaker":"渡部委員","kind":"質問・要望","question":"平成１８年自体、２万８,０００台で、わかりますでしょうか。撤去割合といいましょうか、わかれば説明を求めました。","respondent":"松嶋交通安全担当課長","answer":"割合につきましては、正確な数字はありませんけれども、何度もやっている方は、こちらは把握しております。今現在一番多い方で、８回ということであります。","id":"exchange-053"},{"speaker":"渡部委員","kind":"質問","question":"例えばこれが２回なのか、３回なのか、何か方策を練っているんか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"考えてくださいよと言ったら、ちょっとおかしいんですけれども、これで何回目ですよという話はしております。１回３,０００円ですから、そういった部分はどのように考えているか、そういった状況でやっているところです。","id":"exchange-054"},{"speaker":"安藤委員","kind":"質問","question":"初日も伺わせていただいたんですけれども、東五反田二丁目第２地区と北品川五丁目第１地区とありますけれども、それぞれお伺いしたいと思います。平成１８年度入っていますけれども、１１４億円のうち、どれぐらいが国と都から出ているんか尋ねました。","respondent":"青木都市開発課長、日下部企画財政課長","answer":"そのうち、想定の部分も含んでしまいますけれども、補助金が投入されます予定が５６９億円ほど、総事業費の約１１％強になるかと思います。再開発事業に関する補助金の考え方ですけれども、２分の１が国からの補助金になりまして… ２分の１は国庫、約４分の１になりますけれども、その４分の１を都市計画交付金という形で交付される。そういうような財源構成になってあります。","id":"exchange-055"},{"speaker":"安藤委員","kind":"質問・要望","question":"今年の２月ですかね、「私ども北品川五丁目第１地区市街地再開発準備組合は、このたび開発事業者をまとめました」ともあります。そういった点から、品川区の果たす、強烈に推進するという立場で、相当なお役目を果たしていると思うんですが、そういう認識でよろしいか尋ねました。","respondent":"青木都市開発課長","answer":"大崎駅周辺の６０haの区域につきましては、これは国策にも従う形で、ここについては積極的に推進していくべきであるという方針で指導しておるところです。","id":"exchange-056"},{"speaker":"安藤委員","kind":"質問","question":"この橋をつくったのと事業とこの計画との関係性をまずお伺いしたいのと、なぜこのようなことが可能になるのかというのをお伺いしたいと思います。これをちょっともう少し、どういうことなのか、詳しくお伺いしたいと思います。","respondent":"青木都市開発課長","answer":"３点目として、再開発を進めるに当たって、将来構想を検討していく範疇に入ってあります。再開発事業に合わせて検討していくという段階ですので、土地の高度利用を図りつつ、地区計画制度を活用して現行規制を解除したというものです。","id":"exchange-057"},{"speaker":"安藤委員","kind":"質問","question":"施工主の方が説明に来たのは、都市計画決定前に１回だけ来て、そのときに、どういう計画なのかという、図面などを全く持ってこなかったと。どういった手当て、あるいは認識、お伺いしたいと思うんですけれども。","respondent":"青木都市開発課長","answer":"開発ビル、仮に入居した場合にやっていけないかもしれないというご事情、まさにどこでもある話だと考えています。弁護士も雇ったりして、いろいろ皆さん工夫してやっておられますので、積極的にご相談していただけるのが望ましいのではないかと考えております。","id":"exchange-058"},{"speaker":"安藤委員","kind":"質問・要望","question":"私はよくわかりません。しっかり今求められている策、あるいは高齢者医療費の無料化などに税金を使うべきだと思うんですが、いかがか尋ねました。","respondent":"日下部企画財政課長","answer":"品川区におきましては、すべての施策についてバランスをとりながら、しっかりと進めている。そういう現状ですので、ご理解をいただきたいと思います。","id":"exchange-059"},{"speaker":"渡辺委員","kind":"質問・要望","question":"あるいは、１カ所、１つのスペース当たり、時期が決まっているのか、あるいは回数が決まっているのであるか、お伺いしたいと思います。それともう１点、あるいは民家の木に対しての区民要望も多いかと思いますが、お伺いしたいと思います。","respondent":"藤田道路公園課長","answer":"そういった観点から言うと、全部まとめて同じ時期に切ればいいということではありません。時々、なかなか手が回らないということで、私どもの区のほうでお手伝いをするといったようなケースもあります。","id":"exchange-060"},{"speaker":"渡辺委員","kind":"質問","question":"ご指摘の民地、民家の木に対する、今、お願いという表現がありましたが、こちらは何か条例や法律の関係で、指導を強く言えるケースというのはあるんか尋ねました。","respondent":"藤田道路公園課長","answer":"公道上ではありますけれども、当然、自分のうちの木を管理するのがだれかというような観点に立てば、ご自身で管理するのが当然のことです。一般的な常識の話と重ね合わすと、まずはお願いをしながら、安心・安全に守れるような形での管理をお願いしています。","id":"exchange-061"},{"speaker":"渡辺委員","kind":"質問・要望","question":"関連してお伺いしたいんですが、落ち葉の区民要望というのも、お願いができるのか。この辺を伺いたいと思います。","respondent":"藤田道路公園課長","answer":"昔からですけれども、地域の方々、自分のおうちの前はお掃除をするという形でご協力いただいている人たちも大変多くあります。そういう中で、地域の力と私どもと合わせてきれいな道路にしていきたいと考えています。","id":"exchange-062"},{"speaker":"渡辺委員","kind":"質問・要望","question":"やはり防災の点からも、区民要望、多いかと思います。このまちづくりの会、戸越・豊町地区なんですが、まちづくりの会の主な活動とメンバー構成を伺えればと思います。","respondent":"伊勢住環境整備担当課長","answer":"地域の実情に詳しい方と一緒に区がこの事業を進めるのがいいということで、昨年の１１月２１日に、それと公募で結成されました。今後は、地区計画だとか、あるいは防災活動に資する道路ネットワークの検討等を行っていこうというふうに予定されてあります。","id":"exchange-063"},{"speaker":"渡辺委員","kind":"質問・要望","question":"やはり同様の、歩道という点から、この国文学資料館の跡地で実効性のある整備という要望が出されていると聞いております。広く的確に住民要望が集約されていると考えられますので、平成２０年度からの暫定整備の際で、お考えをお伺いしたいと思います。","respondent":"松代管理工事課長","answer":"私ども、それを十分に踏まえまして、暫定利用に当たって、そのようなことを考えられないかと、今、検討しております。本格整備と二重投資にならないような、そういったことも十分考えながら、計画を練ってまいりたいと考えております。","id":"exchange-064"},{"speaker":"渡辺委員","kind":"質問・要望","question":"春先、お花見の季節ですと、桜への要望なんかも非常に高いと思われます。本当に幅広くなってしまうので、ランキングではないんですが、上位ベスト３ぐらいのものを、比率とともに伺えればと思います。","respondent":"松代管理工事課長","answer":"区立公園、二百十数カ所ありますけれども、高木等も含めて、約４万本ほどあります。上位から椎の木が１,８００本ぐらい、桜が９００本ぐらい、次にイチョウ５００本ぐらいの割合で植えているものです。","id":"exchange-065"},{"speaker":"渡辺委員","kind":"質問・要望","question":"そういった演出も逆にあってもいいのかなと思われます。ぜひそのような方向で、話題になる公園を提供いただければと思いまして、要望として終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"藤原委員","kind":"質問・要望","question":"１４９ページの区民住宅費についてお伺いしますが、建設型と借上型に分けて伺わせていただきたいのと、これから増えていくのでしょうか。予想といいますか、区のご見解をお伺いしたいと思います。","respondent":"齋藤住宅課長","answer":"２５のうち２１は、この３つの住宅に空きが集中しておりまして、半分が埋まりません。これからも埋まらないと思います。","id":"exchange-067"},{"speaker":"藤原委員","kind":"質問","question":"住宅課長からご答弁いただいた３住宅、４０戸ということですが、そうですかとは言えないわけですよね。それと、具体的に区としては、空き室がこういうふうに出たときに、どのような対処をしているのかを、答えるよう求めました。","respondent":"齋藤住宅課長","answer":"２０年間、この間は手放すことも、例えば個人の名義を会社の名義にすることもできない。地域住宅交付金で１,３００万円、持ち出しを少ないようにして、これからも頑張っていきたいと考えています。","id":"exchange-068"},{"speaker":"藤原委員","kind":"質問","question":"結局持ち出しているわけですよね。ちょっと調べたら、４年以上の空き室があるんですけれども、大体この空き室に対して補償額というのは、今までどのぐらいしてきたんか尋ねました。","respondent":"齋藤住宅課長","answer":"去年、空き、最大で３５までいきまして、今年は２７です。年間大体３,５００万円から４,０００万円ぐらい、この４年ですので、掛けることの１億５,０００万円以上は、空き室に家賃補償したです。","id":"exchange-069"},{"speaker":"藤原委員","kind":"質問","question":"この制度は、一体だれのためにあったんでしょうか。その辺についていかがか尋ねました。","respondent":"齋藤住宅課長","answer":"ただ、残念ながら、私どもの区で言うと、３住宅がなかなか設定家賃が高い。近傍よりも高いということでございまして、バランスを欠いている部分がございました。","id":"exchange-070"},{"speaker":"藤原委員","kind":"質問","question":"特優賃の制度をどうにか変えていかなくちゃということが出始めて、どのような形で、どういうふうに具体的になっていくんか尋ねました。","respondent":"齋藤住宅課長","answer":"国は答えませんけれども、地特賃という住宅だったことを知らないで、外していたんじゃないですか。こういうことでありまして、今、２３区を挙げて、使い勝手が悪い制度なので、改善要望をしているです。","id":"exchange-071"},{"speaker":"藤原委員","kind":"質問","question":"ぜひ２３区挙げて、改善してください。どうか尋ねました。","respondent":"齋藤住宅課長","answer":"２３区を代表して、国に改善要望しております。それで、１,３００万円の地域交付金がもしかしたらもらえたのではないかなと考えていますので、引き続き頑張っていきたいと思います。","id":"exchange-072"},{"speaker":"阿部委員","kind":"質問","question":"１４６ページ、これは多分１４０ページ土木管理費、土木総務費の中に入るんでしょうか。あるいは、今後どのぐらい整備をしていくといった、全体の計画というのはあるのか尋ねました。","respondent":"松代管理工事課長","answer":"ここに来まして、平成１３年に、実施計画というもので、数値目標を挙げまして、これまで取り組んでおります。そのときの実施計画の目標は、１,０００ｍを目標にしまして、順次、毎年計画的に進めてまいりました。","id":"exchange-073"},{"speaker":"阿部委員","kind":"質問","question":"先ほどもほかの委員のご質問でありましたが、１つの交差点の中で、どの場所にどのように設置されているかという基準のようなものはあるのでしょうか。１,０００ｍを設置すれば、少なくとも区内の視覚障害を持った方というのは、自由に出歩けるという、そういう基準なんか尋ねました。","respondent":"松代管理工事課長","answer":"次に、横断歩道部分があるところ、それは両方ですから、２カ所つけてまいります。そういった考えで設置しています。","id":"exchange-074"},{"speaker":"阿部委員","kind":"質問","question":"知らない道の点字ブロックというのは、やっぱりわからないのであるというようなお話を伺ったことがあります。そういったようなお考え、ハード整備とあわせてやっていくような、そういった考え方というのはありますか尋ねました。","respondent":"松代管理工事課長","answer":"そういう中で、そこを検討するソフト部隊と一緒になって、どうすればそういったものがバリアフリーにつながるかということを検討しております。そういったことも含めて、今、検討しています。","id":"exchange-075"},{"speaker":"阿部委員","kind":"質問","question":"そのご検討のスケジュールみたいなものがあれば、説明を求めました。","respondent":"上山介護保険担当課長","answer":"施策のメニュー等を検討しておりまして、今後、１２月ごろをめどに計画の概要のまとめを考えております。これは、案の段階でございまして、それを来年の２月には、パブリックコメントを実施いたしまして、３月末に改定作業を終えたいと考えております。","id":"exchange-076"},{"speaker":"阿部委員","kind":"質問","question":"ああいった場所ですから、ほかにはない機能というのができてこないと、どこのまちも駅前は一緒という感じになってしまうと思うんですね。そういった研究機関と地元の産業との交流の場になるような機能、あるいは場所といったものをつくられるような、そんなお考えはありますか尋ねました。","respondent":"青木都市開発課長","answer":"昨年度ものづくり施設の検討ということで、委員ご指摘のような交流施設のようなものを設置していって、検討したものの成果を踏まえて。ものづくり産業支援交流施設、区も積極的に関与しながら、調整を進めているところです。","id":"exchange-077"},{"speaker":"阿部委員","kind":"質問・要望","question":"最後の質問なんですけれども、自転車の通行についてお伺いしたいと思います。この品川区におきまして、自転車の安全通行のためのインフラ整備について、何かお考えをお持ちか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"自転車にとっては、すごくかわいそうな時代になっているのかなと考えています。新たな施策として、新たなと言っても、路側帯の有効活用によりまして自転車の走行空間を確保するということに着手していきたいと考えております。","id":"exchange-078"},{"speaker":"阿部委員","kind":"質問","question":"路側帯の中に自転車の通行帯を確保するということですが、具体的に対象や手法などは決まっているのでしょうか。品川区の場合には、安全策を持って路側帯を使うということを進められようとしているのかどうか、説明を求めました。","respondent":"松嶋交通安全担当課長","answer":"今考えているのは、歩道通行可の部分、そこから車道に自転車をおろそうとして考えております。構造物はちょっと置けないんですけれども、カラー舗装して、要は視覚的な分離対策を実施していきたいと考えております。","id":"exchange-079"},{"speaker":"阿部委員","kind":"質問・要望","question":"段差と言ったらいいんでしょうか、ちょっとがたがたっとタイヤがとられやすいような、そんな部分がある。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"武内委員","kind":"質問","question":"８月にアメリカのほうで、ミネアポリスですか、なかなか厳しい状態があると聞いております。橋梁と呼ばれる車道橋と人道橋と言うんですか、これが４８、横断歩道橋が２２の合計７０あるということで聞いております。","respondent":"松代管理工事課長","answer":"それを受けまして、対象となる橋梁の４８橋に耐震化の工事を計画的に進めてきております。３橋につきましても、順次、今、計画を進めているところです。","id":"exchange-081"},{"speaker":"武内委員","kind":"質問・要望","question":"残り３橋ということなんですけど、また国が管理の部分もあると思うんですけれども、この辺についてはどうなっているのか。大体の数とあわせてどれぐらいの割合で大丈夫なのかというのを、わかれば教えてほしいと求めました。","respondent":"松代管理工事課長","answer":"申しわけございません。国と都の管理しております橋につきましては、細かく数字等、把握してございません。","id":"exchange-082"},{"speaker":"武内委員","kind":"質問","question":"平成１９年の予算書には橋梁台帳管理システム作成委託等、１２３万６,０００円ほど計上されていますけれども、区のだけなんでしょうか。それとも、国とか都の、区内にある、こういうのも含んでいるんか尋ねました。","respondent":"松代管理工事課長","answer":"大変失礼しました。国が１６、東京都が１０、品川区が２２ということを把握しています。","id":"exchange-083"},{"speaker":"武内委員","kind":"質問","question":"そうしますと、今質問した橋梁台帳管理システムが平成１９年予算で入っているんですけれども、これは全部管理するような台帳なんか尋ねました。","respondent":"松代管理工事課長","answer":"私ども、管理システム、基本的に品川区の財産をきちんと管理するための把握するシステムですので、そこの中には、品川区の管理する橋等をシステムに入れているものです。","id":"exchange-084"},{"speaker":"武内委員","kind":"質問","question":"都と国の管理の数については教えていただいたんですけれども、自治体よりも、国とか都道府県が管理の橋が非常に危ない。しっかりそれも申し入れていただいて、早急にやっていただくようにお願いしたいと思うんですけれども、いかがか尋ねました。","respondent":"松代管理工事課長","answer":"もしくは東京都が管理する橋、国の管理する橋も、同様に安全というものに対して目を向けていかなければいけないと考えています。東京都、もしくは国のほうに、そういったことを問い合わせまして、十分調査と協議を進めてまいりたいと考えています。","id":"exchange-085"},{"speaker":"武内委員","kind":"質問","question":"続きまして、木造住宅の耐震化経費の助成費に関連して、お伺いしたいと思います。その中身について少しお伺いしたいと思いますが、５４.４％ですか、どういった調査をされたのか。","respondent":"片田建築課長","answer":"５年ごとに行われています土地利用の現況調査、平成１３年に行った後、平成１８年に行ってきてあります。建築確認とか、いろいろなデータがありますので、それをもとに分析させていただいた結果です。","id":"exchange-086"},{"speaker":"武内委員","kind":"質問","question":"目標９割ですか、平成２７年まででも結構ですし、全体で考えているのか。どういう支援をするかはちょっとわかりませんけれども、入っていますので、大体どれくらいを考えていらっしゃるんか尋ねました。","respondent":"片田建築課長","answer":"いろいろそういう補助の想定を含めて検討していますけれども、国および東京都の支援制度、その半分を支援していきたい。残りの負担については、国の制度を活用しながら進めていきたい、このように考えてあります。","id":"exchange-087"},{"speaker":"武内委員","kind":"質問・要望","question":"総事業費というんですか、どちらかというと、区民の自主的な取り組みを促進させていくという計画もあると思うんですね。簡易改修についてもどうしていくのかとか、その辺の大まかな考え方がもし出ているのでしたら、教えていただきたいということなんです。","respondent":"片田建築課長","answer":"３分の２といったような考え方も出されてきているところですので、東京都および国のその辺の状況を見据えながら、検討していきたいと考えています。国のほうは検討をし始めている、あるいは耐震シェルター等々についても検討をし始めているですので、このように考えております。","id":"exchange-088"},{"speaker":"武内委員","kind":"質問・要望","question":"お聞きしたんですけれども、どうしても今回、そこまでお金をかけたくないと。９０％というのは、そういう取り組みをしていただきたいなと思うんですが、それについての見解をお伺いしたいと思います。","respondent":"片田建築課長","answer":"確かに私どもが挙げた目標というのは、かなり高い目標で、どこまでできるかという課題は常々考えていきたいと考えています。個人の命を守る上でのシェルター等々についても、いろんな角度から考えていきたい、このように考えてあります。","id":"exchange-089"},{"speaker":"原委員","kind":"質問","question":"こういう分類についてまずお聞きしたいのと、１４４ページの水質調査等委託、まず水質調査自体はどの辺でやっておられるのか。この辺について、この３点、ご説明ほしいと求めました。","respondent":"家壽田下水道河川課長","answer":"以後、今後は、その２に引き続きまして、その３、その４工事というふうに続いてまいります。それから、続きまして、河川水質の調査ですけれども、これは目黒川で、全体７カ所の水質を調査するものでございまして、昨年度実施しております。","id":"exchange-090"},{"speaker":"原委員","kind":"意見","question":"そうしますと、「等」というのは便宜上ついているという解釈でよろしいわけですよね。平成１９年度４,８００、約５,０００万円ついておりますので、これは水質調査という解釈でよろしいわけですねとの意見を述べました。","respondent":"家壽田下水道河川課長","answer":"目黒川水質調査等委託について補足しますと、平成１８年度におきましては、「等」の中では、立会川の土壌調査の委託を行っています。立会川の環境美化運動の中で、このＥＭ団子の効果を室内で実験したもので、その水質の調査でこの予算を執行しております。","id":"exchange-091"},{"speaker":"原委員","kind":"質問","question":"そうしますと、まず目黒川が、最近ちょっと、私、どうも臭いなと思ったんですが、内容が臭いんじゃなくて、川自体が非常に臭い。片方でかきまぜて、片方で水質調査をやられているという状況について、ご説明いただけますか尋ねました。","respondent":"家壽田下水道河川課長","answer":"そっと水はとっておりますので、基本的にはかき回さないで、現状の調査をしているです。委員ご指摘の高濃度酸素溶解水というものは、そっと川の底に酸素の入った水を戻すということで、浄化の実験を行っております。","id":"exchange-092"},{"speaker":"原委員","kind":"質問・要望","question":"というのは、非常に本当にクレームが多いものですから、河川の場合には、においの部分というのは非常に難しいんですね。これについてちょっとお伺いしていきますけれども、今の段階としては、そういった問題等に関しましてご意見をちょうだいできればと思うんですけど。","respondent":"青木都市開発課長","answer":"１４６ページの目黒川親水護岸設計委託というところで載っておりますけれども、目黒川の左岸、東五反田二丁目に今後、親水広場を整備してまいります。護岸を低くするものですけれども、あわせて、防災用の船着場の設置を現在検討しております。","id":"exchange-093"},{"speaker":"原委員","kind":"質問・要望","question":"地元の人の意見をくまなく、細部にわたるまで聞いてほしいと求めました。区も当然、この辺との関連関係はどういうふうになっているか、もう少しご説明ほしいと求めました。","respondent":"青木都市開発課長、家壽田下水道河川課長","answer":"原則的に、広場として整備されたものについては、区が管理責任を持つものとご理解いただいて間違いないかと思います。現段階ではまだ事業者中心ですけれども、新たにお住まいになる方々… 河川法の第１０条によりますと、目黒川は２級河川ですけれども、この管理は当該都道府県が行うことになっております。我々が行うこととなっております。","id":"exchange-094"},{"speaker":"原委員","kind":"質問・要望","question":"いろいろな現場のほうで調査をやっておられるのを確認いたしましたので、それからあとは、測量技術においては世界的にトップです。この３点、今後においてぜひとも進めていっていただきたいんですけれども、ご意見をいただければ。","respondent":"青木都市開発課長","answer":"１つ、研究関係の方々とのいろんな主体の協力関係というのは今後行政の課題になってまいりますので、そういった視点で積極的にいろんなまちづくり全般について取り組んでまいりたいと思います。","id":"exchange-095"},{"speaker":"井上委員","kind":"質問","question":"そして、１４２ページ、東急目黒線立体交差事業について伺います。その辺についてもお伺いいたします。","respondent":"伊勢住環境整備担当課長","answer":"ちょうど平成１８年度の予算編成時期、平成１７年の秋ごろなんですが、これらの問い合わせに対応するために予算措置をしたものです。２行の短い記事ですけれども、支援のこと、そういうところでも積極的にお知らせをしている。","id":"exchange-096"},{"speaker":"井上委員","kind":"質問","question":"もっと使いやすい、住民側の立場に立った制度となるかと思いますけれども、その辺の見解はいかがか尋ねました。","respondent":"伊勢住環境整備担当課長","answer":"登録している以外の人はもちろんできませんけれども、もしそういう方がいらっしゃれば、まずは登録していただく。もしそういうことがあれば考えていきたいんですが、ちょっと今、考えてございません。","id":"exchange-097"},{"speaker":"井上委員","kind":"質問・要望","question":"その期間、どうぞ使ってくださいだけではなくて、そういうふうな区民の視点に立った柔軟な対応もひとつこれから検討していただきたいと思っています。それはきっと２００６年度の実績見合いということで、今回の場合でいうと、来年度の予算の見通しなどはどんなふうにお考えか尋ねました。","respondent":"伊勢住環境整備担当課長","answer":"確かに平成１８年度は大変多くの問い合わせがございまして、平成１９年度につきましては若干減ってというような形で、判断したいと思います。こういうスタンスで編成していきたいと考えています。","id":"exchange-098"},{"speaker":"井上委員","kind":"質問・要望","question":"専門家として提供してほしいと思うんですけれども、私たちも区民の皆さんと話をする中で、利用勝手の悪いものというのはあると思うんです。全体の品川区の考えとして、全体のこととしてぜひ副区長にお伺いできればと思うんですが、いかがか尋ねました。","respondent":"伊勢住環境整備担当課長、福田企画部長","answer":"それを契機にまちづくりを考えるといった場合に、地域でどういうふうになっているかとか、そういうのはきめ細かく対応しています。固定的にこういうふうには考えてございませんけれども、今のところは、きめ細かく対応しています。 我々は考えておりませんで、これでいいんだろうかということの問題意識、これは持っております。このことを原点に据えて考えてまいりたいと考えています。","id":"exchange-099"},{"speaker":"井上委員","kind":"質問・要望","question":"そこのところでは、どういう要望があって、なぜそういう声が上がっていくのだということをぜひ一緒に考えてほしいと求めました。それで、次に、新・水とみどりのネットワーク構想検討経費についてお伺いいたします。","respondent":"松代管理工事課長、家壽田下水道河川課長","answer":"平成１８年度に新・水とみどりのネットワーク構想のための検討ということで、調査をしました。調査・検討を主にやる予定でございましたけれども、調査をするということで、金額を計上したものです。 昨年度は水とみどりのネットワークの中で、目黒川にどういう施設をつければ水質が改善されるかということのシミュレーションー等を行っております。そうした経費も今回の決算の中には含まれております。","id":"exchange-100"},{"speaker":"井上委員","kind":"質問","question":"ということは、２,１００万円の中で、この内訳ということで、その後、水とみどりのネットワーク構想をつくるに当たってコンサルタントが入っているかと思うんですけれども、その辺の経費の内訳を一緒に説明を求めました。","respondent":"松代管理工事課長、家壽田下水道河川課長","answer":"今、委員からもお話がありましたように、私どもの水とみどりのネットワーク構想のための調査費が、先ほどの金額、７５０万円でございまして、目黒川の水質等の関係の金額が先ほどの金額です。 目黒川の浄化検討として、１,３５０万円です。","id":"exchange-101"},{"speaker":"井上委員","kind":"質問・要望","question":"それで、決算が２,１００万円になっていて、なおかつここにはネットワーク構想検討経費と書いてある。この２,１００万円の決算がどういうふうな、その辺のことをお伺いしたのと、その辺を説明していただきたいと思ったんですけど。","respondent":"松代管理工事課長","answer":"目黒川、立会川運河というのがありますけれども、目黒川の水質浄化を主な手法の１つとして取り入れたい。新・水とみどりのネットワーク構想検討経費、２,１００万ということを計上しまして、合わせて２,１００万円の執行となったわけです。","id":"exchange-102"},{"speaker":"井上委員","kind":"質問・要望","question":"これは中間案ですから、具体的な施策について予算が分かれているということは、おかしいと思います。そこについて答弁をいただきたいんですけれども、入り口でちょっとよくわからないので、その辺についてだけきちんと説明を求めました。","respondent":"松代管理工事課長","answer":"平成１９年度の計上ですけれども、緑化推進のところに緑の行動計画検討委託ということで、平成１９年度の予算書の中には計上しているものです。平成１９年度に進めるべき構想といいますのは、要するに今後、どういうふうにすればいいのか。","id":"exchange-103"},{"speaker":"高橋委員","kind":"質問","question":"１４３ページの道路橋梁費の中の受託事業費という、先ほど目黒川の話が少し出たんですけれども、受託事業費というのは、どのような性格のものなんでしょうか、説明するよう求めました。","respondent":"家壽田下水道河川課長","answer":"下水道河川課のほうで所管しております受託事業の内容でご説明申し上げますと、全額都のほうからお金をいただいてやっております。ですから、それを受けてやりますので、受託という言葉を使っております。","id":"exchange-104"},{"speaker":"高橋委員","kind":"質問","question":"とすると、今、都のほうでお金がもらえるのは、この４つのうちのどれになるんでしょうか。目黒川の排水施設建設事業はそうだとは思うんですが、すいません。","respondent":"岩田まちづくり事業部長","answer":"例えば９０％の助成事業であれば、残りの１０％、区が全部工事を行う。こういう性格のものです。","id":"exchange-105"},{"speaker":"高橋委員","kind":"質問","question":"ということは、この区が受託をそれぞれしているんですが、メリットというのはどの点にあるんか尋ねました。","respondent":"松代管理工事課長、家壽田下水道河川課長","answer":"そうしますと、騒音・振動、工事による被害がといいますか、ご迷惑をかけるのが１回で済みます。そういったメリットがあります。２３区、品川区のほうの優先順位のポイントが上がってくるようなところも、実際の側面としてはあります。","id":"exchange-106"},{"speaker":"高橋委員","kind":"質問","question":"この中で、金額が多いものとして、今、排水施設建設事業があるんですが、支出のほうの金額が１１億４,８００万円。収入がたしか１２億２００万円ぐらいなんですが、収入のほうが多いわけでありますけれども、この差はどうなるんか尋ねました。","respondent":"家壽田下水道河川課長","answer":"先ほどまちづくり事業部長のほうからもご説明したと思いますけれども、それで受託事業収入のほうが上回っているです。通常、当区で受託しております工事の場合、細かくいろいろあるんですが、おおむね６％の事務費を上乗せしていただいております。","id":"exchange-107"},{"speaker":"高橋委員","kind":"質問","question":"「等」がついてないんですけれども、上の２つは「等」がついているんですが、これはどのようなことが含まれるんでしょうか。一般のマンションなどの管理というような感じで受け取ってもよろしいのか尋ねました。","respondent":"齋藤住宅課長","answer":"１４９ページを見ますと、気持ちが違いますので、お許しをいただきまして。その委託料を積み上げたものがその金額になるです。","id":"exchange-108"},{"speaker":"高橋委員","kind":"意見","question":"区営住宅が２４万８,０００円、区民住宅の借上式が７万３,０００円、建設型が３７万６,０００円。このように比べることがどうか、どういう評価をされているのか、お願いしたいと思いますとの意見を述べました。","respondent":"齋藤住宅課長","answer":"電球を取り替えたり、こういった共益費の部分をやっておりまして、そこで差が出ます。民間と比べてどうかですが、基本的に三井不動産、民間と比べても極めて遜色のない水準でサービスを提供させていただいていると考えています。","id":"exchange-109"},{"speaker":"高橋委員","kind":"意見","question":"指定管理者制度を否定するわけではありませんが、モニタリングのシステムも導入されておりますので、今後も適切な管理をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-110"},{"speaker":"若林委員","kind":"質問・要望","question":"平成１９年度の統計がちょっと手元、最近の街路樹の植栽というんでしょうか、ここら辺の増があまり見当たらないように思っております。街路樹の全体の計画というんでしょうか、マニュアルみたいなのがあると思うんですが、そこら辺のお話を伺いたいと思います。","respondent":"松代管理工事課長、藤田道路公園課長","answer":"新しく植わるところは、都市計画道路として今後整備する予定のところ。こういった流れです。 基本的には、東京都のほうでつくっているマニュアルがございまして、これに基づくような形で行ってあります。そういったものも参考にしながら、区のほうでは、その現場現場に応じた形での対応という形でやらせていただいております。","id":"exchange-111"},{"speaker":"若林委員","kind":"質問・要望","question":"そうしますと、区道のほうでは、もうこれ以上増える余地はないというふうに今お聞きいたしましたけれども、確認をします。区のほうからご要望するとか、区と都ではこういう計画を立てていますというところがあれば、お知らせをほしいと求めました。","respondent":"松代管理工事課長","answer":"オリンピック誘致だとか、いろいろとそういった将来を見込んでまちづくりを進めたいということで、緑化等を広げたいという考えを聞いてあります。そういった対応をしながら、管理しています。","id":"exchange-112"},{"speaker":"若林委員","kind":"質問・要望","question":"改めて伺いたいと思うんですが、剪定の仕方について１つご要望がありまして、これをどういうふうに設定されているかということなんです。その改善点について教えていただきたい。","respondent":"藤田道路公園課長","answer":"安全な通行が図れないというような形になりますので、ベースはその２.５ｍまで下枝は落としてしまうというのが基本の管理になります。管理されていると思いますので、補助２６号線の街路樹の管理については、私どものほうからも東京都のほうにお話をしておきたいと考えています。","id":"exchange-113"},{"speaker":"若林委員","kind":"質問・要望","question":"新しい道が、補助４６号線という言い方でいいんでしょうか、ここのバリアフリーがちょっといかがかなという地域の方からご指摘がございました。これについて、またはその策定等もありますが、区内のこういう障害者の方に対するバリアフリーの考え方を確認させてほしいと求めました。","respondent":"松代管理工事課長、松嶋交通安全担当課長、阿部都市計画課長","answer":"５％の勾配で、その状況によっては、５％以上の勾配がある。そういった改修にあわせて、少しでも車いすの方、加えて… 高齢者、障害者に対応するために、ボタンを押すと青秒数が延伸するシステムの信号があります。したがいまして、そういった場所であれば… ４６号線の件ですけれども、委員ご指摘のところは、街路整備が終わっている部分だろうと思います。","id":"exchange-114"},{"speaker":"若林委員","kind":"質問・要望","question":"区と都ということで、当然地域に密着した区の考え方が都の考え方に優先すると理解しておりますので、今後都への要望と、また策定の中でも、国と都と区の３者の連携で、円滑にバリアフリーのまちづくり、ユニバーサルのまちづくりが前進しますように、お願いを申し上げまして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-115"},{"speaker":"鈴木（真）委員","kind":"確認","question":"これは平成１８年の予算特別委員会で質問させていただいて、もう一度確認なんですが、どのような経過状況になっているかということを教えてください。それから、指導状況というのも説明を求めました。","respondent":"松代管理工事課長、家壽田下水道河川課長、青木都市開発課長、松嶋交通安全担当課長","answer":"今後も港湾局と十分連携を図り、一般区民の方への開放、また水辺ラインとしてよりよい形になるように協議を進めていきたいと考えています。… やはり用地確保が難しいということで、できればなるべく緩やかな護岸の傾斜にしたいところですが、これがどうしても直立的な護岸になってしまうです… 過去３年にわたって検討してまいりましたＪＲと共同でやってきたまちづくりの検討ですけれども、最終結論ではないんですが、正直申し上げますと。","id":"exchange-116"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１４８ページの中高層建築物開発指導費についてお聞かせほしいと求めました。そして、全世帯に占める単身住宅の割合について教えていただきたい。","respondent":"齋藤住宅課長","answer":"平成１４年からワンルームの戸数が増えてまいりまして、平成１７年が３９棟で、１,８０４戸です。併設型とワンルーム型は、うちのほうで統計をとっておりませんので、単身型が幾つかと、こういう数字は、すいません、把握してございません。","id":"exchange-117"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"品川区はその規制についてどう考えているかということでお聞かせいただきたいんですが、そのことを１つお聞かせいただきたいのと、２３区で。そしてまたその中身についても、区として把握しているところがあったら、教えてほしいと求めました。","respondent":"齋藤住宅課長","answer":"９区ございまして、先ほど委員からご指摘のありました荒川区を契機に、４、５区、規制をする方向で検討していると聞いております。規制をすることは検討していないかですが、適正に誘導する方向では考えてありますが、総量規制という考えはございません。","id":"exchange-118"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひファミリータイプで定住というのが地域の強い要望なんですけど、週５日、ぜひ管理の規定もしっかりとしていただきたいということが２つ目。多分２５m2というのが出ていると思うんですが、ぜひ２５m2以上という形にしていただきたいなと思うんですが、いかがか尋ねました。","respondent":"齋藤住宅課長","answer":"こういう意味で考えますと、それは重要なことだと認識しています。これは今、十分検討しておりまして、近々、きちんとしたものをお示しできると考えております。","id":"exchange-119"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ地域の方の要望が入れられる改定をぜひお願いしたいということと、荒川区に私もお話をお聞きしたんですけれども、その要綱でつくられていたと。今回条例にしたというお話もお伺いしたんですけれども、よろしくお願いしたいと思いますが、ひとつお聞かせほしいと求めました。","respondent":"齋藤住宅課長","answer":"説明をする本体自体がない。説明会も、休日を含めてやらせていただいていますので、引き続きご指導します。","id":"exchange-120"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"１棟売りのことを禁止するというのではなくて、１棟売りをしたときに、それを条例の中に入れられないかというところだったんですね。条例をつくっている区が既に９区あって、本当に住民の大変な実態というのがありますので、ぜひ住民の立場からよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-121"},{"speaker":"石田（慎）委員","kind":"質問","question":"私のほうからは、成果報告書１４２ページ、一番下の商店街電線類地中化事業についてお伺いをします。決算と予算額がそれぞれ出ているんですが、この内容と、現在までの品川区においての電線類地中化事業はどのように行われていたのか、説明を求めました。","respondent":"松代管理工事課長","answer":"補助１６３号線、補助２０５号線、そういった都市計画街路で進めております。商店街の活性化を支援するということとあわせて、また、防災機能の強化といった目的で進めているものです。","id":"exchange-122"},{"speaker":"石田（慎）委員","kind":"意見","question":"この１００％というのは、緊急用車両などが、電柱等が倒れたことによって邪魔になってしまう。もし展望というか、今後のお考えがありましたら、説明を求めました。","respondent":"松代管理工事課長","answer":"加えて、今後の予定としましては、滝王子通り、これは避難道路として位置づけられています。４回ほど説明会を開いておりますが、道路幅員を少し広げ、そういう中で電線類の地中化をあわせてやる。","id":"exchange-123"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"その影響で電柱が倒れたと伺っていますが、重点地域を決めていただいて、その中で地中化を進めていただければなと。これはあくまで要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-124"},{"speaker":"松澤委員","kind":"質問・要望","question":"道路新設改良費に入るのでしょうか、国の緊急対策踏切というんでしょうか、支出金が出ると伺いました。２,４００ｔの貯留管ができたということで、あの三ツ木公園の周りは大変に地盤が悪いものですから、周りで大変心配しています。","respondent":"松代管理工事課長、浜脇街路事業担当課長、阿部都市計画課長、家壽田下水道河川課長","answer":"そういったものが１つの要件として挙げられております。加えて５カ所、合計１０カ所、対策を講じるということにしたものです。それにつきましては、鋭意、あと１年半という中で、用地取得、あるいは工事等を進めたいということを考えてあります。… 委員お尋ねの２６号線の件ですけれども、事業認可は、確かに委員がおっしゃるとおり、平成２１年度までとってあります。実際のところ… ８月２７日に説明会を開催いたしまして、２時間、予定時間ぎりぎりいっぱいまで活発な質疑をしていただきました。","id":"exchange-125"},{"speaker":"松澤委員","kind":"質問・要望","question":"本当に待ちに待った、４,８００ｔの工事ができましたので、通常の夕立なら大丈夫かなと思いますけど、さらに頑張ってほしいと求めました。お答えをお願いします。","respondent":"松代管理工事課長","answer":"議会からも陳情等、拡幅も含めて、要望等が挙がっているものと十分認識しております。しかしながら、品川区としては、今年度１０カ所やる、その踏切の次には、ここを何としてもやりたいということで、今、交渉を続けているものです。","id":"exchange-126"},{"speaker":"西本委員","kind":"質問・要望","question":"１４１ページの街路樹整備費と、それから区民住宅費についてお伺いいたします。そうすると、今後どういう形で修繕等々をしなければならないのかということについて、お伺いいたします。","respondent":"藤田道路公園課長、齋藤住宅課長","answer":"いろんな状況の中で感じていることがあると考えていますので、まず地域の方々の声をきちんと私どもとしても聞く必要があるのかなと考えています。工事に入りますよというお知らせをいたしますので、その中でいろんな声を聞きながら… 指定管理者が対応し、オーナーが自分で業者を見つけて、直す。こういう関係になっております。","id":"exchange-127"},{"speaker":"西本委員","kind":"質問・要望","question":"そこは区として何かご要望があればとか、そういう樋の清掃等々のところでご要望があればという形で、投げかけをぜひしていただきたいと考えています。もう役割は終わったよというような話であれば、今後これをどういうふうに終結していくのかなというところで、今後の展望をお聞きしたいと思います。","respondent":"齋藤住宅課長","answer":"そのような住宅は、８年後、１０年後になりますので、そのときの住宅事情、品川区、同じように区民住宅として持っていたほうがいいかどうか。これはそのとき、しかるべき時期、しかるべきときに、議会にご相談をしながら決めたほうがいいのだろうと考えております。","id":"exchange-128"},{"speaker":"西本委員","kind":"質問・要望","question":"２０年経ってしまったから、自由におたくのほうでやってくださいよというふうに手を離してしまうというのも、どうなんだろうと思います。区として必要なところは転用するとかというところのことも考えて、進めていただきたいと考えますが、いかがか尋ねました。","respondent":"齋藤住宅課長","answer":"今、委員からあったこともお話をしたいと思います。１０年後、住宅施策との絡みを考えながら、十分にお話をさせていただこうと思います。","id":"exchange-129"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひ、国の制度がどうなっているかということも含めて、十分に話をして、今後も一緒に考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-130"},{"speaker":"三上委員","kind":"質問","question":"時間がありましたら、１４９ページの区営住宅管理費のアスベスト除去費ということでお伺いしたいと思います。現状について、品川区としてはどういうふうに受けとめられているか、お伺いをしたいと思います。","respondent":"浜脇街路事業担当課長","answer":"その中で検討していきたいです。私どものほうとすれば、予定といいますか、やる時期、それについては、早く回答するようにということで、求めているものです。","id":"exchange-131"},{"speaker":"三上委員","kind":"質問","question":"こういうことについても、本当にどう思うのか。もう一度お伺いいたします。","respondent":"松嶋交通安全担当課長、浜脇街路事業担当課長","answer":"私どものほうも全然考えておりませんし、撤去の強化だとか、そういったものもやっているところです。大崎署とこれまで３回ほど、実施するとともに、強化もしていきたいと考えております。私どものほうが、不動前駅については、連続立体の関係で、東急とのかかわりがあるものですから、これまでも協議してまいりました。","id":"exchange-132"},{"speaker":"三上委員","kind":"確認","question":"補助２６号線の平塚橋交差点のところで、今、改良工事を行うという説明がありましたけれども、もう一度、スケジュールの点を確認させてください。２６号線拡幅のことについて。","respondent":"阿部都市計画課長","answer":"午前中にもご答弁申し上げましたけれども、左折レーンにつきまして、２０年の３月までに暫定整備をして、左折レーンをつくるです。隅切りの部分につきましては、平成２０年度に用地買収をして、本格整備に入るというふうに聞いてあります。","id":"exchange-133"},{"speaker":"三上委員","kind":"質問","question":"平成２０年の３月までに左折レーンという、その距離というのは、どこまで考えているんですか。みずほ銀行までの買収した土地で考えるのかどうか。","respondent":"阿部都市計画課長","answer":"区域につきましては、みずほ銀行の前のところと、あと、２６号線については、駐車場がありますよね、みずほ銀行の裏のところ。そこの区間というふうに聞いております。","id":"exchange-134"},{"speaker":"三上委員","kind":"質問・要望","question":"とにかく８月の段階で、みずほ銀行とマンションとの敷地の境界確認立ち会いの打ち合わせのときに、今後の話をちょっと聞いたと。そういうような状況の中から、２６号線についても、平成１７年の１０月ですか、初めて住民説明会をやった。","respondent":"阿部都市計画課長","answer":"確かに委員がおっしゃるとおり、地域の方々の協力がなければ進まない事業ですので、私どものほうからも、第二建設事務所に対して、住民の方に丁寧な説明をするように求めてまいります。","id":"exchange-135"},{"speaker":"須貝委員","kind":"確認","question":"私は、１４７ページ、建設費の建築確認申請と１４５ページの公園新設改良費についてお聞きしたいと思います。建築確認、そして検査の厳格化を大きな柱とする建築基準法等の一部改正が行われましたが、これはどういうものなのか。","respondent":"片田建築課長","answer":"７月から９月の末までという状況の中では、平成１８年度の同月３カ月間でいきますと、大体５４％ぐらいと。民間に出されたものも含めますと、全体では、前年比の４３％ほど、一応減少してきているという状況です。","id":"exchange-136"},{"speaker":"須貝委員","kind":"確認","question":"法改正によって、書類上の建築確認検査の手続が、今年の６月２０日から変わりました。建築確認審査期間も、従来は区の条例でも２１日間以内で建築確認をおろすという話でしたが、大幅に延びております。","respondent":"片田建築課長","answer":"書類としても、従来は２部ということで、正副受けていたものを、３部と。これは全国的な話ですけれども、このような実態になっているということは、私どもも十分承知しています。","id":"exchange-137"},{"speaker":"須貝委員","kind":"確認","question":"建築確認の、工事がストップされるわけですから、自然と工事日数が延びる。それに対して、品川区として、どのような対応、対策を考えておられるか尋ねました。","respondent":"片田建築課長","answer":"実は、８月９日付で国土交通省のほうから、手続の円滑化についてというような文書が出されてきてあります。区のほうとしても円滑に進めていきたいということで、指導を含めて、対応してきているという状況です。","id":"exchange-138"},{"speaker":"須貝委員","kind":"質問","question":"でも、８月１０日に解説書が出たわけですよね。そうすると、この５０日間というのは、区としてはどのように対応していたのか尋ねました。","respondent":"片田建築課長","answer":"確かに当初の国の説明のニュアンスと、説明を聞きに行ったという部分では、若干当初の法改正の時期とかなりトーンが変わってきてあります。すぐ出しても、処理できないだろうといったような流れの中で、区のほうもいろいろなご相談を受けてきています。","id":"exchange-139"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は、これに対しては本当に憤りを感じております。そして、ちょっとお聞かせいただきたいんですが、今回の法改正で、あくまで見解としてですが、耐震偽装は防げるとお思いか尋ねました。","respondent":"片田建築課長","answer":"ただ、その前の古いプログラムを使うような場合でも、そのプログラムの見方とか、そういうものを含めて、国のほうとしても対応してきている。それを十分確認をしながら、必要なことについては要望していきたい、このように考えてあります。","id":"exchange-140"},{"speaker":"須貝委員","kind":"確認","question":"現場確認、現地確認というのは、実地確認をすれば。この辺、わかる範囲でいいですから、簡単に説明を求めました。","respondent":"片田建築課長","answer":"それをすべて答えてはいるんですけれども、若干私どものほうも、今後進めていかないと見えないところが現実問題として出てきています。今後引き続いて、いろいろな問題について、私どものほうとしても、前向きに受けとめて、必要な対応を行っていきたいと考えています。","id":"exchange-141"},{"speaker":"須貝委員","kind":"質問・要望","question":"仕事は３件抱えているけれども、できないんだという話も聞いております。これについて、どういう状況になっているか、説明を求めました。","respondent":"藤田道路公園課長","answer":"そういったものに対応できるような形での公園整備ということで、ある程度の広さの中で、ますをいっぱいつくりたいんですね。その辺の様子が若干悪いのかなと考えていますけれども、なるべく長く使っていけるように、一緒に管理をしていきたいなと考えています。","id":"exchange-142"},{"speaker":"須貝委員","kind":"意見","question":"地域の人がいろいろ使いやすいような公園にしていただけたらいいのではないかと思うんですが、一言だけ、ご見解を説明するよう求めました。","respondent":"藤田道路公園課長","answer":"皆さんと一緒によりよい管理をしていって、今後も、無償で開放しているという意味でも、大変意義がある公園だと考えていますので、ご理解のほど、よろしくお願いいたします。","id":"exchange-143"},{"speaker":"林委員","kind":"質問・要望","question":"執行率が２２％というふうに書かれているんだけど、なぜ不要になって、こういうところにその数字があらわれていますよというのだけ説明してください。交通安全に対する親御さんへの安心感を与えるためにどういうことをされているのか、説明するよう求めました。","respondent":"青木都市開発課長、日下部企画財政課長、松嶋交通安全担当課長","answer":"２５０億円とかというような話になってまいりまして、今すぐＪＲのほうが率先して開発を進めるということはないということになりそうです。… 成果報告書の１４５ページでまいりますと、２億３,２６２万１,０００円ということで、違ってございました。執行率が２２％で大変低いんですが… そういった中で、安全施設整備を必要な箇所には実施をしています。それと、警察のほうでは、各保育園に行きまして、安全教育を実施しています。","id":"exchange-144"},{"speaker":"林委員","kind":"質問","question":"それから、監査と成果報告書のずれというのは、何ですか、これ。その道路のことだけ説明するよう求めました。","respondent":"松代管理工事課長","answer":"旗の台のコミュニティーゾーンでも、それは実践して、一定の効果を上げています。ですから、必要な箇所があれば、十分地域の方とお話をしながら、進めていけるものと考えているものです。","id":"exchange-145"},{"speaker":"川西委員","kind":"質問","question":"１４５ページの公園新設改良、もし時間があれば、さっきも出ていました街路樹のことについて若干触れたいと思います。最初に、道路台帳の整備と公共溝渠の整備事業、金額が低いんですけど、執行状況について説明を求めました。","respondent":"松代管理工事課長","answer":"そういった関係とあわせて、金額的なものの執行が低くなっていると考えています。水路の管理等をする上で、この経費を持ってございまして、今回はその水路を通路化しようとするものの１路線を計上したものです。","id":"exchange-146"},{"speaker":"川西委員","kind":"質問","question":"整備すべき公共溝渠というのがあると思うんですけど、平成１８年度、何にもしてないということですか。それを伺います。","respondent":"松代管理工事課長","answer":"払い下げ等もしていこうということで、今、考えているところです。そういった作業として進めているものです。","id":"exchange-147"},{"speaker":"川西委員","kind":"質問","question":"道路台帳のほうは、私の聞き方が悪かったんでしょうか。ちゃんとした中身の説明をお願いいたします。","respondent":"岩田まちづくり事業部長","answer":"これは、現在の道路のＬ型から反対のＬ型までがどれだけあるかというのが５００分の１の縮尺図で、きちっと地図をつくって管理をしております。","id":"exchange-148"},{"speaker":"川西委員","kind":"質問・要望","question":"そういう中で１つ伺いたいのは、鈴ケ森公園の拡張用地取得費の中身を説明していただきたい。あわせて、新設公園というのが、この年度はほかに、今私が申し上げたようなほかに何にもないのか尋ねました。","respondent":"松代管理工事課長","answer":"それと、新設に当たりましては、東品川海上公園、今、委員からもお話がありましたように、平成１８年度は新設ということで、設けてあります。平成１８年度の新設公園としては、この１カ所です。","id":"exchange-149"},{"speaker":"川西委員","kind":"質問","question":"もう少し公園の新設というのは積極的にお願いしたいと思いますが、あるいは児童遊園にしたらいいんじゃないかという、いかがでしょうか。ですから、あるいは維持管理、低木というのはどうしてももちが悪いんですよね。","respondent":"松代管理工事課長、藤田道路公園課長","answer":"私ども、公園の設置の基本的な考え方としましては、今現在防災まちづくりを推進しております。これまでも１０カ所ほど、そういった公園をつくっておりますし、今後もまた、適宜、用地等が出れば、購入して、公園として整備するものです。低木の維持管理についてですが、ご指摘のとおり、時期をずらしてしまうと花が咲かなくなったりとか、いろんなことがあります。","id":"exchange-150"},{"speaker":"宮崎委員","kind":"質問","question":"そういう話でしたけれども、また、案をつくっていくということなんでしょうか。そことあわせてまず聞きたいと思います。","respondent":"青木都市開発課長、岩田まちづくり事業部長","answer":"ＪＲは今すぐ開発の見込みはないということをここで初めてご報告したわけですけれども、区としては、過去にもご報告申し上げております。大井町全体に支障がない範囲での道路の位置の検討ともあわせてやってきたものですけれども… この広町の検討は、この３年間、住宅部分を中心とした活用をＪＲとしても将来的にはいろいろ考えていきたい。ありとあらゆるタイプの検討をこの３年間、重ねてまいりました。","id":"exchange-151"},{"speaker":"宮崎委員","kind":"質問・要望","question":"この前の本会議との質問の関係で確認したいんですけれども、現在の助成の７５万円、これは引き上げていくということが必要じゃないかと思うんです。シェルターという考え方が出てきているんだったら、私はもっとここのところも一歩踏み込むべきだと思うんですけれども、お伺いいたします。","respondent":"片田建築課長","answer":"持ち主さんのほうが考えるべき部分と、検討してまいりたい、このように考えてあります。そこをあわせて検討できる要素、あわせて検討できる要素について検討してまいりたい、このように考えてあります。","id":"exchange-152"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そうであるならば、家具の転倒防止なんかも、支援をするということを求めているんです。私はそこのところぜひ、実態調査なんかをやったらどうかと思うんですけれども、考えをお聞かせほしいと求めました。","respondent":"岩田まちづくり事業部長","answer":"これも耐震計画上はカウントはできませんけれども、命を守るというのも１つの大きな柱にしたいということで、今回は計画に載せていただいております。","id":"exchange-153"},{"speaker":"堺委員","kind":"質問・要望","question":"１４７ページの防災生活圏促進事業に関連して、同じ１４７ページですが、密集住宅市街地整備促進事業に関連して質問させてほしいと求めました。このことをお願いしたいと思うんですが、まずこの件について、ご見解をお聞かせいただけますか。","respondent":"松嶋交通安全担当課長","answer":"なお、これは、視覚障害者の方の施設があるとか、よく通るとか、そういった場所につきましては積極的に実施をしています。あるいは大井町の駅前、当然必要な部分だと考えておりますので、これは警察のほうに強く要請してまいりたいと考えております。","id":"exchange-154"},{"speaker":"堺委員","kind":"質問・要望","question":"どうしてもあそこは避けて通れない大事なところですから、こういう願いからお尋ねをしているわけですので、その辺につきましても。そういう視点から取り組んでいただきたい、改善していただきたい、こういうことを要望してきたわけです。","respondent":"松代管理工事課長","answer":"車いすの方でも、スムーズに入れるような幅員等、勾配等をつくったものです。地域の町会等々のお話を聞きますと、非常に雰囲気もよくなったし、きれいになったという声はお聞きしています。","id":"exchange-155"},{"speaker":"堺委員","kind":"質問","question":"あの橋にも何かお名前をつけていただくといいななんて、そんな気もしたんですが、その辺はどうでしょうかね。ちょっと無理な話か尋ねました。","respondent":"松代管理工事課長","answer":"もうしばらく、地域の方々、また利用者の方に、少しずつお声を聞いていきたいなと考えています。３ｌxぐらいあるんですが、もう少しその辺、安心してご利用いただけるようなものを検討したいと思います。","id":"exchange-156"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は、１４８ページ、木造住宅耐震化助成費をやりますが、その前にちょっと確認をしたいことがありますので、２つだけ教えてください。これをわかりながら、拡大しよう、何しよう、ちょこちょこ出していくことが、これをいつまで続ける気なんだというのだけ、教えてほしいなと思います。","respondent":"松代管理工事課長、藤田道路公園課長、片田建築課長","answer":"パブリックコメントを行いまして、そういったものを加味して、基本的な区の整備方針というものを決めます。その間、暫定的な整備とあわせて… そういうような状況の中で、現地現地を判断する中で、これまで対応してきたものです。そういったケースについては、よくよくご近所の方… 平成２７年度、耐震の目標値を決めて進めてありますので、その理想像として９０％という目標値を掲げたものです。","id":"exchange-157"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"もうこれで質問はやめますが、質問の仕方も悪かったかもしれないですが、的確に答えていただきたい。もうこれでやめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-158"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/570060?Template=document&Id=1284#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":121474,"voices":377}},{"id":"h19-20071010-4","meetingId":"h19-c-settlement","date":"2007年10月10日","dateIso":"2007-10-10","committee":"決算特別委員会","time":"午前１０時０３分～午後５時３２分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を170件整理しています。","topics":[{"id":"topic-01","title":"◯本多委員長 おはようございます。ただいまより決算特別委員会を開会いたします。それでは、平成１８年度品川区一般会計歳入歳出決算","agenda":"◯本多委員長 おはようございます。ただいまより決算特別委員会を開会いたします。それでは、平成１８年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"渡辺委員","kind":"質問","question":"そして１５１ページ、１５１ページ、まちの人々に学ぶ授業についてお伺いをしたいと思います。こちらから伺いたいと思います。","respondent":"日下部企画財政課長","answer":"区民インタビューとかいろいろな形をとっておりますが、当然のことながら、そういったものをお聞きした上で具体的な施策に反映をさせていく。長期計画もそうでありますし、そういう視点で今準備を進めているところです。","id":"exchange-001"},{"speaker":"渡辺委員","kind":"確認","question":"はしかるべき立場の方に伺うと、また各所属チーム活動においても、空き状態が多いなどとは現状と大きく異なる。生涯学習の地域スポーツ活動、この点と、少年少女団体の施設利用を現在どのように把握されているかお伺いしたいと思います。","respondent":"富田生涯学習課長","answer":"基本的には１８校の夜間校庭開放している部分についての利用調整を行っているものであり、高齢者、利用いただいている状況があります。学校側の回答はほぼ１００％団体が使っていますよというふうに聞いており。","id":"exchange-002"},{"speaker":"渡辺委員","kind":"質問","question":"やはり片一方といいますか、一方的な情報だと、非常に利用者にも不安を与えることになるかと思います。今のご答弁のように問題ないということであれば、今後も現状から制約を受けたりすることはないと考えますが、この点をお伺いしたいと思います。","respondent":"富田生涯学習課長","answer":"先ほど申し上げましたとおり、こちらのインタビューの内容については、生涯学習課としては確認をしておりませんので、また全体としての利用状況等々を踏まえながら、今後の計画策定を進めてまいりたいと考えています。","id":"exchange-003"},{"speaker":"渡辺委員","kind":"確認","question":"この決算書を見ますと、平成１８年度、４校で展開とありますが、種目を伺いたいと思います。そして決算額で約２００万円ですが、それぞれ１校当たり均等な予算配分なのか、また主な用途は何であるのか伺いたいと思います。","respondent":"河野指導課長","answer":"平成１８年度、いくつかの学校が拠点校となって、周辺校の希望生徒を受け入れながら活動をしています。これは外部指導員の報償費に関する予算でございまして、均等割ということではなく、実際にかかわっていただいた回数等に応じて支払っているものです。","id":"exchange-004"},{"speaker":"渡辺委員","kind":"質問・要望","question":"当然、勤務の時間以外になると思いますが、この善意のボランティアの取り組みに対して、評価という制度は果たしてあるのかどうか伺いたいと思います。ボランティアというお考えでやっているので、あるいは持ち出しという現状が出てしまっているのか、この点を伺いたいと思います。","respondent":"河野指導課長","answer":"特に例えば体育着であるとか、あるいはその種目に使用する道具であるとか、そういうものに対する支援というものはございません。これは公務に準ずるという形で公務扱いにしていますので、公式戦引率に関しましては、旅費等はすべて公費で負担されているです。","id":"exchange-005"},{"speaker":"渡辺委員","kind":"確認","question":"今この合同部活動以外にも全校的に外部指導者の制度が導入されて、いわゆる地域の力を活用するという視点でとても重要なことだと思います。現在ではおそらく１校当たりといいますか、そういったことは年度年度で調整をしておられるのか、その辺をちょっとご確認したいと求めました。","respondent":"河野指導課長","answer":"現在およそ６０名ほどの外部指導員の方にご尽力をいただいております。学校が外部指導員の確保に当たるわけですが、それぞれの状況に応じて予算を執行しているということで、均等割ではございません。","id":"exchange-006"},{"speaker":"渡辺委員","kind":"確認","question":"では１５１ページ、まちの人々に学ぶ授業について伺いたいと思います。どうしても数も多くなってきたり、あるいは年度ごとに実態に応じて予算が考えられているのか、その点を確認したいと求めました。","respondent":"藤森小中一貫教育担当課長","answer":"ただいま、この地域の方々への報償ということで、基本的には１回３,０００円で商品券をお渡ししております。この回数ですけれども、各学校とも２０回という形で統一して学校のほうに配っているという状況です。","id":"exchange-007"},{"speaker":"渡辺委員","kind":"質問","question":"やはり地域によって講師の方の数といいますか、熱心な方が多い地域も当然品川区内、地域差があるかと思います。ぜひとも今後、この実態に即した形で考えられてはどうかと思いますが、いかがか尋ねました。","respondent":"藤森小中一貫教育担当課長","answer":"実際はかなり商品券の配り方というんでしょうか、その３,０００円の中でも、人数によってそれぞれ実態に応じて配分している、お配りしているという状況です。","id":"exchange-008"},{"speaker":"武内委員","kind":"質問・要望","question":"私は、１５０ページの生徒指導対策費と、１５２ページのインターネット活用教育推進事業に関連してお伺いをしたいと思います。今年の４月から生活保護世帯に対して支給されているという中で、どういうことなのか確認をさせてほしいと求めました。","respondent":"古里学務課長","answer":"そういう標準服はその項目に入っておりませんので、これまで対応していない。法の制度等も研究しなければならないと考えておりますので、これから検討したいという旨の回答をさせていただきました。","id":"exchange-009"},{"speaker":"武内委員","kind":"質問・要望","question":"小学校で３,０２５名、また中学校では１,３２９名という方が就学援助、わかれば教えてほしいと求めました。","respondent":"古里学務課長","answer":"この２７.４％という小中通しての率で考えますと、２００人程度が就学援助の対象者ではないかというふうに考えられる。平塚小学校と、それから平塚中学校、この率で申し上げると１５０名程度が就学援助の対象者となっておるかというふうに考えます。","id":"exchange-010"},{"speaker":"武内委員","kind":"質問・要望","question":"２７.４％、全体で４人に１人ぐらいの方が小中学校で就学援助を受けていらっしゃるということで、かなり多いなというふうに感じております。割合というか、率というか、もしわかれば教えてほしいと求めました。","respondent":"古里学務課長","answer":"私どもの就学援助の基準ですけれども、現在のところ、あくまでも目安ですが、生活保護基準の１.２５倍というふうにさせていただいてあります。これも目安ですけれども、２人世帯の場合ですと、２８９万円程度が所得の上限というふうにご案内をさせていただいてあります。","id":"exchange-011"},{"speaker":"武内委員","kind":"質問","question":"そうしますと、今、約１.２５倍ということなんですけれども、この基準というのは、今のお話だと、就学援助で出る項目はそれぞれ国で決まっている。ただ、この就学援助対象になる所得基準というのは、これは自治体によって違ってくる、こういう認識でよろしいのか尋ねました。","respondent":"古里学務課長","answer":"私どものほうは１.２５倍ですけれども、そのほかの区では１.１倍、１.２倍とか、そういう基準を持っているところもあります。１.２６倍というところもあります。","id":"exchange-012"},{"speaker":"武内委員","kind":"質問・要望","question":"その中で出てくるいろいろな課題については、できる限り前向きに対応していただきたいということをまずお願いさせていただきたいんです。いろいろな形で６校構想の中で、こうしたところも含めて積極的に検討していただきたいというふうに思いますけれども、ご見解をお伺いいたします。","respondent":"古里学務課長","answer":"課題はかなりあるような内容なんですが、就学援助の制度の趣旨が、児童・生徒が円滑に義務教育を受けられるようにという、それが制度趣旨です。生活保護世帯への制度化ということも踏まえまして、この制度の趣旨を踏まえて今後積極的に検討してまいりたいと思います。","id":"exchange-013"},{"speaker":"武内委員","kind":"質問・要望","question":"続きまして１５０ページの生徒指導対策費と、１５２ページのインターネット活用教育推進事業、これは関連してお伺いしたいと思います。いろいろ要望させていただいた経緯もありますけれども、どのようにとられているか概略を教えてほしいと求めました。","respondent":"河野指導課長","answer":"すべての学校、特に中学校ですが、セーフティ教室というのを開催しております。インターネットを使った犯罪に巻き込まれない、あるいはそういうような誹謗中傷をしないということにも触れて、あわせて全校で指導しています。","id":"exchange-014"},{"speaker":"武内委員","kind":"質問・要望","question":"１０月１８日に荏原警察署の生活安全課の方を招いて、非常にこういった取り組みをされているんだなということを感じたわけです。どういったものなのかということと、またそうした、そういうケースがこれまであったかどうかというのを教えてほしいと求めました。","respondent":"河野指導課長","answer":"実態があれば、すぐ関係校同士あるいは全学校に情報交換をして防止策を講じるということで、生活指導主任会等では確認しています。なお現在のところ、具体的なそういう被害に遭ったというような報告は、特にこちらのほうにはございません。","id":"exchange-015"},{"speaker":"武内委員","kind":"質問・要望","question":"先ほどの、警察ですけれども、そういった公開講座を開いてやろうという流れなのかなというふうに認識をしております。２ちゃんねるとかですね、いろいろなことで対応していただきたいというふうに要望しますけれども、お伺いして終わりたいと思います。","respondent":"河野指導課長","answer":"なかなか管理しづらいということはご理解いただけていると思います。今後も学校、あるいは家庭とも連携しながら、未然防止に努めてまいりたいというふうに考えております。","id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"１５０ページの教育委員会運営費について伺いたいと思います。今年の３月１５日の教育委員会では、この中で話し合われた特徴、これをまず伺いたいと思います。","respondent":"古里学務課長","answer":"これは、３月に行われている荏原二中の構成母体校への追加ということで行ってきた保護者への説明会、この内容について報告をしたものです。現在、こういうこと、教育委員会としては今後もきちんとした説明をしていくということを申し上げたというふうに記憶しております。","id":"exchange-017"},{"speaker":"南委員","kind":"質問","question":"保護者への意識やスケジュールに配慮が足りなかった点について反省すべき云々。こういうものはどういうことなのか改めて伺いたいと思いますし、そして統廃合を決めたのはいつなのか、これについても改めて伺います。","respondent":"古里学務課長","answer":"地元への説明をしながら周辺校への影響等、いろいろと見ていく中で、構成母体校に追加すべきということを判断をした。最終的には学校説明会の２月９日に初めて発表するという、今後このようなことがないように進めてまいりたいということは申し上げたところです。","id":"exchange-018"},{"speaker":"南委員","kind":"質問","question":"どっちなんでしょうか。明確に答えるよう求めました。","respondent":"古里学務課長","answer":"２月１３日の教育委員会ですけれども、こちらのほうにつきましては、荏原西地区の中学校、改めて荏原西地区一貫校の構成母体校、これを追加する件、これについて協議をさせていただき、この時点で教育委員会としては了承していただいているです。","id":"exchange-019"},{"speaker":"南委員","kind":"質問","question":"決めたのはいつかと聞いているんです。今の答弁で、決めたのは２月１３日だということでいいんか尋ねました。","respondent":"古里学務課長","answer":"荏原西地区の一貫校を設置する、その内容について地域にご説明を申し上げ、さまざまな意見をお伺いをしました。教育委員会としての予算説明等は以前にしてございましたけれども、了承いただいたです。","id":"exchange-020"},{"speaker":"南委員","kind":"確認","question":"正式な手続き上の最終的な判断というのは教育委員会ですから、私も今の説明を聞いて改めてそういうふうに確認しておきたいというふうに思います。そして応募した理由も伺いたいと思います。","respondent":"古里学務課長","answer":"統合にかかわってさまざまな手当あるいは対応策等を行っていく、実証モデルとしてございましたので、それに私どもも手を挙げたです。このような可能性がある中で、国よりそうした事業に対して補助金が出るというふうな情報ですので、私どもはこれに申請をしたです。","id":"exchange-021"},{"speaker":"南委員","kind":"確認","question":"確認をしたいと思います。このところでは教育委員会軽視ではないんか尋ねました。","respondent":"古里学務課長","answer":"私ども学務課の事業予定としてそういうものがあったために、その事業予定に合わせて補助金が出るのであれば、教育委員会の決定ということは。","id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"何回そういう混乱を父母に与えたら、ちゃんとした教訓が酌み取れるんでしょうか。その理由を明確に示していただきたいというふうにむしろ思いますので、ぜひ教育長の、ぜひ答弁を伺いたいと思います。","respondent":"長田教育次長","answer":"この間、定例会の一般質問等にもお答えをしていまして、この検討については区として進めていきますよというような答弁をさせていただいたところです。","id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"さまざまなところに「どうでしょうか」と語りかけをまずしておいて、そしてそういう状況をつかんで、きちんと検討する。この３つが諮問のようなんですけれども、こういう関係の中で、どういうふうに私たちは見ていればいいんか尋ねました。","respondent":"長田教育次長","answer":"これを検討していく中で、地域の中から、今後例えば荏原第二中はどうなっちゃうのか、こういう心配が地域の中から声として出てきた。こういう検討をしてきたわけですから、区民をないがしろにしてこの事業を進めてきたというご指摘は私は当たらない、このように考えてあります。","id":"exchange-024"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、そういう意見があるわけです。出たのであれば、それを踏まえて、こういうふうに意見か出ているけれどもどうだろうかということをなぜ聞こうという期間を持たないんか尋ねました。","respondent":"長田教育次長","answer":"私どもは、そういった話を聞いていまして、そのことを基本に進めてきたつもりです。","id":"exchange-025"},{"speaker":"稲川委員","kind":"質問","question":"私は、成果報告書の１５２ページにあります和楽器による音楽教育、そして１６０ページにありますジュニアリーダー教室についてお伺いをいたします。どういった種類があるのか、大体何校で取り入れてこういうことをやっているのか、説明を求めました。","respondent":"河野指導課長","answer":"音楽の授業の中に和楽器を取り入れた経緯ですが、平成１４年度から完全実施されております学習指導要領の中で、改訂をされたのが始まりです。それから、学年は小学校のほうが５年生、中学校のほうが７年生から９年生を対象といたしまして、すべての学校で実施しています。","id":"exchange-026"},{"speaker":"稲川委員","kind":"意見","question":"他区、本当に実際に三味線１本買うのにも１０万円以上かかるという経費もすごくかかってくるところだとは思うんですが、この１種類だけなのかどうか。お答えくださいとの意見を述べました。","respondent":"河野指導課長","answer":"ある学校で指導したら、こちらのほうから学校のほうにお願いしているのは、主に和楽器の取り扱いということで琴で指導をしていただいているです。もちろん、和楽器には三味線、琴のほかに、尺八でありますとか、笛あるいは太鼓等いろいろな種類があります。","id":"exchange-027"},{"speaker":"稲川委員","kind":"質問","question":"その教える先生というのは、どういった方々がいらっしゃるのか、地域のさまざまな民謡をやられている方がボランティアで行っているのか、はたまたそういう専門の人を雇っているのか、説明を求めました。","respondent":"河野指導課長","answer":"実際に師範ということで、一般の方に指導されている方に委託をして、子どもたちへの指導をお願いしているです。","id":"exchange-028"},{"speaker":"稲川委員","kind":"質問・要望","question":"続きまして、１６０ページのジュニアリーダー教室についてお伺いをいたします。このジュニアリーダーは私も２０年前に、卒業した人たちがどういった形で成果が出ているか、説明を求めました。","respondent":"富田生涯学習課長","answer":"ジュニアリーダー教室は小学校４年生から高校３年生までを対象にしておりまして、特に野外体験等々も含めましてやっていく中で、学校や地域でのインリーダーを育成するということを目的に実施をしてきているものです。","id":"exchange-029"},{"speaker":"稲川委員","kind":"質問","question":"これは先ほど私も申し上げましたように３０年ぐらい前にできたとホームページには書いてあったんですが、もちろん子どもも少なくなっている。派遣していろいろレクチャーをしていくというのが多かったんですが、品川区において、できた当初と比べて何か変わったところはあるんか尋ねました。","respondent":"富田生涯学習課長","answer":"定員等々がもっと多かったというふうに聞いておりますが、現在は１３０人定員ということで実施をしてきております。従前よりもこのリーダー養成講座等を開催するなど、青少年向けのこういったリーダー養成にも力を入れていきたいというふうに思っているところです。","id":"exchange-030"},{"speaker":"稲川委員","kind":"質問","question":"それで、このジュニアリーダー教室、さまざまな市区町村にあると思います。例えば他区とか他県にある、ほかのジュニアとの意見交換会とか交流会というのは、積極的にやられているんか尋ねました。","respondent":"富田生涯学習課長","answer":"２３区すべてではありませんが、実際に２３区の中でジュニアリーダー教室という形で存続しているところは大変少ないという状況があります。青少年委員会が城南ブロック、また東京都のブロックでの、そういった交流という場には参加をしているという状況です。","id":"exchange-031"},{"speaker":"稲川委員","kind":"質問・要望","question":"やはりここで小学校４年生のころから、目上の人との縦のつながり、横のつながりというのをしっかりここで学べると思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"原委員","kind":"質問","question":"それから１５８ページ、１６２ページ、関連して文化センターについてお伺いしたいと思います。","respondent":"高橋幼保一元担当課長","answer":"こちらは国のモデル事業ということで、品川区におきましては第一日野幼稚園が親の子育て力ということで手を挙げて１年間実施した事業です。これは、親子がまた親同士がふれあいながら、そういった機会の中で子育ての向上を図るという目的のもとに平成１８年度実施した事業です。","id":"exchange-033"},{"speaker":"原委員","kind":"質問・要望","question":"まず、期間を過ぎたものは返されているのかということ、簡単で結構ですからお答えいただきたいんですけれども。談合とか、こういった業者というのは専門分野の形になっているものですから、その辺についてなるべく簡単にご説明ほしいと求めました。","respondent":"古里学務課長","answer":"それから駆除ですけれども、害虫の駆除につきましては、毎学年２回定期的に行っております。この業者の契約につきましては、経理課で一般競争入札による契約をしておるところです。","id":"exchange-034"},{"speaker":"原委員","kind":"質問","question":"では、次に１６２ページのプラネタリウムについてお伺いいたします。この辺のところでどんなふうになっていくのかという、そのプラネタリウムについて、まずちょっとご説明いただければと思うんですけれども。","respondent":"富田生涯学習課長","answer":"保育園の方々対象の団体投影というのを実施しているところでございまして、現在は年間およそ５,０００人前後、例年おいでの方々がいるです。もうひと回り大きい、さまざま現在展開されてきておりますので、そういったプログラムも工夫しながら取り入れていきたいと考えています。","id":"exchange-035"},{"speaker":"原委員","kind":"質問","question":"以前、私の一般質問でもお話し申し上げたように、つくるのなら専門的なほうがいいんじゃないですかと。ですから全部、そうすると今度は逆に、これではもう経費がかかり過ぎるからだめだよという形になろうかというふうに推測するんです。","respondent":"富田生涯学習課長","answer":"他の施設等々も活用したプログラムをいかに組んでいくかということが問題になろうと思います。終わりということでなく、大勢の観覧の方々、地域の方々を含めてご覧いただけるようにしてまいりたいと考えています。","id":"exchange-036"},{"speaker":"原委員","kind":"質問","question":"非常に文化センターのこのプラネタリウムの中心を私はぐるぐる回っているものですから。ですから、ちょっとその辺の特化、専門的なところというところでご意見をほしいと求めました。","respondent":"富田生涯学習課長","answer":"プラネタリウムの運営、文化センター全体がそうでありますけれども、運営方法等々については、これからの検討というふうになってまいります。やはり一般の方々に向けての部分というのもあわせ持つ、そういった施設にしてまいりたいと考えています。","id":"exchange-037"},{"speaker":"金野委員","kind":"質問・要望","question":"１５０ページの教育指導費のほうでありますけれども、また教育センターで行われている教育相談についてお伺いします。平成１６年から平成１８年と、この年度でわかれば教えていただきたいんですが、お願いします。","respondent":"河野指導課長","answer":"具体的な人数で申しますと、大体未就学児が約３％ぐらい、それから小学生が約６０％、中学生が３３％、高校生が約６％という割合になってあります。学校生活に関するものが大体５１％、性格行動等に関するものが３３％、精神というような内容になってあります。","id":"exchange-038"},{"speaker":"金野委員","kind":"質問","question":"平成１６年から１８年度の人数の増え方というか変化等は、その点ではどんなものなのか尋ねました。","respondent":"河野指導課長","answer":"平成１６年度から比べてみますと、平成１６年度、１７年度と増加してまいりましたが、平成１８年度については若干下がってあります。教育相談センターに来るまでもなく、それぞれの学校で相談できる機会が増えたからではないかというふうに考察をしています。","id":"exchange-039"},{"speaker":"金野委員","kind":"提案","question":"平成４年のときの予算特別委員会では、去年の平成１８年度の第４回定例会でも先輩よりこのソーシャルワーカーに対しての提案をさせていただきました。平成４年度のときにはその当時の教育長から、去年提案をさせていただいたときには、そのようなご答弁をいただきましたとの意見を述べました。","respondent":"河野指導課長","answer":"必要があれば、専門スタッフあるいは学生スタッフ等の派遣ができますよということで、ご案内もさせていただいているところです。ただ、今後これらの推移を見ながら、必要に応じて検討してまいりたいというふうに考えております。","id":"exchange-040"},{"speaker":"金野委員","kind":"提案","question":"私もいろいろな声をいただきながら提案をさせていただきたい、そのように思っておりますので、進めていただければと再度要望をしたいと思います。今、平成１８年度でこの国のモデル事業として行われているということですが、今後はどのような展開になっていくのか尋ねました。","respondent":"高橋幼保一元担当課長","answer":"子ども側からの支援、そして親側からの支援ということで含めて、今後考えていきたいと思います。その平成１８年度にやった親の子育て力につきましては、やはり地域の中の子育てが大切であるということを再認識したところでございまして、今後。","id":"exchange-041"},{"speaker":"金野委員","kind":"質問・要望","question":"状況を見て、子育てにみんなで支援をしていく環境を、どうかこの事業を展開をしながら進めていってほしいと求めました。続きまして、この幼稚園費の中の預かり保育事業に関してお伺いします。","respondent":"高橋幼保一元担当課長","answer":"この預かり保育についてのご質問ですが、昨年度平成１８年度９月実施の園が４園で、１月実施の園が３園でございました。お母さんたちで、その部分については、幼稚園でも進めていただいて感謝申し上げますというお言葉は聞いているところです。","id":"exchange-042"},{"speaker":"金野委員","kind":"質問","question":"お母さんの都合で、都合というかいろいろなご事情で、この制度が始まって本当に助かるというお声をたくさんいただいているところであります。少ないときは３人だったり、また多いところでは１０人ちょっとということでありますが、説明を求めました。","respondent":"高橋幼保一元担当課長","answer":"２時に大体降園するんですけれども、７園ほとんどですけれども、預かり保育室を設定しています。そして３時ごろにおやつを食べて、それでそのあとも、室内遊びとか園庭遊びということをしている状況ということを伺っています。","id":"exchange-043"},{"speaker":"金野委員","kind":"質問","question":"私立と区立では内容が少しどうなのかなと思ってお伺いをさせていただきましたが、また遊んでいく、縦割りの保育というのでしょうか。内容等、今後の展開がもしあるのであれば、その点をお伺いしたいと思います。","respondent":"高橋幼保一元担当課長","answer":"品川区の預かり保育の今後についてですが、品川区におきましては、幼保一元化推進事業ということの中で、保育園には幼児教育を、幼稚園には預かり保育をしながら、そういった意味での子育て支援、そして親育て支援ということを進めてまいりたいと思っているところです。","id":"exchange-044"},{"speaker":"井桁委員","kind":"質問","question":"私は、成果報告書１５９ページの生涯学習費全般についてちょっとお伺いをしたいと思います。平成１９年度予算が約１３１万円ついておりますが、今後のこの８３運動、そしてＰＴＡの活動について教えていただけたらと考えています。","respondent":"富田生涯学習課長","answer":"８３運動についてですが、今年度の予算につきましては庁有車への８３運動のステッカー、間もなくお披露目ができるかと考えています。ＰＴＡ活動支援事業といたしましては、地区別研修会、また中央研究発表大会等々ということで実施をしていただいているという内容です。","id":"exchange-045"},{"speaker":"井桁委員","kind":"質問","question":"この８３運動、私の家の近所がそうなんですが地域のボランティアの方も参加をしてくださっていますので、ぜひそこからどんどんとパイを広げていく。活発でないところといったほうがよろしいんでしょうか、そういったところがあるといった現状というのは把握をされていますか尋ねました。","respondent":"富田生涯学習課長","answer":"その辺はやはり中心となって進めていく必要があるというふうに考えているところでございまして、８３のロゴマーク入りのパトロールベストを全校いただいて、区としても支援を強めていきたいと考えています。","id":"exchange-046"},{"speaker":"井桁委員","kind":"質問・要望","question":"ぜひ今後とも、この８３運動というのが品川区から広まっていくようにお願いをしたいと思います。１ページ戻りまして、１５９ページのシルバー大学、そういったことがあれば教えていただきたいと考えています。","respondent":"富田生涯学習課長","answer":"最近若干その辺が低くなってまいりまして、平成１８年度は約１.７倍、今年度は１.５倍程度の合格ということでございました。次がパソコン、あとが筆ペンですとか色えんぴつで描こう等々といったところが続いているという状況です。","id":"exchange-047"},{"speaker":"井桁委員","kind":"質問・要望","question":"ということは、定員というのは近年倍率が下がって落ち着いてきているといった状況ということは、申し込み数が少なくなっているんでしょうか。それとも定員数のほうを増員させたのでしょうか、教えてほしいと求めました。","respondent":"富田生涯学習課長","answer":"このところ、一度定員を増やしたことがありますが、現在のところはずっと１３０人、ふれあいアカデミーは変わってきておりませんで、申し込み者が若干減ってきているということです。","id":"exchange-048"},{"speaker":"井桁委員","kind":"質問","question":"私の周りの方も、そういったところで安定して皆さんのやりたい、最初の入り口のところを開いていただくことは本当にうれしく思っています。生徒と呼んだほうがよろしいのでしょうか、事後活動というのでしょうか、そういったものは実際に行われているんか尋ねました。","respondent":"富田生涯学習課長","answer":"３年間のふれあいアカデミーを出た方々中心に、シルバー大学同窓会というのがございまして、こちらの方々も大勢で活動を継続していただいています。そのほか、それぞれ自主グループをつくられて、各地域で活発な活動を展開されているところです。","id":"exchange-049"},{"speaker":"井桁委員","kind":"質問","question":"そのほかスポーツに関しても、いろいろ歩き回るにしても、いろいろな場所が今なかなかとれないといった現状があるみたいなんです。箱をとるというんでしょうか、そういったものに関しては、いかがお考えか尋ねました。","respondent":"富田生涯学習課長","answer":"文化系、スポーツ系、若干異なるというふうには思います。そういった情報交換を進めながら、一緒の活動の、全体の輪を広げていくというふうに持っていきたいなと現在は思っております。","id":"exchange-050"},{"speaker":"中塚委員","kind":"質問","question":"成果報告書の１５１ページの学力定着度調査を中心に、大井ふ頭の野外活動広場について、後半若干伺いたいと思います。あわせて、全国学力テストと東京都の学力テストの対象学年も説明を求めました。","respondent":"藤森小中一貫教育担当課長","answer":"東京都教育委員会が実施しておりますものにつきましては、５年生と８年生が実施対象ということになってあります。文部科学省の実施している学力定着度調査につきましては６年生と９年生が対象となっております。","id":"exchange-051"},{"speaker":"中塚委員","kind":"質問","question":"そもそも私は学年すべて対象にする一斉学力テストは反対ですけれども、いくら何でもこれはやり過ぎだと、私はやめるべきだと思います。小４から中３まで毎年やることにどんな意味があるのか、それぞれのテストに目的の違いがあるのか、説明を求めました。","respondent":"河野指導課長","answer":"それぞれの学年で学んだことをベースに、さらに幅の広い学習内容について勉強していくです。４年、７年という区切りで行っておりますが、それぞれの学年ごとに私は確認すべきであるというふうに考えております。","id":"exchange-052"},{"speaker":"中塚委員","kind":"質問","question":"新聞でも大きく取り上げられていると思いますのでご存じだと思いますけれども、改めて伺いたいのは、足立区ではどういう不正が行われたのか。品川区自身は、その後、何らかの対策といいますか、今後の課題といいますか、どんなふうにとらえているのか説明を求めました。","respondent":"河野指導課長","answer":"品川区の課題ということで申し上げれば、現在、まだまだ学校のほうの分析が不十分なところがあるのではないかという懸念は持っております。","id":"exchange-053"},{"speaker":"中塚委員","kind":"質問・要望","question":"ちょっとお考えを示していただきたいと思うんですけれども、最も多い学年では５回にわたってコピーをした問題を生徒にやらせていたと。テストの点数を上げるためだけに特化した教育、これは私は間違っていると思いますけれども、あわせてお考えを説明するよう求めました。","respondent":"河野指導課長","answer":"それは中塚委員おっしゃるとおり、テストの点数を上げるためだけの目的で、そういうことが行われているということについては私どもも憤りを感じておりますが、品川区の学力定着度調査におきましては、断じてそういうことはございません。","id":"exchange-054"},{"speaker":"中塚委員","kind":"質問","question":"子どもたちのすこやかな成長を願っていきたいと思うんですけれども、その点、お考えを聞かせてください。過去問と言われますけれども、これを子どもたちにやらせていると、そういう例はあるのかどうか説明を求めました。","respondent":"河野指導課長","answer":"学校がそれまで行ってきた教育活動がきちんと子どものほうに意図どおりに指導することができたのかどうかということを振り返るための手だてとして用…点数を競ってどこの学校が１番だ２番だというようなことで競うための学力定着度調査ではございません。","id":"exchange-055"},{"speaker":"中塚委員","kind":"質問","question":"「過去問題については、ただ単に学力テストに向けての練習だけではなく、基礎学力充実のための方法の１つである」と。この議事録では私は読み取れるんですけれども、その過去問の実態はないとおっしゃいますけれども、いかがなんか尋ねました。","respondent":"河野指導課長","answer":"要するに自分の学力を確認するというようなことは、どこの学校でも日常的といいますか、通常行われている学習の１つである。そういうふうに認識しております。","id":"exchange-056"},{"speaker":"中塚委員","kind":"質問","question":"実施前に、普段の授業とは違ってテスト方式のプリント学習が１週間繰り返し行われていたと。教育長自身も学校の中でこういうテスト対策のための授業、プリントが行われていることをご存じなのかどうか説明を求めました。","respondent":"藤森小中一貫教育担当課長","answer":"学校の学力定着度調査に対するねらいという認識が、各学校は、これを知りたいがために学力定着度調査をやっている。２点目の教育長のことについては、問題につきましては教育長の指示を得ながら、毎年実施しているという状況です。","id":"exchange-057"},{"speaker":"中塚委員","kind":"質問","question":"ということは、では、学力テスト前に過去問題をなんでやるんか尋ねました。","respondent":"河野指導課長","answer":"私がさっき過去問題をやることもあると言ったのは、それぞれ目的があってやることがあるということでございまして、学力定着度調査前に過去問題をやっているというふうな発言はしてございません。","id":"exchange-058"},{"speaker":"中塚委員","kind":"質問","question":"１つ伺いたいのは、つもりでないのか、お考えを教えてください。私は絶対にやるべきじゃないと思いますけれども、いかがか尋ねました。","respondent":"河野指導課長","answer":"実際問題としてそういう部分があるということも否定できないのが大変私も残念だと考えています。それから、全国で行われました国の学力調査の結果ですが、学校ごとの結果について、公表するということは考えておりません。","id":"exchange-059"},{"speaker":"中塚委員","kind":"質問","question":"それについてお伺いしたいんですけれども、ここを利用されている方々に伺いましたら、このいわゆるキャンプ場でいいんでしょうか。東京都との折衝の状況とあわせて、利用者からどんな声が上がっているのか、説明を求めました。","respondent":"富田生涯学習課長","answer":"この場についてどうするか、まだ港湾局と結論は出ておりませんが、継続は困難であるというふうに考えているところです。こちらは区内を問わず区外の方々にも、半分程度は区外の方々に利用いただいているような状況もあるです。","id":"exchange-060"},{"speaker":"中塚委員","kind":"質問","question":"その利用団体の方、私が伺ったのはボーイスカウトの方なんですけれども、とても利用勝手がよくて大変喜んでいたと。飯ごう炊飯もできる、こういった代替地をぜひちょっと検討していただけたらと思うんですけれども、いかがか尋ねました。","respondent":"富田生涯学習課長","answer":"２３区の中で、現在２３区でありますのは、江東区立の若洲公園２カ所です。本当に２３区の中で宿泊できるキャンプ場というのは、こういったところの活用をお願いしていきたいというふうに思っているところです。","id":"exchange-061"},{"speaker":"中塚委員","kind":"質問・要望","question":"ただ、今利用として希望が多いのは宿泊もできるいわゆるキャンプ場、宿泊可能なキャンプ場なんですね。ぜひ代替地を東京都とも話し合ってもらうし、それが無理であれば、何とか近くのところで見つけていただきたいと強く要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"山内委員","kind":"質問・要望","question":"私は成果報告書の１５１ページ、プラン２１に関連した小学校における英語学習について、まずちょっとお尋ねをさせてほしいと求めました。その辺について、まず先生に向けたシステムというものがあるのかどうか、ちょっとお尋ねします。","respondent":"藤森小中一貫教育担当課長","answer":"その指導者をどう育成していくのかというようなお話ですけれども、私どもの教育委員会で年間１０回、教員対象の研修会を開催しています。それと、そのＡＬＴと担任がどうやって協力して英語の指導に当たるのかということも含めて研修を充実させているところです。","id":"exchange-063"},{"speaker":"山内委員","kind":"質問","question":"それで、成果がちょっと載っていたんですけれども、児童についての成果を問うたところ、「おおむね満足をする」ということが掲載されていました。将来的にこのような、そのような具体的な、そういう英語を駆使したような仕事につきたいというような子どもたちの答えというのはあるんか尋ねました。","respondent":"藤森小中一貫教育担当課長","answer":"今、今ご案内のように、職業に結びつけて具体的にこういう職業になりたいというような報告は今のところはあまりございません。あるいは世界に出て何か活躍したいだとか、外国人との接し方において積極的に働きかけていこうというような部分の意見は多数出ているかと思います。","id":"exchange-064"},{"speaker":"山内委員","kind":"意見","question":"やはりそうすると、いままで楽しく英語に接していたんですけれども、いよいよここから、僕はそれはすごく大事なことだと思うんです。多少なりともあると思うんですけれども、その辺についてどうお考えなのか、ちょっと説明を求めました。","respondent":"藤森小中一貫教育担当課長","answer":"考えたのがこの小中一貫校教育でございまして、聞くだとか話すだとか、小学校から中学校へどう連携させていくのか。そういうような形で中学校の指導のあり方について、実践を今のところ、しています。","id":"exchange-065"},{"speaker":"山内委員","kind":"質問","question":"教える先生が指導に対して難しいというこの数字、約６０％近く出ているということは、これは非常に大きな問題ではないかと。その辺についての先生に対しての区教委からのフォローみたいなものはいかがなんか尋ねました。","respondent":"藤森小中一貫教育担当課長","answer":"そういった小学校との連携を絡めた部分での指導に変えていくには、やはり時間もかかりますし、そういった研修等も必要かというふうに考えてあります。","id":"exchange-066"},{"speaker":"阿部委員","kind":"質問","question":"前年度が１億５,０００万円ですから相当力を入れているということなんですが、何と言ったらいいんでしょうか。そういった前提でお伺いするんですけれども、そして公立学校の中できちんと教育を受けられる体制を整えているのか、予算も含めて説明を求めました。","respondent":"河野指導課長","answer":"ＮＰＯ法人ＩＷＣ国際市民の会と連携をいたしまして、授業についていかれないというお子さんたちを対象に、それぞれ指導をしています。それから日本語教室２といたしましては、少しずつ授業に適応できるような指導、これはおよそ６カ月間という範囲で実施しています。","id":"exchange-067"},{"speaker":"阿部委員","kind":"質問","question":"そういった中で１万３,０００円、１人あたり時給に換算すると本当に数百円ぐらいになってしまっている状態であるというふうに聞いております。その他待遇というか、活動に対する支援を行うべきではないかと考えますが、いかがか尋ねました。","respondent":"河野指導課長","answer":"このＩＷＣとの連携は、平成元年のころからずっと多大な協力をいただいて継続してきている事業です。外国人の日本語が解せない子どもたちに対するフォロー、今後、ＮＰＯの支援等についても研究をしてまいりたいというふうに考えております。","id":"exchange-068"},{"speaker":"阿部委員","kind":"質問","question":"次に、学校栄養職員についてなんですが、学校栄養職員は、今品川区で何人いらっしゃいますでしょうか。どういった配置の体制になっているのか説明を求めました。","respondent":"古里学務課長","answer":"学校栄養職員の配置ですが、東京都の基準の定めにより、２校に１名を配置をしています。２校に１名ですので、１人の栄養職員が２つの学校を管理をするという状態になっております。","id":"exchange-069"},{"speaker":"阿部委員","kind":"質問","question":"さまざまな仕事が増えてきている中での２校に１人という配置、その中で、学校栄養職員の仕事はなかなか回らなくなっているのではないかと思います。その辺の現状、認識についていかがか尋ねました。","respondent":"古里学務課長","answer":"再雇用職員１名、合計１０名、合計３０名が配置をされております。代行の学校の全体の給食運営にかかわっていく中で、現状、時間がなかなか足りなくなってきているという現状があるというふうに聞いております。","id":"exchange-070"},{"speaker":"阿部委員","kind":"質問","question":"で、調理代行によって、調理員が逆に別の仕事につかざるを得なくなっているというような現状もあると思います。そういったさまざまな状況の中で、今、そういった試みをされているケースがあるというように聞いたんですけれどもいかがか尋ねました。","respondent":"市川庶務課長","answer":"本年、平成１９年４月の定期人事異動の際に、小学校２校ですけれども、学校栄養職員の業務補助ということを職務内容にして、本年３月まで学校の調理現場に勤務しておりました学校給食調理職員２名を配置いたしました。","id":"exchange-071"},{"speaker":"阿部委員","kind":"質問","question":"そのケース、その例の評価といいますか、実際にどのように今思っていらっしゃるか、率直なところを教えてほしいと求めました。","respondent":"古里学務課長","answer":"現在学校に配置されております学校栄養職員と協働しながら、その学校の給食運営、これをスムーズに進めることができて、コラボレーションがとれているというふうに聞いております。","id":"exchange-072"},{"speaker":"阿部委員","kind":"確認","question":"現在やっている方法がそれなりの手ごたえがあるのであれば、今後そういったやり方を増やしていく、広げていく可能性があるのかどうか。今、伺ったところですと、うまくいっているということですので、今後広げてほしいと求めましたが、その辺、確認したいと求めました。","respondent":"市川庶務課長","answer":"その結果、上々の結果が出ていると判断していますので、基本的には現在の調理職員の人材活用策ということで具体的な検討をさせていただきたい。このように考えてあります。","id":"exchange-073"},{"speaker":"阿部委員","kind":"質問・要望","question":"次に、１６２ページの文化センターの関係でお伺いいたします。確認をさせていただきたいんですけれども、この計画に変更がないのか、現状のまま着実にお話が進んでいるのか確認したいと求めました。","respondent":"富田生涯学習課長","answer":"現在検討しているところでございまして、和太鼓対応ということになってまいりますと、特殊な二重三重の構造ということになってまいります。","id":"exchange-074"},{"speaker":"阿部委員","kind":"質問・要望","question":"要望はとまることがなくなると思います。きちんとしたものを最初に１つつくっておくということが最も費用対効果の高いことと思いますので、長い目で見てご検討をお願いしたいと思います。","respondent":"富田生涯学習課長","answer":"先ほど申し上げましたように、そういった太鼓団体の状況等々、またご要望の声も受けとめつつ、重ねて検討を続けたいと考えています。","id":"exchange-075"},{"speaker":"阿部委員","kind":"質問","question":"時間の配分がよろしくなかったんですが、ちょっと戻りまして人件費のところで、特別支援関係の介助員について一言お伺いしたいと考えています。本年度より介助員の見直しをしたと、削る方向であるということを伺いましたが、その意図について説明を求めました。","respondent":"河野指導課長","answer":"品川区では、平成元年より肢体不自由のお子さんを中心に、いわゆる身辺自立の介助ということで介助員制度を設けてまいりました。現在の介助員制度ですと、一人ひとりの子どもに適した支援をするという意図で、それにあわせて介助員制度の検討をしているという状況です。","id":"exchange-076"},{"speaker":"藤原委員","kind":"質問","question":"成果報告書の１５０ページ、義務教育施設整備基金積立金、１５７ページ、学校施設建設費についてお伺いします。１５７ページで学校施設建設費で８０億円余支出しているんですが、考え方もちょっとよくわからないので、この辺について説明していただけますか。","respondent":"日下部企画財政課長","answer":"ただ、財源としてしっかり押さえておかなければいけないものは一定のルールに従って積み立てをするということをまず１つの前提にして出し入れをする。ちょっと長くなりますのでこの辺にしますが、出し入れを進めているという状況です。","id":"exchange-077"},{"speaker":"藤原委員","kind":"質問","question":"中長期的にはちょっとわからないというお話ですが、少なくとも来年度も改修、校舎の改築とか建設というのはあると思うんですけれども、来年度もこの手法でやられていくつもりか尋ねました。","respondent":"日下部企画財政課長","answer":"総計予算主義の関係も含めまして。財源というものがその予算の中で明確になりますので、いままでの考え方を基本にいたしまして出し入れを進めていくということで考えております。","id":"exchange-078"},{"speaker":"藤原委員","kind":"質問","question":"今日は教育費なので、細かくはお伺いしませんが、公共施設の整備基金なんかにおいても、やはりこの基金の出し入れの考え方というのは変わらずにやっていくんか尋ねました。","respondent":"日下部企画財政課長","answer":"例えば耐用年数の５０年を超えるようなものがかなり目白押しで出てまいりますので、こういったものをしっかりと積み立てをして今後に備えていくということで進めてまいりたい、このように考えております。","id":"exchange-079"},{"speaker":"藤原委員","kind":"質問","question":"平成１８年度末で６１０億円ぐらい基金の残高があると思うんですけれども、これからまた改築、建設と出てまいりますよね。結局、目標額といいますか、この基金の目標額というのは何か設定というのはあるのか尋ねました。","respondent":"日下部企画財政課長","answer":"それから、５０年を超えたものの更新時期を考えますと、大雑把に言いまして年間５０億ぐらいはどうしても見ざるを得ない。こういうこともありますので、その辺も見計らいながら基金の活用を図っていくということが基本になろうかと思います。","id":"exchange-080"},{"speaker":"藤原委員","kind":"質問","question":"２３区がとても裕福、中長期的に見て、本当に財政というのは楽観できないと考えています。豊かということがあだになって、いわゆる国がねらってくるという不安もあるんですけれども、その辺についてはいかがか尋ねました。","respondent":"日下部企画財政課長","answer":"そういうものがこれからおそらく遠からず出てまいりますので、それ次第では、しっかりとその辺も含めて備えていく必要があるだろう。このように考えております。","id":"exchange-081"},{"speaker":"浅野委員","kind":"質問","question":"２番目に１５０ページの学校事務電算システム経費、１５２ページ、パソコン借料等について質問します。伊藤学園と第二延山小学校で電波障害対策が挙げられておりますけれども、具体的な内容、対策内容についてお伺いいたします。","respondent":"市川庶務課長","answer":"電波障害の対策につきましては、周辺家屋の調査を行った上で、必要と認められる家屋世帯につきまして、基本的にケーブルテレビによる対策ということで対応してまいっております。","id":"exchange-082"},{"speaker":"浅野委員","kind":"質問","question":"この小中一貫校で、いままで私も日野学園を見学させていただいたんですけれども、新しい取り組みかなと思ったのが屋内プールですね。新しい機能とか、そういうものの計画がございましたらば、お伺いいたします。","respondent":"市川庶務課長","answer":"この違った水深に対応の仕方としては別の方式もあるようですけれども、大分それぞれの方式のメリット、デメリットもあるようです。今後の計画につきましては、それぞれの実情に応じた中で、最も適切な方式を採用していきたいというふうに考えてあります。","id":"exchange-083"},{"speaker":"浅野委員","kind":"質問","question":"それ以外についてはすべて土の舗装というんでしょうか、この土舗装というんでしょうか、どういう舗装なのか。いままで最近改築した学校は、すべてこの土の舗装になっているかどうか、お伺いいたします。","respondent":"市川庶務課長","answer":"今、個々の計画に即して、できる限りの工夫をしてまいりたいというふうに考えてあります。今後そういったことを慎重に調査し、また検討して、素材の採用を決めていきたいと考えています。","id":"exchange-084"},{"speaker":"浅野委員","kind":"質問","question":"もうちょっとお伺いしたかったのは、何もなければ、それとも土のままでそのまま来ているのかということをちょっとお伺いしたかったんです。ここは一時期ベトベトしたような、そういうような校庭だったというふうに伺っておりますけれども、これも土舗装の１つなんか尋ねました。","respondent":"市川庶務課長","answer":"あるいは土と砂ですけれども、こういった混合割合、この辺が実際には微妙に影響してまいります。それで、第二延山小学校の場合につきましては、川砂をまぜた土を追加処理をして、今現在経過を観察しています。","id":"exchange-085"},{"speaker":"浅野委員","kind":"質問・要望","question":"新しい砂も１回やはり飛ばされてしまったようで、結構また古いべたべたの層が出てきたりしていたそうです。そのようなものについてはしっかりと業者のほうに要望しているのか、確認したく、お伺いいたします。","respondent":"市川庶務課長","answer":"その辺の事情を調べた上で今後に生かしてまいりたいと思いますが、必ずその工事に際しては、近隣対策ということは条件に入れているということでご理解をいただければと思います。","id":"exchange-086"},{"speaker":"浅野委員","kind":"質問","question":"それとあとこの費用の内訳なんですけれども、例えば開発をする費用、維持をする費用、また業務委託をする費用、この分類で簡単に内訳をお願いしたい。そしてまた今後の開発計画についてもお伺いしたいと思います。","respondent":"古里学務課長","answer":"それ以外に９００万円弱ですが、システムをサポートするためのシステムサポート経費を委託料として計上しています。今後についてですけれども、事務形態の変更に伴うプログラム変更、こうした小規模開発をしていく経費のみというふうに考えてあります。","id":"exchange-087"},{"speaker":"浅野委員","kind":"質問","question":"続きまして、学校ＩＴ化推進費ですけれども、こちらのほうは８,３００万円で、今年度も１億２,０００万円が予算化されています。なっていなければ今後していくのかどうか、お伺いいたします。","respondent":"古里学務課長","answer":"過去私はそういうふうにした記憶はございませんけれども、公務の合理化ということを行っていく上で使っていくシステムというふうに考えてあります。教員が事務をつかさどる時間を効率的に終了させて児童・生徒の直接指導に当たらせたい、これが運用の基本的な考え方です。","id":"exchange-088"},{"speaker":"浅野委員","kind":"質問","question":"今はちょっと違うということですから、そうではないということなので、こちらはまた別途個別にお話をさせてほしいと求めました。パソコンのＯＳはウィンドウズ、標準ソフトとしてはオフィスが入っているかと思いますけれども、簡単にご答弁願います。","respondent":"古里学務課長","answer":"現在はすべてウィンドウズＸＰのバージョンにそろえてあります。","id":"exchange-089"},{"speaker":"浅野委員","kind":"質問","question":"こちらのほうの本体の、行政のほうもパソコンを４,０００台使われているというのが歳入のところで質問をして回答をいただいております。それが継続してどんどん高くなるというのが今現状だと思いますので、ぜひともこの分のコスト削減に取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"大沢委員","kind":"質問","question":"１５０ページ、１点、ちょっとお伺いしたいと思います。第３については、第１が１９５１年から始まったですが、ちょっとお伺いしたいと思います。","respondent":"河野指導課長","answer":"朝６時半に子どもを迎え入れて、夏休み皆勤だと、最後にノート等をいただいたという記憶があります。夏季休業日中に地域の保護者等が主催して、朝のラジオ体操教室というような形で、子どもたちの参加を呼びかけているというのが現状です。","id":"exchange-091"},{"speaker":"大沢委員","kind":"意見","question":"これについてどのようにお考えなのか。どういうふうにお考えになるか、受けとめられているのか、ご答弁くださいとの意見を述べました。","respondent":"河野指導課長","answer":"昨今、そういうことではなくて、いわゆるストレッチ系の体操というものを取り入れる傾向が非常に強くなってきております。私も、どうしても、今申し上げたようなストレッチ系の準備体操のほうに重点を置く傾向になってもいたし方ないのかなというふうに思います。","id":"exchange-092"},{"speaker":"大沢委員","kind":"質問","question":"伝統といいますか、その継承を、ぜひとも知らない子はないというような状態にできることをお願いしたいと思います。ちょっとそこでお伺いしたいのは、子どもたちがどのようなストレスをためているのか、説明を求めました。","respondent":"河野指導課長","answer":"家族関係におけるストレス、学習等に関するストレス、そんなようなものが一般的に多く取り上げられている現状があります。","id":"exchange-093"},{"speaker":"大沢委員","kind":"質問","question":"スクールカウンセラーの先生方が、子どもたちの心のケアをされているわけですけれども、それはもう既に病にかかってしまった子どもに対してで、かかる以前の予防的なカウンセリングというのはされているのか尋ねました。","respondent":"河野指導課長","answer":"スクールカウンセラーが直接的に子どもにかかわるケースというのは、非常に限定されております。悩んだときの対応等について啓発をするとともに、教員、担任等が指導をしています。","id":"exchange-094"},{"speaker":"大沢委員","kind":"提案","question":"担任の先生の指導、その中で、私ちょっと一つ進言といいますか、ご提案をさせてほしいと求めました。どういうふうな対処の仕方というか、ストレスがたまった場合にどうすればいいかというような教育というか、どのようにお考えになりますかとの意見を述べました。","respondent":"河野指導課長","answer":"子どもたちがストレスをためる場面というのは、個々の状況によってさまざまです。自分たちの体験をもとに、一人ひとりが克服できる、そんな力を育てていくことも教育の大事な役割だと認識しています。","id":"exchange-095"},{"speaker":"渡部委員","kind":"質問・要望","question":"ただ、その地域からの要望というのだけは、どうしても解せないんで、それだけひとつ教えてほしい。保護者の要望等でいろいろ標準服等の更新についてあったと思いますが、この２点、説明を求めました。","respondent":"長田教育次長、古里学務課長","answer":"これを進めるに当たりまして、確かに反対の声もありました。やはり、将来を考えたら、少し教育委員会も考えなければいけないでしょうというようなお話をいただいていたところです。 こうしたものに充ててまいりたい、いわゆる学校指定用品を検討して、この予算を挙げてあります。","id":"exchange-096"},{"speaker":"渡部委員","kind":"質問・要望","question":"一つちょっとわからなかったので教えていただきたいのが、中学校で参加教員の延べ人数がありますが、校外指導というのは何でしょうか。今後、例えば全学校において、保護者の要望等があれば、そちらのほうに対しても開催する準備があるか、どうか、教えていただけますか尋ねました。","respondent":"富田生涯学習課長、河野指導課長","answer":"あわせて、保護者に対しては、家庭教育学級の中で、全校１回ずつということで実施をしたものです。平成１８年度に入りまして、学年を拡大いたしまして、たしか、５年生もということで実施をしてきたです。 校外指導の中の、要するに参加教員延べという中身ですが、各地域の祭礼、あるいは、夏の盆踊り等の地域のそういう夜間に行われる行事のときにパトロールに従事した人数です。","id":"exchange-097"},{"speaker":"渡部委員","kind":"確認","question":"どうなんでしょうか、学校の教育ね、まずくなったんだよ」というような会話がありました。どうかわからないんですけれども、確認もしてないんですが、焼かなきゃいけないのがフライになって出てきたという話も小耳に挟んだんです。","respondent":"古里学務課長","answer":"そして学校、それから入っている民間の事業者の３者で、より質の高いものを追求していくんだということが一番大事なことだろうと思っているんです。それはすべて標準という内容になっています。","id":"exchange-098"},{"speaker":"井上委員","kind":"質問・要望","question":"その中で、５月にも改築計画が発表されたようなので、そのことについて、少しお伺いをしたいと思います。その２点について、お伺いします。","respondent":"富田生涯学習課長","answer":"音楽ホールにつきましては、先ほど申し上げたように、検討してまいりたいと思っているところです。コストをかけなくても十分な音響が確保できると考えておりますので、そういう意味では、さまざまな方に喜んでいただける施設になると考えております。","id":"exchange-099"},{"speaker":"井上委員","kind":"質問・要望","question":"どういう方たちの利用を想定しているのかということを質問させていただきましたので、担当者の職員の皆さんでぜひ検討をしてほしいと求めました。そこに運動器具を入れる倉庫を新たに地下に掘って、設計変更がされるというお話もあるやに伺ったんですけれども、その辺はいかがか尋ねました。","respondent":"富田生涯学習課長","answer":"基本は基本としながらも、従来使ってきた方々のこともありますので、そういった意味では、幅広い活用ができるような方策を検討しているです。そのために、スタジオに倉庫等々ということで、今、考えているわけではございません。","id":"exchange-100"},{"speaker":"井上委員","kind":"質問・要望","question":"会議室があり、そして４階が教育センターというふうに伺っていますので、そうしたコンセプトをぜひ守っていただきたいなと思っているんです。今、運動施設がないということを確認させていただいたということで、よろしいんか尋ねました。","respondent":"富田生涯学習課長","answer":"体育施設なり、スポーツ施設という形で部屋を設ける考えは、今のところ持っていないということでありまして、内容によっては、できるだけ幅広く使えるような場は設けていきたいとは考えております。","id":"exchange-101"},{"speaker":"井上委員","kind":"質問・要望","question":"それを理解した要望に対しては、ぜひ耳を傾けてほしいと求めましたけれども、ぜひ引き続きここを中心にいってほしいと思っているんです。中途半端な建物にしていただきたくないということを要望しますし、広く区民の声を聞いて、その辺はいかがか尋ねました。","respondent":"富田生涯学習課長","answer":"新たな施設を建てる場合には、ほんとうに白いところから絵がかけていくと思っています。改築の場合には、ぜひそちらでというようなことも含めながら、音楽活動を特徴として持った文化センターにしていきたいという基本的な部分は同様です。","id":"exchange-102"},{"speaker":"井上委員","kind":"質問・要望","question":"ぜひ、将来的な財産になるような建物にしていただければということを要望して、次の質問をします。そこで、昨年の各学校の実績を、お伺いいたします。","respondent":"河野指導課長","answer":"平成１８年度におきましては、区内のすべての小学校でＣＡＰを実施しています。対象の学年、３年生と５年生の二つの学年で実施しております。","id":"exchange-103"},{"speaker":"井上委員","kind":"質問・要望","question":"１０回あると思うんですけれども、要望として、研究課題として挙げさせてほしいと求めました。ですから、ぜひ、教師全体に、３年生と５年生だけではないところに拡大をしてほしいと求めましたけれども、その辺のお考えはいかがか尋ねました。","respondent":"河野指導課長","answer":"ＣＡＰの実施に当たっては、必ず大人向けのワークショップということもあわせて求められているところです。３年生、５年生を担任している教員は必ず出席しておりますので、参加できる教員には呼びかけていきたいと考えております。","id":"exchange-104"},{"speaker":"井上委員","kind":"質問・要望","question":"ＣＡＰの中では、だれかにＳＯＳを発することは恥ずかしいことでも何でもないんだということを、やっぱり思春期になった中学生にも知ってほしい。ＳＯＳを出すことも、中学校へのＣＡＰの拡大についての見解が何かあれば、ほしいと求めました。","respondent":"河野指導課長","answer":"強く生きる、ＣＡＰを初めアサーショントレーニングであるとか、さまざまな手法が効果があると言われているところです。ＣＡＰも含めて、さらに効果的な取り組みがあれば、またそのことについて検討させていただきたいと思います。","id":"exchange-105"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"成果報告書の１５１ページにあります、１５２ページにあります、インターネット活用教育推進事業についてお伺いします。これを、決算書を見て、そういった内容のものが載っていなかったので、教えてほしいと求めました。","respondent":"古里学務課長","answer":"したがって、区役所のほうが設置している安全対策、ファイヤーウォールを含めた安全対策の傘のもとにあります。それぞれにセキュリティシステムを構築して運用していますので、両方とも、基本的なセキュリティ対策をとって運用しております。","id":"exchange-106"},{"speaker":"石田（慎）委員","kind":"質問","question":"教師が使うパソコンに関しては、区役所のセキュリティシステムでやっているということなんですけれども、学校でのセキュリティシステムは、どこが管理をしてやられているんか尋ねました。","respondent":"古里学務課長","answer":"それぞれ学校ごとにサーバーを立てて、その中にセキュリティシステムを入れております。このセキュリティシステムのほうは、学務課が業者に委託をしまして、メンテナンス等も含めて運用しております。","id":"exchange-107"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"ぜひ、今後ともしっかりとしたセキュリティシステムを使ってほしいと求めました。インターネットを活用して授業ができる教師は、今、一体どのぐらいいるのか、教えてほしいと求めました。","respondent":"河野指導課長","answer":"ただ、平成１８年度については、同様の調査が、質問項目が変わって、従来の「ＩＴ」という質問形式から「ＩＣＴ」という質問に変わりました。この部分に対する回答は６０％台ということで、ＩＴ化を進めているところですので、参加を呼びかけているところです。","id":"exchange-108"},{"speaker":"石田（慎）委員","kind":"質問","question":"いじめ等の問題もいろいろ質問されているんですが、僕たちの世代もそうなんですが、若い人は特にメールを使って何かを伝える。教師と生徒の間に、例えばメールアドレスの交換等をして、日常的に相談ができるようなシステムというのは、学校ではあるんか尋ねました。","respondent":"河野指導課長","answer":"そういうＩＴの闇の部分でもあるわけですけれども、人目に触れないところでいろいろなことが行われるという部分が、実際問題として起こっております。私どもとしては、むしろ逆に、生徒と教師が、個人的にそういうやりとりがないようにということで指導しています。","id":"exchange-109"},{"speaker":"石田（慎）委員","kind":"質問","question":"ここも質問したいんですが、それを受けた生徒が、実際にどのような成果が出たのか。もしおわかりになりましたら、説明を求めました。","respondent":"藤森小中一貫教育担当課長","answer":"全校で実施をしているというのは、平成１８年度からです。自分から働きかけたりとか、あるいは、かなり日常的に子どもたちに浸透しているなというような感触を得ているところです。","id":"exchange-110"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"聞く話すがなかなかできないという現状ですので、せっかくスタートしたばかりの小学校における英語学習にぜひとも力を入れてほしいと求めました。特にこの成果報告書を見ていても、英語の欄が非常に出ている。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そういう面では、教室の問題は、児童にとって勉強の場ですから、重要な場所なんですけれども、その点、どう対応なさるのか一つお聞きしたい。その効果と、どのような内容までやっていらっしゃるのか、そこの２点を説明するよう求めました。","respondent":"市川庶務課長、古里学務課長","answer":"私から、１点目の学校の施設対応に関連することについて、お答えいたします。その辺は、学校とさまざま協議をしながら、対応をしています。 清掃、植栽の管理、こうしたものをすべて総合的に管理をしてやっております。あるいは予防保全、こうした内容まで含めて、施設の維持管理をするということをやっております。","id":"exchange-112"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ですから、いろいろな面で対応を考えていただいて、児童生徒の授業に対して影響のないように、その辺を、またご検討していただきたい。ある面、自分たちで使うところを掃除するのは当然な話だと思うんですが、そこら辺の考え方も一緒にお聞きしたいと思います。","respondent":"古里学務課長","answer":"生徒自身が自分たちの教室などの清掃を行うということは、生活指導上の問題もあり、やらせているところです。トイレにつきましては、ほかの学校と同様、子どもたちがやっているという状況は、品川区の場合、ございません。","id":"exchange-113"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ちょっとそこら辺が、なぜやらせないのか。児童の衛生という意味なのか、なぜか、特別な理由があるんか尋ねました。","respondent":"古里学務課長","answer":"例えばＯ―１５７などが問題となったとき、いわゆる感染症の問題というのは、学校の保健の上で避けて通れない課題がある。そうしたことから、トイレについての清掃を児童生徒にやらせるという方法を、今、とっていないと聞いたことがあります。","id":"exchange-114"},{"speaker":"鈴木（真）委員","kind":"確認","question":"Ｏ―１５７が出たというところでは、その辺は、教育の中で強調されているんでしょうね。もう１回、確認したいと求めました。","respondent":"河野指導課長","answer":"先ほど、学務課長がご答弁させていただいたように、区としては、そういうリスクを考えて、現在のところ、トイレ掃除はやらせないです。こういうようなことについても、また、さまざまな意見をもとに研究はしていきたいと考えています。","id":"exchange-115"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これまたいろいろほかの場で確認させていただきたいと思うんですが、もう１点、１５０ページの中堅教員研修というのが５人しかないんですよね。なぜ、中堅職員の研修が少なかったのか、その辺を説明するよう求めました。","respondent":"河野指導課長","answer":"中堅教員の研修に関しては、産業能率大学のほうに委託をして実施していただいている研修です。それぞれ研修に参加するに当たりまして、相当高額な予算を必要としますので、予算の関係上、人数を絞らせていただいているです。","id":"exchange-116"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"何校にあるのか、それから、すまいるスクールとしての専用スペースがなくて学校との共用というところはあるんでしょうか。あったら、それも何校なのか、あわせて教えてほしいと求めました。","respondent":"市川庶務課長","answer":"私どもが直接説明を受けたという経過はございませんが、一人当たりの１.６５m2ということに対応した広さを満たしているのか、今現在。","id":"exchange-117"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"すまいるスクールというのは、今回の放課後子どもプランの先取りだったのかなという思いがしているんです。放課後子どもプランに対しての区の考えについても、お聞かせほしいと求めました。","respondent":"市川庶務課長","answer":"国が、学童保育クラブの待機児の解消という課題がかなり重かったように説明を受けております。それから、いわゆる国のナショナルスタンダードというようなことで一くくりにできるのかどうか、この辺は実務的な検討課題かなとは感じております。","id":"exchange-118"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"専任指導員が１人しかいない、安定した職員体制を、ほんとうにきちんと対策をとるということが求められていると思うんです。そういうことに対して、どういうふうに継承していく体制をとっていこうと考えているのか、そのことについてもお聞かせほしいと求めました。","respondent":"市川庶務課長","answer":"１点目の、やっぱりこの事業に対する基本的な認識の部分で、私どもの考えと大きく隔たりがあると感じてあります。それから、専任指導員のノウハウの継承ですけれども、この辺の危惧は、私どもも持っておりますけれども、これは、今後の課題の一つかという認識です。","id":"exchange-119"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"私は、学童保育クラブということであれば、家庭にかわる生活の場というのが必要だと思います。その位置づけをお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-120"},{"speaker":"三上委員","kind":"質問","question":"どうか、仕組み等について、ちょっとお伺いしたい。特に、きょうは教育費でありますので、教育委員会としては、どういうふうな取り組み方をしているのかということで、お伺いしたいと思います。","respondent":"富田生涯学習課長","answer":"教育委員会の後援名義等につきましては、生涯学習課が一番件数が多うありますので、私のほうからお答えをします。３番目の協賛というのは、４番目、委員会が他に薦めるためということで定めております。","id":"exchange-121"},{"speaker":"三上委員","kind":"質問","question":"端的にお伺いします。こういうことについて、ちょっとどうお考えか尋ねました。","respondent":"富田生涯学習課長","answer":"この事業につきましては、最初が「どどっと遊ぶデイ２００５」のときでありますが、実行委員会ということで申請を受けております。子どもたちにさまざまな体験活動をさせる、手づくり遊び等々をさせるといったこの活動の内容について、後援をするということで決定をした内容です。","id":"exchange-122"},{"speaker":"三上委員","kind":"質問","question":"活動の内容について、だから、教育委員会として、学校給食ということについて、それが表に出たという部分については、それでいいんか尋ねました。","respondent":"市川庶務課長","answer":"それが学校給食のいわゆるレシピに従ってつくられたか、どうか、これは把握しておりません。ただ、少なくとも給食の料理用具がその場で使われたということは一切ございません。","id":"exchange-123"},{"speaker":"三上委員","kind":"質問","question":"会場は土のところでしょ、車が入れば、当然、土ぼこりが舞います。後援するという意味にあって、もうちょっと慎重に扱ってもいいんじゃないかなと思いますけれども、いかがか尋ねました。","respondent":"富田生涯学習課長","answer":"社会教育、口に入る食べ物を提供する場の安全確保がきちんとされているのか等々について、私どもの確認が不十分であった点はあろうかと思います。","id":"exchange-124"},{"speaker":"三上委員","kind":"質問・要望","question":"きちっとした書類の中にあって、どういうものがいいのかということについては、その基準にかなった形で、１回１回それを点検しながら許可していく。これらを比べて考えてみると、並列的にいろいろな形で支援をしようという考え方であると、私は受けとめていますが、それでよろしいか尋ねました。","respondent":"富田生涯学習課長","answer":"はい、委員ご指摘のように、生涯学習の活動につきましては、行政として、施設の提供、場と機会の提供をするとともに、さまざまな事業の区民の皆さんの自主的な活動の支援をしていく、おっしゃるとおりです。","id":"exchange-125"},{"speaker":"三上委員","kind":"確認","question":"人生８０年代と言われて久しくなっていますけれども、確認したように、こういうことはわかりました。こういう現実を私は聞いていますけれども、教育委員会としては、そういうことについて何らかの声を聞いていらっしゃることはないか尋ねました。","respondent":"富田生涯学習課長","answer":"あるいは、地域での卓球の自主グループに参加されたり、そのような形で活動されているものと考えています。私のところには、直接にはそういった行き先についてのご相談というのは、現時点では、受けていないという状況です。","id":"exchange-126"},{"speaker":"三上委員","kind":"質問・要望","question":"私のところに寄せられていることはどういうことかというと、総合体育館でやっている卓球の週２回、数多くの人がたくさんいると。それは事実か尋ねました。","respondent":"富田生涯学習課長","answer":"今後も、そういったアリーナの状況を見ながら、活動場所についても、引き続き検討してまいりたいと思っているところです。したがいまして、五反田文化センターで卓球のできる場所を確保できないか、現在、設計の中で検討を進めているところです。","id":"exchange-127"},{"speaker":"三上委員","kind":"質問・要望","question":"そういう気持ちも、私は考えてほしいと求めました。区長、何か首をひねっているけれども、違いますか。","respondent":"富田生涯学習課長","answer":"今の卓球のできる施設ですけれども、スタジオがいいのか、どうかを含めまして、スタジオの数についても、ただいま検討を加えているところです。それから、卓球のできる場所については、スタジオとは限りませんけれども、ほかの場でも用意するように検討してまいります。","id":"exchange-128"},{"speaker":"西本委員","kind":"質問・要望","question":"これは代行とかどうのこうのという前に、その辺を、ちょっとご答弁ほしいと求めました。それらについて、今後、どういう形が可能なのかを、お聞きしたいと思います。","respondent":"市川庶務課長、古里学務課長","answer":"実質、８校から１校引きまして、現状では７校になっております。この国有地につきましては、法律に基づきまして、国有財産の有償貸付ということで、相応の使用料を払っているという仕組みです。それから５月に行った試食会では、衛生面の対応もよく、安心したという保護者からの声が寄せられているです。","id":"exchange-129"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、今後、いろいろ考えてやっていただきたい。今、給食の民間代行に移行する中では、なかなかできにくいところで、それも含めて、将来的に考えていただきたいと考えますが、いかがか尋ねました。","respondent":"市川庶務課長、日下部企画財政課長、古里学務課長","answer":"ただ、いかんせん、今の制度の中で、有償貸付、それから、改築をする際には、改築承諾料というものまで制度化されている現実があります。… しかも、９割の起債の償還については、すべて財調算定の対象になります。財政面でも非常に有利でありますので、今後とも… 数えるばかりですけれども、コンロを設置する場所があるというところには、そういう対応をしております。","id":"exchange-130"},{"speaker":"西本委員","kind":"質問・要望","question":"区長のほうも頑張っていただいて、品川区の思いを伝えて、国有地を無償で提供していただけるように頑張ってほしいと求めました。給食調理代行ということもありますので、全体的に可能な方向で検討を加えていただきたいとお願いして、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-131"},{"speaker":"松澤委員","kind":"質問","question":"成果報告書の１５６ページ、給食調理代行について、お伺いをしたいと思います。２人の委員の評価が分れましたので、１校当たりどのぐらいの経費削減になっているのかについて、お聞きしたいと思います。","respondent":"古里学務課長","answer":"経費の試算ですけれども、いろいろと変わってまいりますけれども、大体、１校当たり２,０００万円程度削減されるというのが、計算をした中で出てきている数字です。","id":"exchange-132"},{"speaker":"松澤委員","kind":"質問・要望","question":"大変な経費削減で、その意味では、残った学校にも順次拡大していってほしいと求めました。今年度の調理代行の中で、大間窪小学校で業者の変更があったと聞いたんですけれども、それについての詳細をお聞きしたいと思います。","respondent":"古里学務課長","answer":"大間窪小学校、４月スタート時点で、当初の仕様どおりに学校給食の経験者を配置できないという事態が発生しておりました。それに基づいて、業者の変更をしたものです。","id":"exchange-133"},{"speaker":"松澤委員","kind":"質問・要望","question":"この契約は、総合評価方式による契約ということで、今までの契約と変わった形をとっていますよね。これについても、説明してほしいと求めました。","respondent":"古里学務課長","answer":"私ども、業者の提案の中に、学校給食の経験者の配置ということを基礎的な条件として提案をさせていただきました。東京２３区では実績がないけれども、品川区での取り組みをしたいという申し出がありましたので、総合評価をしたものです。","id":"exchange-134"},{"speaker":"松澤委員","kind":"提案","question":"業務提案、特に衛生面の意識みたいなもの、これらをきちっと業者と話を進めながら契約を進めたい云々」と書いてあります。ちょっと問題があるんじゃないかと思うんですが、その点、見解をお聞きしたいと思いますとの意見を述べました。","respondent":"中島経理課長","answer":"総合評価方式について、お答えを申し上げます。事業の実施体制、方式そのものについては、妥当なものであったと考えております。","id":"exchange-135"},{"speaker":"松澤委員","kind":"質問","question":"それで、今まで経験したことのない業者、これは何ですか、「２３区では実績がないけれども」と、そこが何で入れるんだろうか。２校やっている業者が簡単に辞退してしまう、ほかで一生懸命委託をやりながら応募した人たちが、１校ずつ２業者が入れるじゃないか尋ねました。","respondent":"富田生涯学習課長","answer":"宝蔵地での建物の建築等で、ある程度掘り下げる場合には、試掘調査というのを行います。そして、本調査に入るようなものが出てきたような場合には本調査になるということで、今回は、本調査の該当がなかったというものです。","id":"exchange-136"},{"speaker":"松澤委員","kind":"確認","question":"今、そこにどんどんマンションが建っているけれども、５件しか試掘しないというけれども、ほんとうでしょうかね。建築確認なんかとったときに、ないのか、その辺をお聞きしたいと思います。","respondent":"富田生涯学習課長","answer":"ご指摘のように、建築のほうで、そういった指導はしていただいております。","id":"exchange-137"},{"speaker":"高橋委員","kind":"質問","question":"１５８ページの幼稚園の運営費について、お尋ねしたいと思います。幼稚園の教育の中で、一つの幼稚園だけではなくて、幾つかの幼稚園が合同で教育をする機会などはあるんか尋ねました。","respondent":"高橋幼保一元担当課長","answer":"幼児教育の中で、合同して幼児教育をする機会があるのかと問われると、今のところ、聞いていません、申しわけありません。","id":"exchange-138"},{"speaker":"高橋委員","kind":"質問","question":"保育園のほうでは、幾つかの保育園が集まってドッジボール大会をやったりとかをお聞きしているんですが、すみません、話が民生費のほうに飛びますが、お答えいただけたら。","respondent":"高橋幼保一元担当課長","answer":"そういった相互の関係での研究ということを進め始めたのが、平成１７年度、窓口を一本化した成果かなと思っているところです。","id":"exchange-139"},{"speaker":"高橋委員","kind":"質問・要望","question":"幼稚園と小学校の段差があるということで、その解消にも役立つのではないかと思ったので、お尋ねしました。現時点でどのようなことが組まれているか、お教えほしいと求めました、お願いします。","respondent":"高橋幼保一元担当課長","answer":"子どもの０歳から就学前、大まかな骨子というようなもの、パンフレットをつくったところです。委員会を年間４回する予定ですけれども、２回目が終わり、内容を深めているところです。","id":"exchange-140"},{"speaker":"高橋委員","kind":"質問","question":"すみません、具体的にどのようなことをするかという、その内容みたいなものは、その会議では出ていないんか尋ねました。","respondent":"高橋幼保一元担当課長","answer":"なおかつ、学校を視野に入れながら、プログラム開発をしています。来年度３月には策定できる予定ですので、そのときは、またご報告したいと思います。","id":"exchange-141"},{"speaker":"高橋委員","kind":"質問","question":"今年の予算で、これまた先ほどの就学前教育推進事業の中に、平成１９年度では、幼保と小の連携事業というので３１４万円あるんですが、こちらは、具体的にどのようなことをやられているか、説明を求めました。","respondent":"高橋幼保一元担当課長","answer":"幼小連携事業というところで、具体的には、平成１９年度、モデル事業として小学校２１校が参加し、公私立保育園、幼稚園３３園が参加して、現在、幼稚園、保育園、そして小学校の連携事業を進めているところです。","id":"exchange-142"},{"speaker":"高橋委員","kind":"質問","question":"では、具体的な成果は、後ほど、どんなことをやったか、教えてほしいと求めました。小学校教諭で、幼稚園教諭の免許を持っている人がどれぐらいなのかというのが、もしあれでしたら、また後ほどでも結構なんですが。","respondent":"高橋幼保一元担当課長","answer":"小の連携事業の具体例ですが、５月に出してもらった中では、今まで進めてきたところです。品川区の子どもとして育つということでは、この連携事業は大切な事業だと、私は思っているところです。","id":"exchange-143"},{"speaker":"高橋委員","kind":"提案","question":"これは提案というか、意見ということで。１校当たりの図書購入費がどれぐらいになっているのか、図書購入費が１校当たりどういう形になっているか、お願いしますとの意見を述べました。","respondent":"工藤品川図書館長","answer":"ネットワーク化整備校に関しましては、小学校で５５万円を追加しておりまして、中学校では７０万円余を増額でつけております。合計としまして、小・中学校図書購入費３,６００万円余をつけているところです。","id":"exchange-144"},{"speaker":"高橋委員","kind":"質問","question":"平成１７年度からプラスアルファをつけていらっしゃると思うんですが、それがそろった段階では、また４３万円に戻ってしまうんでしょうか。それも含めて、小・中学校の図書を充実させるに当たって、金額的にといいますか、その辺、妥当かどうかを説明するよう求めました。","respondent":"工藤品川図書館長","answer":"ネットワーク化後、図書館、書籍に係わる経費がどのようになるかというお尋ねです。１校当たり４３万円ということになっておりますけれども、５８校の整備が終わってから、また状況を見ながら考えていきたいと考えています。","id":"exchange-145"},{"speaker":"川西委員","kind":"質問","question":"一つは教科担任制の現況における効果について、教えてください。それから、夏季施設なんですけれども、在籍児童生徒数の何％が参加しているのか、説明を求めました。","respondent":"藤森小中一貫教育担当課長、河野指導課長、古里学務課長","answer":"私のほうから、１点目、教科担任制についてのお尋ねにお答えいたします。全小学校におきまして、５年生以上の一部の教科において実施をしているものです。小学校におきましては、部活動という形で実施されておりませんので、外部指導員は派遣しておりません。中学校においては、平成１８年度… クラブ活動の指導費の内訳ですが、クラブ活動の性格上、この金額は、中学校における活動指導費です。","id":"exchange-146"},{"speaker":"川西委員","kind":"質問","question":"１年生から３年生が対象ということで、この資料に書いてあるんですけれども。２年目、４月から開校ということで、その最終的な数字を説明するよう求めました。","respondent":"古里学務課長","answer":"中学校につきましては、最終的には、一応、全員の受け入れができたです。日野学園につきましても、基本的には、中学校のほうは、最終的に希望者は全員受け入れをしております。","id":"exchange-147"},{"speaker":"川西委員","kind":"質問","question":"一貫校になって、大変周りから人気があって、今、１０月１日から申込みの時期ですよね。同じ会派の阿部委員が質問していまして、認定の級を持っている人のことを言っておりますが、どのようになっているか説明を求めました。","respondent":"河野指導課長","answer":"平成１８年度、延べ人数で申し上げますと、小学校７８名、中学校１６名に、何らの形で介助員を措置してまいりました。小学校のお子さんで８４名、中学校で１３名に、何らかの形で介助をつけているという実績です。","id":"exchange-148"},{"speaker":"川西委員","kind":"質問","question":"すまいるスクールも、６時まで介助員をつけていただいているんか尋ねました。","respondent":"市川庶務課長","answer":"失礼しました。すまいるスクールでは、すまいるスクールの職員が対応しております。","id":"exchange-149"},{"speaker":"川西委員","kind":"質問","question":"そうしますと、例えば低学年で、一対一の対応が必要な発達障害の重度の場合もありますけれども、そういう場合には、人手が足りないんじゃないかと思うんですが、いかがか尋ねました。","respondent":"市川庶務課長","answer":"その子どもの状況に応じて、いわゆるスタッフの加配措置で対応をしております。","id":"exchange-150"},{"speaker":"川西委員","kind":"質問","question":"大変安心をいたしました。どういうシーズンに、どうしているか、お伺いします。","respondent":"古里学務課長","answer":"ジャガイモ、ニンジン、カボチャ、タマネギ等の野菜類が中心です。八ヶ岳につきましても、ジャガイモ、ニンジン、カボチャ、タマネギ、トウモロコシ等を取り入れているところです。","id":"exchange-151"},{"speaker":"川西委員","kind":"質問","question":"もう一つ、校庭整備について、小学校２校実施、これはどういう舗装で、どこの学校か、お伺いします。","respondent":"市川庶務課長","answer":"杜松小学校と、戸越小学校の２校です。いずれも、土舗装です。","id":"exchange-152"},{"speaker":"林委員","kind":"確認","question":"一つ、関連というよりも、教育委員会の姿勢だけ確認しておきます。確認しておくんですけれども、あるか、ないかだけ答えるよう求めました。","respondent":"富田生涯学習課長、河野指導課長、古里学務課長","answer":"五反田文化センターについてですが、複合施設全体を見て、学校の体育館以外スポーツ施設を入れるとお話をしたことは一切ございません。 転入してまいります管理職については、考え方、私どもが教育長講話も含めて指導しております。それから、プラン２１等の理念等については、それぞれの校長… １５２ページからの四角に入れているところですが、小学校、わざわざ箱に入れて表示をしているものです。","id":"exchange-153"},{"speaker":"林委員","kind":"質問","question":"この決算、予算の立て方は決まりがいろいろあるでしょう、わかりやすくしてほしいなということ。健康管理で言うと、幼稚園の教職員の健康管理というのは、お金をかけないんか尋ねました。","respondent":"高橋幼保一元担当課長","answer":"区立幼稚園につきましては、幼稚園の中では、子ども全体にかかわる部分については、学校保健法に定められている中で、それぞれの園医等の方針も含めて、職員に関しましては、区の職員と同じような健康に関する管理を行っているところです。","id":"exchange-154"},{"speaker":"林委員","kind":"意見","question":"どこかに入っているんでしょうけれども、きちんとそれは大事なことだから、載せてほしい。しっかりと先生たちを守ってあげるというか、してほしいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-155"},{"speaker":"宮崎委員","kind":"質問","question":"私は、学校規模適正化について、伺いたいと思います。そういうことでいいのか、どうなのか、まず聞きたいと思います。","respondent":"古里学務課長","answer":"教育委員会が、今回、学事制度審議会を立ち上げたですけれども、これが方針転換なのかです。その方法を学事制度審議会の中で検討するですから、方針を転換する、考えなければいけない状況の変化があったんだということで検討しておりますので。","id":"exchange-156"},{"speaker":"宮崎委員","kind":"提案","question":"そこのところが大きく違うと思うんですが、もう一度、見解を伺いたいと思います。今年の６月１２日の教育委員会の席上で、区長部局からの提案だということでコスト論を持ち出して、小規模校の統廃合を迫っていくとの意見を述べました。","respondent":"古里学務課長","answer":"スタンスを変えたのかですけれども、私どもは、今までも、これからもですが、小規模学校をなくすような検討を進めるつもりはございません。こうしたものも十分に尊重しながら、今後の教育環境がどうあるべきかということを検討していくですので、方針を変えた。","id":"exchange-157"},{"speaker":"宮崎委員","kind":"質問","question":"じゃあ、果たして、そうなんでしょうか。これは、どう転んで見ても、小規模校は統廃合していくと、そういうことが見え見えじゃないか尋ねました。","respondent":"長田教育次長","answer":"そういった中で検討されて、その答申をいただいた上で、教育委員会がどう考えるかというようなことです。これからの検討を進めていくわけですから、ある面、統廃合されるのかもわかりません。","id":"exchange-158"},{"speaker":"宮崎委員","kind":"質問","question":"これは、もう事務局の一人歩き、区長部局のコスト論を正面を抱えて教育委員会に迫っているということでしかないんじゃないでしょうか。本会議でも聞いたけれども、ついに答弁しませんでしたが、小規模校を残すということをはっきり言ったらどうか尋ねました。","respondent":"長田教育次長","answer":"それから、学校の統廃合という話につきましては、教育的な配慮の中から検討していくのは、これは当たり前のことです。ものを考えるときに、一つの物事を考えていくときに、コスト論というのは必ず持って検討しています。","id":"exchange-159"},{"speaker":"宮崎委員","kind":"質問・要望","question":"バランスをよくしたいということであると、具体的に、その基準というのは何か考えているんですか。やっぱり、学校選択制の中でも、小規模校を残すというのが義務だと思うんですけれども、どうか尋ねました。","respondent":"長田教育次長","answer":"先ほど来、説明しているとおり、学事制度審議会の設置につきましては、教育委員会の中ではさまざまな意見が出ました。それに基づいて設置をして、今、諮問していますので、その結果を見守っていただきたいと思います。","id":"exchange-160"},{"speaker":"堺委員","kind":"質問","question":"それからもう１点が、ここにあります、教職員の健康管理について１点、合計３点について、お尋ねをしたいと考えています。中学生約４,４００名、小学校は約１万２,０００人近いお子さんが、どのように把握されておられますか尋ねました。","respondent":"河野指導課長","answer":"それから、女子については、４種目ほどで国の平均も上回っている。４種目については、国は下回っておりますけれども、都の平均については上回っているという状況です。","id":"exchange-161"},{"speaker":"堺委員","kind":"質問・要望","question":"健全な精神は健全な肉体に宿るという言葉もありますが、やはり、学力、体力、気力というんですか、それが重要な要素かなと考えています。しっかりと取り組んでいただきたいと思うんですが、この件について、ご見解をお聞かせいただけますか尋ねました。","respondent":"河野指導課長","answer":"委員ご指摘のとおりで、知、徳、体と、これはもういずれも大切な条件ですので、学校教育の中で体力の向上も含めて、できる限りのことは取り組んでいきたいと考えております。","id":"exchange-162"},{"speaker":"堺委員","kind":"質問","question":"今度は体力ではなくて精神面といいましょうか、そういう面について、ちょっと教えていただければと考えています。この辺について、実情といいますか、実態といいましょうか、それを把握されたことはありますか。","respondent":"河野指導課長","answer":"あるいはアンケート調査等によって、傾向的なもの、あるいは個々の対応についてはやっております。マナーの問題等々を含めて、悩みの解決方法というような内容については、指導しています。","id":"exchange-163"},{"speaker":"堺委員","kind":"質問","question":"それぞれ４人から６人の精神科の先生がその学校に出向いて行って、問診というんですか、いろいろ調査をされたようです。有病率と読むんでしょうか、中学１年生に限ると１０.７％という調査の結果が出ております。","respondent":"河野指導課長","answer":"最近の小学生、中学生、さまざまなところで、さまざまな形でストレスを受けているのだということが、こういう実態にあらわれているのかと思います。","id":"exchange-164"},{"speaker":"堺委員","kind":"質問・要望","question":"やっぱり早い時期に芽をとっちゃうというんでしょうか、そういう方向でこの件についても取り組んでいっていただきたいなと、こんな気がするんです。こういう精神面の健康という面についてもしっかりと取り組んでいっていただきたいと、こう重ねて思うんですが、ご見解をお聞かせいただけますか。","respondent":"河野指導課長","answer":"この手の取り組みについては、特別支援の関連で、今年度から全校に、専門家による巡回相談を実施しています。ぜひ、そういう力も借りながら、子どもたちの心のケアを含めて取り組んでいきたいと考えております。","id":"exchange-165"},{"speaker":"堺委員","kind":"質問","question":"それから３点目、今度は教える側の先生です。あるいは小学校でも約６８２名という大変多くの先生がいらっしゃいますが、いかがでしょうか、状況についてお知らせいただけますか。","respondent":"市川庶務課長","answer":"小・中学校の教職員の健康管理については、体系上は教育委員会事務局のほうで管理をしているというシステムをとっております。さらに、看護士を配置して、教職員の健康診断等の執行状況について万全を期すようにしております。","id":"exchange-166"},{"speaker":"堺委員","kind":"確認","question":"やっぱり若い先生の心と体、そういうものをサポートしていく必要性も、学校の現場の中では必要だろうと言われておりますね。この件について、学校現場における若い先生のサポート体制について、ちょっと確認をしておきたいと思います。","respondent":"河野指導課長","answer":"慣れない環境の中でさまざまなストレスが加わったときに、人間、抑鬱状態に陥るというふうに、私、認識しております。日常的に指導主事、あるいは、事務職員を巡回させて、できるだけ相談等にはこまめに乗るという体制で取り組んでいるところです。","id":"exchange-167"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そういう基準を高いところで設けてもいいけれども、それはもうちょっとスパンを広げてやってほしいなと、それをもう一度お聞きしたいと思います。こういう教材がこの学校にあるというリストを校長会等で配っているか、どうか、教えていただきたい。","respondent":"河野指導課長、藤森小中一貫教育担当課長","answer":"教員が、確かに変わってきたということに関する評価ですが、品川区では、外部評価等も実施しております。委員、ご指摘のケーブルテレビの活用等も含めて、まだまだ研究の余地はあると考えております。実施した後に、どういった方にお願いしたというようなものにつきましては、すべての学校を把握している状況があります。","id":"exchange-168"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"こういうことをやれる人がいるんだというのは、どこかで横串をやってほしいと思うんですけれども、それに対する考え方を教えていただきたい。改善点を生徒に出すわけですから、あとの３回のアンケートというか、生徒の評点が一番成長率が高い先生がいるわけですよね。","respondent":"河野指導課長、堀越行財政改革担当課長","answer":"ほかの課とも連携をしながら、当該のご本人に確認をとりながら、できるところから進めていきたいと考えます。あの先生はうるさいから嫌だという評価もあるという実態がありますので、この部分については… 今、活用する仕組みといたしましては、ボランティアナビというのがございまして、その中で登録をいただいています。","id":"exchange-169"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"何かというと、例えば地域の方々が、この学校にこういうことをやろうと、例えば和楽器を寄附したりすると、そこに残るわけじゃないですか。これは要望だけにしておきます。","respondent":"藤森小中一貫教育担当課長","answer":"教材のリストのことについてですけれども、当然、限られた予算の中で有効活用ということであるならば、今の委員ご提案の内容は大変すばらしいものだと思いますので、今後、校長会といろいろ相談しながら、前向きに検討してまいりたいと考えています。","id":"exchange-170"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/570060?Template=document&Id=1286#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":115115,"voices":391}},{"id":"h19-20071015-4","meetingId":"h19-c-settlement","date":"2007年10月15日","dateIso":"2007-10-15","committee":"決算特別委員会","time":"午前１０時０２分～午後６時０３分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を119件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"林委員","kind":"質問","question":"いろいろな種類の使われ方をしていますし、款別審査の中でも４,０００台を超えるというお話もありました。あるいは管理はだれがしているのか、あるいはインターネットにすべてつながっているのか、そういうところをお聞きしていきます。","respondent":"福田企画部長","answer":"それからご質問にありました共通で使用する、いわゆる窓口業務などに対応するものが６００台あります。例えば産休代替のような派遣職員の場合にはそういう機能が必要ないと考えられますので、若干数でありますけれども、そういうものがあります。","id":"exchange-001"},{"speaker":"林委員","kind":"意見","question":"学校の先生方に１台ずつという、個人が責任を持って操作をする、あるいは管理をしていくという上に責任者がいると聞いています。あけっ放しという言葉があるのかどうかわかりませんけれども、どのくらいのセキュリティの厳しさというのがあるのか、その辺を聞かせてくださいとの意見を述べました。","respondent":"福田企画部長","answer":"そのグループの職員だけが認識しているパスワードがないと、そのパソコンを立ち上げること自体ができません。個々のパスワードを入力するものですから、どういう操作が行われたのかということの認識もできるようになっております。","id":"exchange-002"},{"speaker":"林委員","kind":"質問","question":"人間ですから、油断ということもあるだろうと思いますので、そういうことを重ねてお願いをしておきます。本体と保守料というか、メンテナンスという料金に分けられると思うんですけれども、その辺について説明するよう求めました。","respondent":"福田企画部長","answer":"このうち個々の職員が使用しているものが５億６,０００万円ということになります。機器の賃借料が２,９００万円、これが１,８００万円、これはいずれも個人用のものに相当するものです。","id":"exchange-003"},{"speaker":"林委員","kind":"意見","question":"数字から割り返していくと、人のお金と部品ということになっていますけれども、自前でやったほうが効果があるという考え方も１つあると思うんですね。","respondent":"福田企画部長","answer":"１日五、六件ということもありますと、迅速な修繕がなかなか難しくなるような局面も考えられます。このようなことを考え合わせますと、現在のところは委託による保守管理のほうに優位性があるのではないかと考えております。","id":"exchange-004"},{"speaker":"林委員","kind":"質問","question":"いろいろあると思いますし、コストパフォーマンスを含めて検証していってほしいと思いますので、お願いしておきます。主たるものを挙げていただくよう求めました。","respondent":"福田企画部長","answer":"お答えする前に、正確に申し上げますと８００万円台でございまして、それを除けば大体７００万円というものが平均的なものです。実務的にはさまざまな、例えば実施報告書のようなものがございまして、それぞれの所管が確認をするという作業をそのたびに行っているものです。","id":"exchange-005"},{"speaker":"林委員","kind":"質問","question":"ですから、補助金によっては後追いできちんと補助金を出した先から、いろいろな意見を聞いてみるということも必要なんだろうと。そこまで気を使って出していくということも必要なんだろうと思うんですけれども、その辺について説明するよう求めました。","respondent":"福田企画部長","answer":"ある程度の期間その効果が継続するような事業、２つあると思いますが、これはなかなか難しい問題があると思います。しかしながら、かといって１年で枯れてしまう、この辺のバランスを考慮しながら検討すべき課題だろうと考えております。","id":"exchange-006"},{"speaker":"林委員","kind":"質問・要望","question":"防災に関連して２つ伺います。ですから、品川に助けに来られるという人がたくさんいらっしゃるわけで、その辺についての考え方を説明するよう求めました。","respondent":"田中区民生活事業部長","answer":"今、部隊運用の訓練と多くの方が参加して体験してもらうというところの部分と、うまく重なる部分があれば今後検討していきたいと考えております。継続性等を考えて、十分学校側と協議しながら、実現に向けて検討してまいりたいと考えております。","id":"exchange-007"},{"speaker":"林委員","kind":"質問・要望","question":"だから、そういう訓練も必要なんじゃないですかということを伝えているので、そういうところをもう１回確認させてください。ですから、声かけをしてやってほしいと求めましたので、もう一度、答えるよう求めました。","respondent":"田中区民生活事業部長","answer":"慌てずにご家庭で、そのときが来たら対処できるようにする、なるべく多くの方が参加して体験型の訓練をしてもらう。そういう性格のものだということでご理解いただきたいと思います。","id":"exchange-008"},{"speaker":"林委員","kind":"提案","question":"１つその中に、品川区としての備えが１つ増えるでしょうという提案をしているわけで、検討するかしないかだけ後で答えてください。ＩＳＯは４つのチャンネルで回っているわけですから、それぞれについて説明を求めました。","respondent":"岩崎環境清掃事業部長、濱野区長、田中総務部長","answer":"それから、何よりもそういう規格に合格しているということを維持し続けているというところに意味があるんだろうと考えております。もう１つ… 各地域地域で別にやってくるわけではありませんので、そういったことについての対応というのも必要だろうと考えています。しかし… 中小企業センターも実はタイルでございまして、あのときよりもう少し詳しく説明申しますと、タイル自体が老朽化しますと劣化して落っこちてきます。","id":"exchange-009"},{"speaker":"林委員","kind":"質問・要望","question":"割り箸が全部悪いわけじゃなくて、国産の間伐材を使った割り箸はもう少し利用してほしいと。中国産の割り箸より割高になるんだけれども、品川区でよそがやっていない第１番目のマイ箸宣言というのはいかがでしょうかね。","respondent":"岩田まちづくり事業部長、岩崎環境清掃事業部長","answer":"さらに技術的に難しいのがこの壁面緑化というものでございまして、これは私どものほうでは十数年前からいろいろな試行錯誤を繰り返してまいりました。委員ご提案の、その趣旨は十分貴重なご意見だと思いますので… １枚３００円で、包むようにきれいな端切れでつくっておりますけれども、そういうもので今、だんだんはやりつつあります。","id":"exchange-010"},{"speaker":"林委員","kind":"質問・要望","question":"そして品川はまだですけれども、取り組み始めた自治体もあると聞いていますので、その辺についてお聞かせください。現況、あるいは区民の方々の反応、反響というのを説明するよう求めました。","respondent":"早津区民生活事業部次長","answer":"暖景苑を廃止した後、３つの民間施設を借り上げまして、運用を開始したのがこの４月からです。利用者の方からはおおむねご好評をいただいていると認識しています。","id":"exchange-011"},{"speaker":"林委員","kind":"意見","question":"２３区では４区、地方自治体の中で大変高額な、１億円近い予算を組んでいる自治体もあると把握をしております。これは新しく取り組むということであれば区長のお答えと感じますけれども、その部分だけ先にいただきますとの意見を述べました。","respondent":"濱野区長","answer":"そういう意味で、何らかの対応を検討する必要があるんだろうと思います。こういった点を検討しながら進めてまいりたいと考えています。","id":"exchange-012"},{"speaker":"林委員","kind":"質問・要望","question":"それ以外のところは、大ホールというんですかね。ただで招待するわけじゃないんですから、それぞれが自分で費用を払って利用するわけですから、情報を細かく伝えていただきたいと思っています。","respondent":"早津区民生活事業部次長","answer":"かゆいところにといいますか、このパンフレットに追加的な情報を、必要な情報を織り込みをするような形で対応してまいりたいと考えています。私どもとしましては、委員のご指摘もありましたが、暖景苑等との委託料とも比較して、かなり格安であると認識でいるところです。","id":"exchange-013"},{"speaker":"林委員","kind":"質問・要望","question":"「学校ごとの学習指導要領の教育目標を達成しづらくなっている小規模校」、こういう表現があるんだけれども、小規模校ってこういう現状ですか。それからもう１つは、品川区の教育改革にとっての邪魔にならないかどうか、説明するよう求めました。","respondent":"若月教育長","answer":"平成１２年から品川区は教育改革を始めてまいりました。品川区が進めている教育改革に自信を持って、これからも前進をしてまいりたいと、かように考えているところです。","id":"exchange-014"},{"speaker":"林委員","kind":"確認","question":"それから、品川の改革と日本の改革という観点でいくと、教員の独自採用ということについて、東京都とか国は何の文句もないんですね。それだけ確認して終わります。","respondent":"若月教育長","answer":"あるいは地方分権といったような大きな流れの中から、品川区が独自に、独自の財源で教員を採用していく。そして、東京都の教育委員会はかなりその育成の仕方についても注目をしていきたいということで、応援の声をいただいているところです。","id":"exchange-015"},{"speaker":"山路委員","kind":"質問・要望","question":"質問の内容は、東品川清掃作業所の廃止について、大井町駅周辺のまちづくりについてお伺いをいたします。そこで、品川区の住宅政策のさらなる充実を求めてお伺いをいたします。","respondent":"岩田まちづくり事業部長","answer":"住宅困窮者に対する住宅セーフティネットを構築するための施策を策定、実施することを、国や地方公共団体の責務と定めたものです。住宅ストックの活用および賃貸住宅の情報提供、相談、その他の支援に関する施策を講ずることとしたものです。","id":"exchange-016"},{"speaker":"山路委員","kind":"質問・要望","question":"質問の２点目は、高齢者等への入居あっ旋事業の拡充についてであります。そこで、あっ旋については、ここ二、三年、何人の高齢者から申請があり、成立に至らなかった件数はどれくらいあるのか、お伺いいたします。","respondent":"木下福祉高齢事業部長","answer":"この中であっ旋助成したケースは２３件ですが、全体では４８件が解決済み、年度末で未解決のものが２７件という状況です。この辺の数値の推移は、この３年間の単位で見ましても、ほぼ同様です。","id":"exchange-017"},{"speaker":"山路委員","kind":"質問","question":"７５件申請があって４８件、私も実は先日、一人暮らしの高齢者の方からアパートが借りられなくて困っているとの相談を受けました。今、主な不成立の理由とこれまでどのような改善を図ってこられたのか、改めてお伺いをいたします。","respondent":"木下福祉高齢事業部長","answer":"１つは東京都宅地建物取引業協会品川支部との間で住宅あっ旋事業協力店制度というのを、平成１５年から協定を結ぶ形で実施をしています。なお、品川支部のほうとは、毎年定期的な会合を設けておりまして、この制度の趣旨について協力依頼を続けているところです。","id":"exchange-018"},{"speaker":"山路委員","kind":"提案","question":"公明党は、当時整備された、高齢者の居住確保に関する法律によって創設された東京都の支援策を積極的に活用するよう提案をしてきましたが。これらの事業を現在検討中の第四次長期基本計画の中に盛り込んでいただくことを要望いたしますが、それぞれご所見をお伺いいたしますとの意見を述べました。","respondent":"木下福祉高齢事業部長","answer":"この間検討を進めてまいりましたけれども、最近になりまして、行政との連携の中で行っている事業者が複数出てまいりました。今後の高齢期の住まい方ということを幅広い角度から検討し、そのあり方、あるいは仕組みなどを考えていく必要があるだろうと認識しています。","id":"exchange-019"},{"speaker":"山路委員","kind":"質問・要望","question":"今、国の制度の活用をした新たな仕組みづくりを検討するとの答弁をいただきましたが、どのような内容となるか教えてほしいと求めました。","respondent":"木下福祉高齢事業部長","answer":"今後検討していきたいということでありますが、ただ特に高齢期の住まい方ということを考えましたときに、今、２つ課題があるなと考えています。あわせて宅建協会品川支部と連携もしながら、第四次長期基本計画の中で幅広い角度から検討してまいりたいと考えております。","id":"exchange-020"},{"speaker":"山路委員","kind":"提案","question":"私は去る６月の第２回定例会の一般質問で、子育て世帯等の住宅確保のため、上限４万円の助成金を活用した制度の創設を提案いたしました。手続等の詳細について注視していくとの趣旨の答弁をいただきましたが、その後の詳細について、施行時期とあわせてお知らせをほしいと求めました。","respondent":"岩田まちづくり事業部長","answer":"子育て世代をはじめとした住宅困窮者の方々を支援し、あわせて住宅の空き室の解消を図るというものでございました。区の借り上げ型区民住宅で最も問題となっておりました空き室の多い住宅を、直接対象とできないという制度であることが明らかになってまいりました。","id":"exchange-021"},{"speaker":"山路委員","kind":"質問・要望","question":"改善を働きかけていると聞いてはおりますが、さらに精力的にお願いをしたいと要望いたしますが、いかがでしょうか。区としても検討していただければと要望いたしますが、どのようなお考えをお持ちでしょうか、お伺いいたします。","respondent":"岩田まちづくり事業部長","answer":"区といたしましても、この地域優良賃貸住宅制度が公営住宅を補完する公的賃貸住宅の活用という、セーフティネット法の中核に位置づけられているという事業であることから、現在、国に対して制度の改善を要望してきているところですが、引き続き働きかけを強めてまいります。","id":"exchange-022"},{"speaker":"山路委員","kind":"質問・要望","question":"平成２１年度までの計画では、今後の新たな公営住宅の建設についてはどのようにお考えなのか、お伺いいたします。策定中の新たな基本構想、今後の長期基本計画にどう位置づけていくのか、予定があったらあわせて教えてほしいと求めました。","respondent":"岩田まちづくり事業部長","answer":"２３区で飛び抜けたストックを保有しているものでございまして、現在の段階では新たな需要に対して建設を行っていくという考え方はございません。その可能性と必要性については、もう１度きちっと議論をして、適切に対応してまいりたいと考えております。","id":"exchange-023"},{"speaker":"山路委員","kind":"提案","question":"住宅困窮者のための住宅建設について提案いたしましたが、障害者、子育て世帯などの住宅確保要配慮者のための公的住宅の建設を提案いたします。長期基本計画の中に織り込んでいくですが、早急に検討をしてほしいと求めましたが、ご所見をお伺いいたしますとの意見を述べました。","respondent":"岩田まちづくり事業部長","answer":"この２住宅の方々につきましては、来年度に、財務局に財産の引き継ぎを行う予定であると伺っております。その東京都の動向に注目してまいりますけれども、このうち第２大井伊藤町住宅につきましては、現在調整しています。","id":"exchange-024"},{"speaker":"山路委員","kind":"質問","question":"５点目は、二世代住宅取得等助成事業についてお伺いいたします。平成１７年度、平成１８年度は何件の予定件数を見込み、それぞれ申し込み数と助成件数があったのかお伺いいたします。","respondent":"岩田まちづくり事業部長","answer":"この対象件数ですが、平成１７年度は、申請１６件に対しまして、助成が完了しましたのが１４件です。同じように平成１８年度は申請１５件で、助成件数が１５件です。","id":"exchange-025"},{"speaker":"山路委員","kind":"質問","question":"助成予定件数に対して助成をした件数が、ただいま数字をお伺いしまして、非常に少ないようですが、この件については、どのように検証されているのか、お伺いいたします。","respondent":"岩田まちづくり事業部長","answer":"当時は予算化してある件数は２０件でございましたが、その都度補正予算等で充当させていただいたものです。この動きの中で、現在は予算上は２５件の対象件数とさせていただいているものです。","id":"exchange-026"},{"speaker":"山路委員","kind":"提案","question":"いつ家を建てても均一にすることが必要と思いますので、制度としてこれは改善していただきたいことを要望いたしますが、お考えをお聞かせください。したがって、２５戸の枠を外した二世代住宅施策を提案いたしますが、ご見解をお伺いいたしますとの意見を述べました。","respondent":"岩田まちづくり事業部長","answer":"委員ご指摘のように、そのちょうど中間部分であります６月に今までは募集等を行ってきておりましたけれども、検討させていただきたいと思います。","id":"exchange-027"},{"speaker":"山路委員","kind":"確認","question":"本年６月２０日に改正建築基準法が施行されましたが、現状と今後の本区の取り組みなどについてお尋ねしてまいりたいと思います。建築確認審査期間が延長されたことにより、高齢者幼保施設では５カ月、当初計画よりおくれるとの発表がありました。","respondent":"田中総務部長","answer":"今持ってありますのは、荏原西地区の小中一貫校等々３校の新築工事、それから八潮地区小中一貫校での増築工事などが予定されているところです。","id":"exchange-028"},{"speaker":"山路委員","kind":"質問・要望","question":"改正された法についてお伺いします。そして改正建築基準法は、ただいま説明が一部ございましたが、その趣旨や主なポイントをお知らせほしいと求めました。","respondent":"谷田部まちづくり事業部次長","answer":"３点目ですけれども、大臣認定の構造計算プログラムも改ざんできるなどの問題があったということで、大きく３点私どもは認識しています。４点目は中間検査の義務づけでございまして、３階建て以上の共同住宅に対する中間検査の義務づけがされ、建築基準法の厳格化が行われたです。","id":"exchange-029"},{"speaker":"山路委員","kind":"質問・要望","question":"ところで、７月の建築確認件数速報値では、これに引きずられる形で８月の住宅着工数も４割以上激減したことが明らかになりました。お伺いしますが、各月における建築確認申請数と許可数を、前年と比較しながら示すよう求めました。","respondent":"谷田部まちづくり事業部次長","answer":"これは延べ床面積に関係ございませんが、２０ｍを超える鉄筋コンクリート造の建築物、それから４階建て以上の鉄骨造の建築物が対象になります。","id":"exchange-030"},{"speaker":"山路委員","kind":"質問・要望","question":"そこで、国による建築確認行政の円滑化に向けた取り組みをお知らせほしいと求めました。現在、本区の相談体制などの取り組みについてもお伺いいたします。","respondent":"谷田部まちづくり事業部次長","answer":"東京都が主催いたします建築士など実務に携わる人を対象とした説明会の周知を行い、窓口での個別相談の対応をとってあります。それから申請者への対応も充実してございまして、申請前の協議を綿密に行い、申請後の審査が円滑に進むよう、現在努めているところです。","id":"exchange-031"},{"speaker":"山路委員","kind":"確認","question":"現状の建築確認申請数や許可数を踏まえると、さらに今後建築確認業務の円滑化が進むことによって、現在の審査体制で対応することは可能でしょうか。そこで、今後の申請数の増加の見通しをどのように立てておられるかをお伺いいたします。","respondent":"谷田部まちづくり事業部次長","answer":"建築確認の増加も予想されますけれども、制度改正に伴う一過性のものと考えられ、組織内の協力体制強化により対応が可能であると考えています。","id":"exchange-032"},{"speaker":"山路委員","kind":"質問・要望","question":"特定行政庁に求められるのは、できるだけ早く建築確認許可をおろすことがであるのは当然ですが、既に平成１８年第１回定例会の代表質問において。今からかかる事態を未然に防ぐための確認審査人員の増員など、体制の強化を求めますが、ご所見をお伺いいたします。","respondent":"谷田部まちづくり事業部次長","answer":"３割は区のほうに申請する状況になってございまして、建築基準法が改正された後、現在の制度でも変わらないものと私ども考えてあります。当面につきましては、組織内の中の協力体制で対応していくです。","id":"exchange-033"},{"speaker":"山路委員","kind":"確認","question":"今後、品川区へ建築確認申請がどさっと出た場合、現状で大丈夫だと言われておりますが、私はそのパニックを非常に危惧するものです。人事課の方に改めてもう１回お伺いいたしますが、今から体制については早急にとっていくべきだと思いますが、どのようにお考えか尋ねました。","respondent":"田中総務部長","answer":"今回の建築確認審査関係につきまして、特に人員の体制の問題について私のほうからお答えをいたします。区の職員のＯＢを、例えば非常勤職員としてあたらせるとか、そういう対応を考えざるを得ないということで考えているところです。","id":"exchange-034"},{"speaker":"山路委員","kind":"質問・要望","question":"続いて東品川清掃作業所の廃止についてお伺いいたします。東品川清掃作業所は平成１２年の都区制度改革により、ごみ圧縮設備でコンテナに詰め込み、このたび廃止になるということをお伺いいたしました。","respondent":"岩崎環境清掃事業部長","answer":"船舶中継所ですが、サーマルリサイクルという大きな政策転換を２３区が来年度一斉にやってまいります。相当かさがあったわけですが、それが瀬戸物の割れたものとかというようなものが多くなりますので、そのようなことになるです。","id":"exchange-035"},{"speaker":"山路委員","kind":"質問","question":"ここが廃止になると、この土地を品川区は自由に活用できるのか、あるいは東京都の縛りはあるのか、この辺の状況についてはどのようになっているのか、また廃止後のこの土地の有効活用については、品川区独自で計画が立てられるのかどうか、お伺いをいたします。","respondent":"福田企画部長","answer":"品川区のいわば裁量についてお答えをしますが、あそこの土地は平成１２年の特別区制度改革、都区間で譲渡契約が締結されております。今から数えますと大体１３年間、今の時点でこの品川区の裁量で跡地活用の計画を進めるという関係には、残念ながらございません。","id":"exchange-036"},{"speaker":"山路委員","kind":"質問・要望","question":"現状ではあと１３年縛りがあるですが、その縛りを早く取れるように交渉していただきたいということと、改めて要望させてほしいと求めました。ご意見をお伺いいたします。","respondent":"福田企画部長","answer":"拘束の問題はありますけれども、あの土地をどう考えるかということにつきまして、品川区はいろいろ考えるべきだという認識は持っております。","id":"exchange-037"},{"speaker":"山路委員","kind":"質問・要望","question":"商業、交通の中心としても、今後の発展のためにも今後のまちづくりにおいての一層の努力が求められているものと考えるものです。質問の１点目は、昭和６２年の大井プレイス構想について、今後の検討計画についてお伺いをいたします。","respondent":"岩田まちづくり事業部長","answer":"広町のアパートを中心とした開発構想につきましては、この３年間、ＪＲと共同でさまざまな検討をしてまいりました。この間の３年間の成果は、今後の大井町駅周辺の開発の望むべきあり方について、引き続き検討をしてまいりたいと考えています。","id":"exchange-038"},{"speaker":"山路委員","kind":"質問","question":"区民相談における内容を中心に質問をさせていただきました。さらなる区民ニーズにこたえる施策を期待して、私の総括質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問・要望","question":"初めに環境の質問です。京都議定書以降の状況と、このままの状況が続くと日本はどうなるのか、現時点での課題をお聞かせほしいと求めました。","respondent":"岩崎環境清掃事業部長","answer":"来月の１１月には、ほかの部会も含めた統合報告書が出される予定だです。地球温暖化というのがここ３０年ほどで急激に進んでいるということが、これが人為的な結果であると、より国際的な認識が明確になってきたです。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"意見","question":"現時点が今後どうなるのかというところを、もう少し詳しくお聞かせいただきたかったわけですけれども、３０年、急激に温暖化が進んでいる。ＣＯ２が増加している、品川でできる温暖化防止対策は一体何なのか、現状と課題をお知らせくださいとの意見を述べました。","respondent":"岩崎環境清掃事業部長","answer":"中国、インド、そういう地球全体で温暖化ガスを削減しようという動きを強めなければならない。これが当面の最大の課題であると認識しております。","id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"評価もしていますけれども、今、発生源をどう対応していくのかというのが求められていると思います。具体的な方向に足を踏み出してほしいと思うことが１点と、もう１点、この点はいかがか尋ねました。","respondent":"岩崎環境清掃事業部長","answer":"もう１つは、私どもが考えているのは、公的機関の率先的な取り組みのようなことです。政府と、東京都と、目標そのものは違っておりますが、適切な組み合わせで全体として地球規模のＣＯ２削減が進めばよろしいと考えているわけです。","id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問・要望","question":"環境というか、品川の状況に合ったものというところが求められていくことだと思いますけれども、特に他都市との連携とか。来年４月より本格実施となっておりますけれども、不燃としてきたプラスチックを燃やすように変更した理由は何なのか、この点について伺います。","respondent":"岩崎環境清掃事業部長","answer":"これまでご説明してきましたように、ＣＯ２フリー、大きな寄与をしないというふうに認識しております。そういう意味で電力を買わないで済むということがありますので、これは非常に重要なポイントだろうと考えております。","id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もう１回そこ、ＣＯ２はこのサーマルリサイクルを実施することで増えるのか、明確にお答えをほしいと求めました。この間ずっとプラスチックを燃やすことで増えるＣＯ２と、この相殺で同じだという考えは全く当たらないと思いますが、この点はいかがか尋ねました。","respondent":"岩崎環境清掃事業部長","answer":"埋立地をごらんになると、あれで発電できるぐらいに集められる部分というのは少ないと説明を受けております。大変大きな温暖化係数を持つメタンガスでありますので、委員のおっしゃるような話にはならないのではないかと私は理解しております。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もう１点なんですけれども、燃やすことの危険、この点についてお伺いしたいと思います。環境や人体への影響が大きいと言われていますダイオキシン類や重金属類などなど、危険について認識をお伺いしたいと思います。","respondent":"岩崎環境清掃事業部長","answer":"今の清掃工場は、環境に対する負荷を可能な限り削減しようという、プラント産業に近い形のものであるというのはご指摘のとおりだと思います。","id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほどのＣＯ２のところはぜひお答えをほしいと求めました。燃やすことで新たに生成していく、このことは何としてでもやめていかなければいけないと思いますが、改めていかがか尋ねました。","respondent":"岩崎環境清掃事業部長","answer":"先ほどメタンガスの説明をいたしましたが、メタンガスが減ってＣＯ２が増えるという関係で、それがほとんど相殺になるです。それから、これは公的機関が正式な検査機関にきちんとお願いしたものでありまして、そのような恣意的なことは一切行われていないと考えています。","id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ実態をしっかりとらえてほしいと求めました。その辺の真意を伺いたいのと、売電の考えはごみを今後どんどん増やす方向に向かうのではないかと考えますが、これはいかがか尋ねました。","respondent":"岩崎環境清掃事業部長","answer":"今、燃え続けておりますので、プラスチックを燃すとか燃さないというのは関係なしに発電はできるわけです。そういう意味で、そういうことは全然だれも考えていないわけでございまして、ちょっと認識が違うなです。","id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ごみを減らすのに何が必要なのでしょうか。この３Ｒの政策について説明をしていただきたいのと、この循環型になっていない大もとが一体何か、これについてお願いいたします。","respondent":"岩崎環境清掃事業部長","answer":"ちょっと前は自動車のリサイクルも法律上規定してきたということで、循環型は日本ではかなり進んできているという認識です。うまくご答弁できないわけですけれども、そこをもうちょっと追加的に言っていただくと、もうちょっとうまく言えるかもしれません。","id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問","question":"企業の責任を問わないばかりか、かえって企業が責任を負うのを助けてしまうことになるのではないでしょうか。それだったら燃やしてしまえばいいではないか、こういった人が増えるのではないか尋ねました。","respondent":"岩崎環境清掃事業部長","answer":"先ほどお話が出ました循環型社会形成推進基本法の第２条は定義がありまして、製品等が廃棄物等となることが抑制されうんぬんかんぬんです。そのエネルギーをリカバリーする、リサイクルするという流れですので、特に矛盾していないと理解しております。","id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そこをもう１回お答えいただきたいのと、回収をしたり、再使用をする。この点についてお答えいただきたいのと、この辺についてどのように説明をしているのか、今後の課題について、答えるよう求めました。","respondent":"岩崎環境清掃事業部長","answer":"私どもがいろいろと分別変更についてビラを配布し、個別訪問をやっている中では、非常にこの分別はいいという声が聞こえております。これは非常に品川の場合、うまく定着しているように今の段階では見受けているところです。","id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２月２日、統廃合を視野に入れている検討となっていると思いますが、この点はどうでしょうか。３月から３カ月間、また今後の審議の予定、検討内容なども示すよう求めました。","respondent":"長田教育次長","answer":"この学校の将来のあり方に関する検討というのは、いずれは検討しなければいけない項目だろうと私どもは理解をしています。それから、１回で決着がつかないで、何回か継続をして、最終的には全会一致でご承認をいただいたです。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私はかなりのいろいろな意見、批判が出たと聞いています。特に進め方、方向性に問題がありといった意見が出されたそうですが、委員の方々の意見を幾つか紹介してほしいと求めました。","respondent":"長田教育次長","answer":"教育委員から出た意見ですけれども、いろいろな意見が出たというのは申し上げました。この見直しというか、検討が、この検討が今までの区のスタンスを変えていくものにならないかといったようなことが主な出た意見の内容です。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問","question":"ポスト設置が必要かどうかの検討は事前に行うべきであった。私は、全会一致と言われましたけれども、このような多様な意見が出ていた、このことを今後どう生かしていくのか、ぜひお伺いしたいと思います。","respondent":"長田教育次長","answer":"今、３月２６日の教育委員会でのご発言について説明をいただきましたけれども、何も否定をしてございません。一部の議案修正も行いましたし、これについては何回か継続で協議をしてきたという結果ですので、そのようにご理解をいただきたいと思います。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この適正規模、統廃合しないと言っていたのが、この方針が変わったと受けとめてよろしいわけですね。一体、だれが、いつ、この方針を変えたのか、明確にお答えほしいと求めました。","respondent":"長田教育次長","answer":"その１つに、過小規模校、極めて人数が少なくなってきた学校、こういった学校では教育要領を実施をしていくに当たっての弊害が出てきていると。従来の方針転換をだれが、統廃合に結びつけるというような決定については、一切区の中ではしてございません。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問","question":"昨年の決算特別委員会では、子どもの数と学校の数のアンバランスをどうとらえるか課題である。やはり前区長が統廃合しないと言っていたことに比較して、私は明らかに方針が変わったととらえますが、これを変わらないと言えるのか尋ねました。","respondent":"若月教育長","answer":"これを考えることであって、スタンスを変更したとか、全くそれは筋違いの話なんです。その流れに沿って、やはり未来永劫と言いましたが、その未来が今、ここに来たと考えていただければと思います。","id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どうとらえているんでしょうか。この小規模校の問題を問題であるというのは、どこから出てきたのか、改めてお伺いします。","respondent":"長田教育次長","answer":"確かに、いろいろな要素はあると思いますけれども、学校教育には指導要領に基づいて実施をしていくというような部分があります。その少人数で指導する部分もあるし、こういう場合については、その中で実施をするというようなことが基本だろうと思っています。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"責任の所在を明らかにしてほしいと求めましたが、そうは思いませんでしょうか。批判も届いていますけれども、今こそ本当に選択制の見直しが求められていると思いますが、いかがか尋ねました。","respondent":"長田教育次長","answer":"これについては、順次建て替えをしていく予定ですので、その途中だとご理解をいただければと思います。今、逆にそういった選択ができないことのほうが、私どもは問題だと考えています。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問","question":"コスト論についてお伺いをしたいと思います。この点についてお伺いしたいと思います。","respondent":"長田教育次長","answer":"こういうような観点から、検討してきたわけですので、コスト論があって、それに基づいてやってきたわけではないと。学校のあり方を検討していくときには、検討をしていくべきだというような趣旨で、この教育委員会については説明を申し上げたところです。","id":"exchange-058"},{"speaker":"飯沼委員","kind":"意見","question":"大事な学校のあり方を論議する審議会なんですが、当然、公開であるべきであると思っています。ぜひこの点を説明するよう求めました。","respondent":"長田教育次長","answer":"そういった話の中で、例えば具体的な学校名を挙げて議論をするというようなことは、必ず必要になってまいります。ただ、この部分につきましては、中間のまとめ等の中で、できるだけ早く出して、区民の意見を聞くような機会も設けたいと思ってあります。","id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問・要望","question":"議事録はどうなんでしょうか。来年４月、合併してから、４０人クラスにいられなかったらどうしたらいいんだろうか。","respondent":"長田教育次長","answer":"それからあと、一緒になることによって不安だというような話も確かに説明会の中で出ておりました。２つの学校については、統合に向けての検討も行っておりますし、要するに成果の上がる形というようなことで検討しています。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私の周囲には、国民年金でも入れる施設をつくってほしいという声がたくさんあります。区民の願いに反し、特別養護老人ホームの建設を拒否をしていますが、その理由を改めて説明を求めました。","respondent":"木下福祉高齢事業部長","answer":"この部分については、これまでの特別養護老人ホームで基本的な対応ができていると考えております。１つの流れとしては、ケアホームと、それから適宜グループホームを組み合わせる形で施設の整備をしているです。","id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問・要望","question":"個室、ユニットケアで行われていますが、この新型特別養護老人ホームとケアホーム西五反田との違いを教えてほしいと求めました。特に施設設備、職員配置、利用料金、建設に当たっての補助金などを説明するよう求めました。","respondent":"木下福祉高齢事業部長","answer":"３つで構成されていまして、介護サービスの部分、これは介護報酬で対応。その中でいいサービスを提供するということはなかなか難しいところがあるということであります。","id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私はケアホームのニーズがどれくらいあるのか、改めてお伺いをするのと、国民年金で入れない人を一体今後どうしたらいいのか。介護の格差がつくこの点に対してどう思うのかということと、特別養護老人ホームの待機者も改めて示すよう求めました。","respondent":"木下福祉高齢事業部長","answer":"それから国民年金の方のお話がございまして、確かに区民の中には、そういう方もおられるというふうに認識を当然しています。もう少し低廉な利用料で事業を遂行していきたいということで、今、鋭意検討しています。","id":"exchange-063"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ特別養護老人ホームをつくってほしいと求めました。ぜひケアホームでも入れる減免制度をお願いしたいと思います。","respondent":"木下福祉高齢事業部長","answer":"ケアホームに減免制度というのは、私どもとしては考えておりません。なるべく全体としてバランスがとれた、比較的低廉な部屋も提供するという考え方で、今後とも進めていきたいと考えています。","id":"exchange-064"},{"speaker":"川西委員","kind":"質問","question":"１番目に幼保一体施設の今後について伺います。就労に関係のない人が入園できる制度を拡大していくのかどうか、どちらでも構わないわけですけれども、その辺について区の方針を伺います。","respondent":"古川児童保健事業部長","answer":"今、基本的には等しく育つための環境づくりをしていきたいということで、まずは幼保一体施設に取り組んだのが平成１４年でございました。こういったものを活用しながら、当初申し上げました課題の解決のために教育環境の整備に努めてまいりたいと考えています。","id":"exchange-065"},{"speaker":"川西委員","kind":"質問・要望","question":"１つは今、品川区が進めているさまざまな制度については、大変感謝をいたしております。認証保育所に子どもを通わせる保護者への補助金のことをぜひお考えほしいと求めましたが、この辺について、答えるよう求めました。","respondent":"古川児童保健事業部長","answer":"解消に努めてありますが、なかなか認可保育園で、すべてのお子さんの保育需要におこたえするのは難しいというのが現実です。何らかの助成が必要ではないか、このような観点から今、鋭意検討しています。","id":"exchange-066"},{"speaker":"川西委員","kind":"質問・要望","question":"そこで質問ですが、区民の声を聞くことについてのお考えをどのように進められようとしているか、伺います。ああいうものが大変子どもは好きですから、そういう交通博物館的なもの、あるいは青少年センターみたいなもの。","respondent":"福田企画部長","answer":"したがいまして、例えばパブリックコメントなどを通してお聞きするということも１つの手法だろうということで検討させていただきたいと考えています。","id":"exchange-067"},{"speaker":"川西委員","kind":"質問・要望","question":"もらうんじゃないんですから。それで緑化なら何とか区長は動いてくれるのかなと思いますので、ぜひ。","respondent":"岩田まちづくり事業部長","answer":"その後検討するという段階ですので、この動きは、区は常に注視してまいります。第２大井伊藤町住宅につきましては、鋭意検討し、調査しています。","id":"exchange-068"},{"speaker":"川西委員","kind":"質問・要望","question":"あるいは管理人は２４時間常駐で、緑化については指導の範囲ではあっても、その後の手入れを義務づけて報告させるなどの要望が出されています。質問ですが、３つ目はワンルームマンションの指導要綱の見直し、定期的な報告義務等についてのお答えをほしいと求めました。","respondent":"岩田まちづくり事業部長","answer":"工場立地法が変更になって、昭和４０年代から大規模な工場が立地できなくなり、そのように大きく土地が変換になってまいりました。いろいろ検討していく必要があると考えておりますし、何年かして、こういったこともいろいろ研究をさせていただきたいと思います。","id":"exchange-069"},{"speaker":"川西委員","kind":"質問・要望","question":"実際に資源化されるプラスチック類がどう処理されていくのかというのを、自費負担でもいいですから、そういう機会を設けて欲しいと思います。それで研修機会を設けて、資質の向上を積極的にやっていただきたいと思うのですが、２つ質問いたします。","respondent":"岩崎環境清掃事業部長、木下福祉高齢事業部長","answer":"そういう意味で、そういうことがうまくできるかどうか、予算の中でいろいろと検討してまいりたいと思います。それからもう１つは、それの一環でもあるとは思いますけれども、資源追っかけ隊も拡充することができるかどうか… 実は平成１６年度に全利用者のアンケート調査をやったときには、大変満足と、まあ満足で９３.６％。","id":"exchange-070"},{"speaker":"須貝委員","kind":"質問","question":"５点に対しまして、総括質問をします。その中身について説明を求めました。","respondent":"日下部企画財政課長","answer":"それからさらに、主要５課題をめぐる財調協議の決着によりまして、学校改築の特別交付金といったものが新しく出てまいりました。以上のような理由によるものです。","id":"exchange-071"},{"speaker":"須貝委員","kind":"意見","question":"そして年度末の３月には倍の２００億円となっておりますが、もう一度だけこの３月に対して、どうして急に倍ぐらいの歳入が入ってきたのか。それについて、説明を求めました。","respondent":"日下部企画財政課長","answer":"さらに、国庫補助金や特別区債などの特定財源、加えまして、地方譲与税、それから地方消費税の交付金、これも大きな金額が３月に入ってきております。このような理由によるものです。","id":"exchange-072"},{"speaker":"須貝委員","kind":"質問","question":"歳出も通常月の歳出は平均約９１億円となっておりますが、年度末の３月は１４９億円と、約１.６倍という数字になっております。この中身についても説明を求めました。","respondent":"日下部企画財政課長","answer":"支出につきましても、年度末ですので、かなりこれが集中してまいります。主なところを申し上げますと、例えば各種の補助金でありますとか、あるいは起債の償還分、この辺が主なところです。","id":"exchange-073"},{"speaker":"須貝委員","kind":"意見","question":"この１０８億円の黒字を合わせた、１３５億円が実質は黒字と考えられますが、支出という扱いにされてしまいます。この処理はまことに不思議だなという気がするんですが、その理由について説明を求めました。","respondent":"日下部企画財政課長","answer":"それから続きまして、基金の積立、あるいは起債の償還に充てるということが義務づけられているというものです。区といたしましては、余裕財源の使途をできるだけ早い段階で確定しまして、そしてその有効活用を図れるように処理をしているというものです。","id":"exchange-074"},{"speaker":"須貝委員","kind":"意見","question":"なぜ品川区の決算は、一般の手法と違うのか。それに対して、どのようなご見解をお持ちなのか、説明を求めました。","respondent":"日下部企画財政課長","answer":"これが経営状況を判断する上での１つのメルクマールになってくると思います。この辺が１つの評価のポイントの違いになっておりますので、あるいは会計上の１つの仕組みの違い、こういったことでご理解をいただきたいと思います。","id":"exchange-075"},{"speaker":"須貝委員","kind":"意見","question":"これは総予算の１０％以上の予算が要は固定費として、特定の財源にしか使えなくなるということは、果たしていいことなんだろうかと。そのうち二、三％でも区民に直接かかわる事業にもっとお金が使われるべきじゃないかなと思いますが、ご見解を説明するよう求めました。","respondent":"日下部企画財政課長","answer":"さらに、平成１８年度の時点では平成１９年度、今年度の国文学研究資料館の取得といったものも控えておりました。こういった観点から、基金の積立を行ったものですので、その辺は十分ご理解をいただきたいと思います。","id":"exchange-076"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川区の収支決算も同じく、当年の４月１日から翌年の３月３１日ですが、平成１８年４月から平成１９年５月までの１４カ月間が記載されています。１４カ月間になっていると思いますが、どういうわけでこうなっているのか、わかりやすく教えてほしいと求めました。","respondent":"日下部企画財政課長","answer":"これは３月いっぱい可能ですけれども、出納までその３月中に完了するということはできませんので、取り扱われるというルールが定まっているものです。これが会計処理上の基準になっておりますので、こういった民間と役所の会計処理上の違いによるものと理解をしております。","id":"exchange-077"},{"speaker":"須貝委員","kind":"質問","question":"そして人件費やその会社の保有する機器・設備など会社の経費も違うわけですから、見積金額が１０％や２０％違っても、それは当たり前だと思います。この見積もりに参加できる業者はおよそ１０社ぐらいしかいませんが、なぜこのように１０社ぐらいということで限定されているんか尋ねました。","respondent":"田中総務部長","answer":"予定価格と、私どもの入札予定価格というのは、積算をしたものです。ちなみに、これが全く予定価格と、それから業者の入札に入れていく数字が必ずしも近寄っているというふうには一概には言えないかなと思ってあります。","id":"exchange-078"},{"speaker":"須貝委員","kind":"質問・要望","question":"平成１９年６月２０日から建築基準法の一部改正があり、書類上の建築確認検査の手続が変わりました。短期間でもいいですから、なぜ人を増やそうという努力をしていただけないか、ちょっとその辺についてご見解を説明するよう求めました。","respondent":"谷田部まちづくり事業部次長","answer":"制度改正を受けまして、まだ３カ月余の時間の経過です。事業部を挙げて、何とか協力体制で乗り切っていきたいということで、新たな人員の体制は考えていないです。","id":"exchange-079"},{"speaker":"須貝委員","kind":"確認","question":"ということは、やはりそれだけ先ほども話がありましたが、半分ぐらい前年度と比較して、建築確認の申請着工も減っているわけです。その辺について、それでも増やすおつもりはないか尋ねました。","respondent":"谷田部まちづくり事業部次長","answer":"それから審査に、従来２１日間の審査期間、これは今回、３５日に延長されました。おおむね１カ月程度で確認ができてありますので、事前の相談の中で十分対応することによって、区としては対応しているという状況です。","id":"exchange-080"},{"speaker":"須貝委員","kind":"意見","question":"なぜなら、そこに車がとまっていたら、どんどん火が移って、延焼して、その幹線道路も歩けなくなるんじゃないかなという見解も出ております。つくる、そして今言った学校にも、体育館にもそういう冷暖房の設備を設けるということに対してご見解を説明するよう求めました。","respondent":"田中区民生活事業部長","answer":"こういう形で、長期にいるのではなくて、戻る形で対応していきたいと考えています。トイレですとかいうものを設置したらというお尋ねですが、避難所の機能については、そういう面ではこの間充実させてきたところだと考えております。","id":"exchange-081"},{"speaker":"須貝委員","kind":"質問","question":"私、ちょっと１つだけ質問しますが、町会や自治会が災害用品等を備蓄できる倉庫を、そういう場所を区のほうで提供していただけないか。そういうことも要は自分たちの町会は自分たちで守るということも私、大切な一環だと思うんですが、その辺についてご見解を説明するよう求めました。","respondent":"田中区民生活事業部長","answer":"その後での物資の配布等考えますと、かえって非常に手元に届かないということになってしまうのではないかということを考えていますので、それから避難所の体系というものが一番効果的な形で対応できると考えています。","id":"exchange-082"},{"speaker":"須貝委員","kind":"質問","question":"学校にあるんでしょうかということが第１と、やはり身近な町会、自治会にお願いするということが私は大切なことじゃないかなと思います。その点について、品川区教育委員会としてはどのようにお考えなのか、説明を求めました。","respondent":"長田教育次長","answer":"５割近い受験というようなことがあるのも事実ですし、それから事実、２５％の子どもたちが私立に行っているという事実もあります。ただ、人間性の育成というようなことが公立学校の責任として、やっぱりその部分は果たしていかなければならないんだろうと考えているところです。","id":"exchange-083"},{"speaker":"須貝委員","kind":"質問","question":"それは家庭の事情もありますが、考え方もあると思いますが、やはりその辺、１つの指標として、私は考えなければいけない１つかなと。これについてどのように思われますか尋ねました。","respondent":"長田教育次長","answer":"あるいは学力という部分を求めて、そういう層があるというようなことは、教育委員会とも把握をしています。ただ、さまざま難しい部分がありまして、教育委員会でもその辺のところはすべきではないだろうと思ってあります。","id":"exchange-084"},{"speaker":"須貝委員","kind":"意見","question":"１つだけ、ちょっと根本的なことをお聞かせ願いたいんですが、どうすれば子どもたちの学習能力が上がると思われますか。それだけちょっと教育委員会の見解を説明するよう求めました。","respondent":"長田教育次長","answer":"日常の指導する中で、その子が得意とする分野ですとか、あるいは不得意とする分野を教員がどう見きわめるかといった能力が必要になってまいります。その見きわめた中で、これは個別指導なり、少人数指導の中でそういった部分を対応をしていけばよろしいのかなと考えています。","id":"exchange-085"},{"speaker":"須貝委員","kind":"質問・要望","question":"もっとそういうカリキュラムというんですか、学習能力向上のそういうシステム、制度をつくったらいかがか。学習能力を上げるという仕組みが今、この教育委員会に求められているんじゃないかと思うんですが、いかがか尋ねました。","respondent":"若月教育長","answer":"こういったようなことを考えると、二項対立的なものの考え方ではなくて、さまざまな教育の方法というものをバランスよく組み合わせていく。これがやはり一番大事だろうと、私たちはそう考えています。","id":"exchange-086"},{"speaker":"須貝委員","kind":"質問・要望","question":"何しろ、私は何とか塾ならできる、学校だとなかなかおくれていく、やはりそこの現実はしっかり見きわめてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"},{"speaker":"西本委員","kind":"確認","question":"初めに財政的支援から、現状の確認、それから将来にわたっての考え方を聞きたいと思います。財政的な支援のあり方、保育政策の考え方についてお聞きしたいと思います。","respondent":"古川児童保健事業部長","answer":"今後、在宅子育てのしやすい環境づくりをさまざまな角度から検討していく必要があるだろうと。最終的には所得の低い方への経済的負担の支援といったものは一定程度必要だと思ってありますけれども、応益それぞれの制度を十分に踏まえた。","id":"exchange-088"},{"speaker":"西本委員","kind":"質問・要望","question":"ここでちょっと確認をさせていただきたいのですが、今、税制の法改正があります。それをいかに理解していただいてというところが必要かと思いますが、その考え方についてお聞きしたいと思います。","respondent":"古川児童保健事業部長","answer":"毎年予算編成までにはさまざまな角度から検討していますし、いわゆる保育園の利用料につきましても、毎年そういった観点から精査しています。平成１６年１０月に一定の改定をし、そういったことにつきましても、一定の考慮していく時期がそろそろ来るだろうと考えています。","id":"exchange-089"},{"speaker":"西本委員","kind":"質問・要望","question":"今、それらの施設間の違いというのは何だろうというところが疑問として出てくるわけですが、それらの考え方はいかがでしょうか。品川区の見解をお聞きします。","respondent":"古川児童保健事業部長","answer":"一番代表的なのは幼保一元化の考え方がさまざま議論され、幼稚園・保育園に限らず、一定の制度上のものは残るだろうと思ってあります。もう１つの新しい視点として、今後私どもは検討していく、このように考えております。","id":"exchange-090"},{"speaker":"西本委員","kind":"質問","question":"私のほうも、この間の動きを見ておりますと、幼稚園のあり方って、どういうことなんだろう、どうあるべきなんだろうか。将来的にそれぞれの施設をどういう考え方で、子育て支援という形で持っていこうとしているのか、将来についてのお考えをお聞きしたいと思います。","respondent":"古川児童保健事業部長","answer":"私は制度はそのまま、ものによっては、残していくものがあるだろうと思ってあります。当然支援はしてまいりますけれども、あるいは保護者が選択しやすいような環境を私どもは手助けしていく必要があるだろうと考えております。","id":"exchange-091"},{"speaker":"西本委員","kind":"質問・要望","question":"保育ママ利用者のことですけれども、２７０人から２,５００人と、１０倍に増やしていきたいというような目標も掲げているという報道もありました。それよりも実態に即した保育体制の施策も図るべきではないだろうかと考えますが、ご見解をお聞きしたいと思います。","respondent":"古川児童保健事業部長","answer":"当然に子育て支援が必要な部分がありますので、これは児童福祉法の改正を待つことは到底今すぐにというわけにまいりませんので、実は考えてあります。いずれにいたしましても、いろいろな視点から、子育て支援の施策については、十分な検討をしてまいりたいと考えています。","id":"exchange-092"},{"speaker":"西本委員","kind":"質問・要望","question":"どうしてもという方に利用していただくのは当然ですけれども、十分に検討して考えていただきたいと考えています。安易に利用しない環境も必要ではないかと考えておりますが、考え方をお聞きしたいと思います。","respondent":"古川児童保健事業部長","answer":"環境を整えてまいりますと、それを使う方々が、さまざまな理由をもってお使いになるわけです。１０時までの夜間延長保育、必要か必要でないかという判断は、私どもも求めていきたいと考えています。","id":"exchange-093"},{"speaker":"西本委員","kind":"質問・要望","question":"保育園ＰＴＡというのが全園にできたわけですけれども、私はこの保育園ＰＴＡを全部の保育園に早くつくってくださいということを要望いたしました。同時に保育士たちの意識をどう変えていくのかということについて、お聞きしたいと思います。","respondent":"古川児童保健事業部長","answer":"まずもって親自身が育つ場であり、そしてまた子どもとともに成長する、いい機会であろうと考えています。このＰＴＡ活動を十分に支援をしていきながら、親と、そして保育士がともに育つような環境もまた考えていきたいと思ってあります。","id":"exchange-094"},{"speaker":"西本委員","kind":"質問・要望","question":"長期にわたって、品川区の公有地がどうなっていくのか。事業を展開していったらいいのかというところの視点を考えてほしいと求めましたが、区の考え方をお聞きしたいと思います。","respondent":"福田企画部長","answer":"それからもう１つは、ちょっと大げさかもしれませんが、国全体のことに活用するということも視点としては忘れてはならないだろうと考えています。","id":"exchange-095"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、その中で地域をどういうふうに見ていくのかというところは、そのまちをつくっていただきたいという視点も必要ではないかなと考えています。例えば地域全体の役割であるとかということも含めて、今後、どのようにして地域のご要望にこたえていくのかについてお聞きしたいと思います。","respondent":"福田企画部長","answer":"こういう２つの側面があります。やはりそこにその地域の方たちのご意見を区が十分に伺って、そうした調和のある施設をその地域に配置する、これが基本だろうと思います。","id":"exchange-096"},{"speaker":"西本委員","kind":"質問・要望","question":"この中で、品川区はまずケアホームをどうしてここに持ってきたのかということについて、お聞きしたいと思います。それから同時に、幼保一体施設をここに持ってきた経過、理由を今までの総括的にまとめてお話をほしいと求めました。","respondent":"福田企画部長","answer":"幾つかの基本を区は考えておりまして、例えば今の社会経済環境を考えますと、子育て支援に関する区民の期待が相当高まっているということ。こういうような、あの地域に関しての総合的な考えに基づいて、それぞれの複合施設としたというものが基本です。","id":"exchange-097"},{"speaker":"西本委員","kind":"質問","question":"どういう理由で、将来、これらのニーズをどういうふうにとらえているのかということをまず１つお聞きしたいところです。これはどうして民設民営にしたのか、公設公営との違いについてもお聞きしたいと思います。","respondent":"木下福祉高齢事業部長、古川児童保健事業部長","answer":"これからの高齢者の、現在、このケアホームを基本にグループホームを組み合わせる方式をとっているということであります。まだ３割弱ということでありますので、基本的には、これまでの考え方で進めていきたいと考えているところです。 幾つか保育園、幼稚園がありますけれども、将来的な需要を見越した中での１つの考え方。もう１つは、幼稚園や保育園というものの一体的な教育・保育環境をつくっていきたいというのが私どもにとっての１つの考え方です。","id":"exchange-098"},{"speaker":"西本委員","kind":"質問","question":"それは大体わかっているんですけれども、保育園で民設民営というのは、品川区にとって初めてなんです。企画部として、この全体として、こういう手法を今後どういうふうな考え方で使おうとしているのかというところをお聞きしたいと思います。","respondent":"福田企画部長","answer":"こういうようないろいろな要素をさまざま検討した上で、いわば白紙から検討した上で、こういう場合はこうだというような直裁的なものではないと考えています。","id":"exchange-099"},{"speaker":"西本委員","kind":"質問・要望","question":"ここは地域の方たちが見ていくというところですが、ぜひ検討していただきたいのは、既存のＮＰＯ団体という新しい手法を取り入れていただきたい。運営をしっかりとしていただくような、住民側があまり負担にならないような手法を取り入れていただきと考えますが、いかがか尋ねました。","respondent":"田中区民生活事業部長","answer":"ウェルカムセンター原につきましては、地域の住民を主体にした検討が行われています。行政側から押しつけていくということは、今の自主的に検討を積み上げていくということと、十分うまく検討が進むように支援はしていきたいと思います。","id":"exchange-100"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひ、この地域ですね、学識経験者、ＮＰＯをぜひ使ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-101"},{"speaker":"市川委員","kind":"質問","question":"そこで行政として、地域特性に合わせた取り組みとして、どのようなことをしているのでしょうか。区民への働きかけもおのずと違ってくると思いますけれども、どういうところに重点を置いてやっているのかということを伺います。","respondent":"田中区民生活事業部長","answer":"実際、防災訓練等の訓練項目等は地区の防災協議会で検討して、確定して実施されるということになっております。なお、その一例ですが、防災訓練の中で、八潮の高層住宅での訓練ですが、階段避難機を使った要援護者を避難させる訓練等も実施しています。","id":"exchange-102"},{"speaker":"市川委員","kind":"質問","question":"区としては高層建築物には建築計画に共同備蓄場所を複数階に義務づけるなどして、付置義務を条例化していくぐらいの予防対策が必要かと思います。見解を伺います。","respondent":"田中区民生活事業部長","answer":"都市型の災害として、エレベーターの閉じ込め等、いろいろあります。こういう対応を今回の地域防災計画の中で取り込んでいますが、今後の高層階で長期にわたって生活する場合、今後検討していきたいと考えています。","id":"exchange-103"},{"speaker":"市川委員","kind":"質問・要望","question":"実際の運用はどういうところで示されているのでしょうか。例えば都立高校６校と、ほぼ１０年前に協定を結んでいますけれども、１０年間の間に何回協議の機会があったんか尋ねました。","respondent":"田中区民生活事業部長","answer":"３点目ですが、ある面で非常にベテランの職員が多いので、臨機に対応するところがあります。高校・大学等と結んで、避難所ですとか、そういうところで連携・協力して対応するようにしています。","id":"exchange-104"},{"speaker":"市川委員","kind":"質問・要望","question":"区民の皆様と学習会を持ったときも、特に都立高校との協議会についてはしっかり協議を行っていくように要望いたします。校庭で行うだけでなく、実際に学校に入って避難する教室の確認などもできるように、その辺の取り組みがどのように行われているのかを伺います。","respondent":"田中区民生活事業部長","answer":"避難所の訓練は全体で２４校で行われています。備蓄倉庫等から食料、備蓄資材を出したり、簡易トイレを組み立てたりというような形での訓練を行っているところです。","id":"exchange-105"},{"speaker":"市川委員","kind":"質問・要望","question":"１つは、どれほどまでに他の学校との差異化、つまり学校間の多様性が達成されたのか、お伺いします。２つ目は、２２％にとどまったという結果を受け、伺います。","respondent":"長田教育次長","answer":"プラン２１に基づきまして、その教育の内容につきましては、品川区の小中一貫教育指導要領に基づいて実施をしています。各校とも統一の要領に基づいて実施をしておりますから、こういった部分では、ある面平等です。","id":"exchange-106"},{"speaker":"市川委員","kind":"質問・要望","question":"そもそも、一連の改革は何を目的としたものなのか、改めて確認をさせてほしいと求めました。この点について、見解を伺います。","respondent":"若月教育長","answer":"したがって、どういう学校に入ろうと、形態がどうであろうと、そこの受ける教育の質といったようなものに差はありません。その辺をひとつ、しっかりと整理をして見ていっていただければと思います。","id":"exchange-107"},{"speaker":"市川委員","kind":"質問・要望","question":"このご見解をお伺いいたします。今後、統廃合が懸念される場合の対応と、このような他区の動きに対しての感想もあわせて伺います。","respondent":"長田教育次長","answer":"今、個別の課題について検討をいただいているところですので、そういった問題については既に決着がついている問題かなと思っているところです。","id":"exchange-108"},{"speaker":"市川委員","kind":"質問","question":"先ほど、理由について伺いましたので、それを答弁というふうにします。審議会が公聴会を開くというふうに決めれば、市民の声を聞くことができるのか、この点について伺います。","respondent":"長田教育次長","answer":"９月４日だと思いますけれども、この部分をどうするのかという検討をしていただいた結果、この非公開というものを決定してきたわけです。学事制度審議会の中で、そういう要請が出てくれば、これは区としても検討するという内容だと理解しています。","id":"exchange-109"},{"speaker":"市川委員","kind":"質問・要望","question":"学事制度審議会が、ぜひ市民の声を聞くというところに立っていただきたいと期待をいたします。ご見解を伺います。","respondent":"若月教育長","answer":"例えば競争といったようなものが起こす弊害といったようなものもちゃんと見通して、そういう弊害が起きないような手を打って進めていることです。ぜひよろしくお願いいたします。","id":"exchange-110"},{"speaker":"市川委員","kind":"質問","question":"教師の資質の向上とか、教育現場が忙しくなっているんじゃないかなと想像するんですけれども、現場はどうなんでしょうか。教育現場の実態について、少しお伺いいたします。","respondent":"若月教育長","answer":"そしてそういった親御さん方に対して対応していく。１人にかかる負担は増えていることは間違いありませんので、独自採用でもって円滑な学校経営を進めていこうというのも１つのあらわれであります。","id":"exchange-111"},{"speaker":"市川委員","kind":"質問・要望","question":"今期の決算特別委員会の中でも児童生徒、先生のメンタル面の支援ということで、多くの税金が使われていました。そういう教育現場をつくることを大切にしていただきたいという、私の意見を申し上げまして、私の質問を終わりにいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-112"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"さらに児童生徒の健全育成のために、教員のスキルアップや親育など、総合的な教育施策の展開も強く要望します。最後に、我が会派が行政と車の両輪となるべく、真剣かつ真摯に取り上げた意見・提言を前向きに検討され、実現されることを強く要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-113"},{"speaker":"堺委員","kind":"提案","question":"初めて１,３００億円台を超えた、また我が党が提案をしてきた不妊治療助成制度の創設や、多くの施策が予算化されておりました。我が党の委員が款別審査や総括質疑の中で提案をしてきた、要望いたしまして、意見表明といたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-114"},{"speaker":"宮崎委員","kind":"質問・要望","question":"丸井が撤退するのに、なぜ需要調査も行わず、大規模開発を推進するのでしょうか。改めて３０人学級の実現を強く求めるものです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-115"},{"speaker":"川西委員","kind":"質問・要望","question":"区民要望に耳を傾けるよう、配慮されたい。子育て世代から高齢者まで、品川に住んでよかったと言われる施策の展開を今後とも、区施策に展開されるよう要望いたしまして、意見表明を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-116"},{"speaker":"須貝委員","kind":"質問・要望","question":"以下、意見と要望を述べします。所得格差が広がる中、品川区民同士が支え合う仕組みづくりを要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-117"},{"speaker":"西本委員","kind":"提案","question":"以下、その理由と幾つかの意見・要望を申し上げます。我が会派委員が提案、要望した各項目について、区政運営に生かしていただくことを願いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-118"},{"speaker":"井上委員","kind":"提案","question":"創意工夫の新規事業は政策決定にポイントが高いようですが、公がすべきかどうかという政策判断は慎重に行うことを要望します。この決算特別委員会で提案した意見を来年度の予算編成に生かしていただき、だれもが安心できる生活を実感できる品川区となることを要望しとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-119"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/570060?Template=document&Id=1288#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":113642,"voices":255}},{"id":"h19-20071022-8","meetingId":"h19-cm10","date":"2007年10月22日","dateIso":"2007-10-22","committee":"建設委員会","time":"午前１１時０２分～午後 ３時４９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件整理しています。","topics":[{"id":"topic-01","title":"はじめに(1)の第１８回東京都道路整備事業推進大会","agenda":"はじめに(1)の第１８回東京都道路整備事業推進大会","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"毎回、この大会で大会決議を挙げられていると思うんですけれども、今年の大会決議はどういう内容なのか。そして、決議案というのは、どのように決まるのか、それを説明するよう求めました。","respondent":"阿部都市計画課長","answer":"きょうの午前中に代表役員会が開かれておりまして、その中で決定するものですので、私のほうは事前には入手しておりません。式次第の１１にありますけれども、賛同いただいたら、大会決議にするというものです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"ないままに、なぜそこに出席をして、その内容について賛成するのか、その考えを聞きたかった。この大会上、どういうふうに位置づけられているのか、その２点を説明するよう求めました。","respondent":"阿部都市計画課長","answer":"今、申しましたとおり、案につきましては、この場で提示されるわけですから、その場で、それに賛成の決議をしていくということが１点目です。反対を問うということではなくて、この場で決議をするですので、反対意見を言う場はございません。","id":"exchange-002"},{"speaker":"中塚委員","kind":"意見","question":"昨年の大会決議案を見させていただきましたけれども、結局、３環状線整備を進める内容になっており、共産党としては、この計画には賛同できません。意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"よく共産党の中で話をしてほしいけれども、申し合わせ確認事項は直さない、休憩中だから配慮をするということで話は保留になっている。申し合わせ確認事項を直そうとやったときに、それをこの場で行かないと公言する話ではないと思いますので、その点をしっかり仕切っていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"申し合わせ確認事項の変更については、大いに議会運営委員会のほうで議論をしてほしいと求めました。ここで、私はこれ以上は言いませんけれども、ぜひそこで進めて、実態に即して、申し合わせ確認事項を変更していく、そういう問題だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"提案","question":"その提案があって、議会運営委員会で提案があったわけでもない、申し合わせ確認事項はそのまま生きている。申し合わせ確認事項を直してくれということを、議会運営委員会の中で提案をすることができたわけで、そんな内容の提案があってもとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"中塚委員","kind":"確認","question":"議会運営委員会で、申し合わせ確認事項を変えるべきだという主張は述べさせていただきました。今の委員の経過の説明には納得できません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]},{"id":"topic-02","title":"の都市高速道路中央環状品川線南品川換気所建設に伴う準備工事説明会の開催","agenda":"の都市高速道路中央環状品川線南品川換気所建設に伴う準備工事説明会の開催","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"今の説明の中で、近隣町会に説明した上で、このチラシを配布したというお話でしたけれども、どういう範囲で配布をしたのか、説明を求めました。","respondent":"阿部都市計画課長","answer":"配布の範囲ですけれども、裏面に、南品川換気所用地とありますけれども、ここに建つのは高さ３０ｍの換気所を予定しております。説明の範囲としては、その高さの２倍の範囲と聞いております。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"２Ｈの高さでチラシを配布したということでよろしいわけですか。前回、１回目の説明会があったときに、５０ｍの範囲で配布をしたそうですけれども、今回、２Ｈとなると、それ以下ということになるのか尋ねました。","respondent":"阿部都市計画課長","answer":"今の５０ｍの範囲と申しますのは、事業説明会のときの範囲でございまして、それは、計画道路から５０ｍの範囲というような配布の仕方です。今回は、今申し上げましたとおり、今度建ちますのは３０ｍの高さですので、その高さの２倍の範囲にチラシを戸別配布したです。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"一度上がったのが８００ｍの範囲に降り注ぐという説明があるわけですから、せめて、こういう工事が行われますという周知は行うべきだと思うんです。今の高さ２Ｈだけの範囲というのは、非常に納得できないと思うんですけれども、いかがか尋ねました。","respondent":"阿部都市計画課長","answer":"委員がおっしゃった８００ｍというのは、既に事業説明会の後も、町会単位に説明会を個別にしております。そういう意味では、かなり広い範囲に丁寧に説明をしていると思います。","id":"exchange-010"},{"speaker":"中塚委員","kind":"意見","question":"かなり広い範囲って、結局、このチラシは、高さの２Ｈの住民の方にしかお配りしないわけですよね。広範囲にきちんと工事の説明を周知、徹底ということをするべきだと、私は思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"井上委員","kind":"質問","question":"私は地元で、ここをいつも通っている場所ですので、その辺のことをお願いします。換気所用地の反対側に通れる場所をつくるということですから、２８ｍ先に行くということになるかと思うんですが、それを説明願います。","respondent":"阿部都市計画課長","answer":"先ほど説明しなかったんですけれども、今回は、換気所の工事ではない。ですから、こちら側の子供の森公園側も若干は狭くはなりますけれども、歩行者、あるいは自転車が通れる通路は確保するということです。","id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"すみません、ちょっと関連して教えてほしいんですけれども、ピンクの通路の幅を教えていただきたい。こっちで赤で書いてあるのに、ピンクのところがちょっと切れちゃっているじゃないか尋ねました。","respondent":"阿部都市計画課長","answer":"現状は２.５ｍありますので、若干狭くなるです。もう一つの空白というのは、ここにつきましては、現状が確保されるんだろうと思っています。","id":"exchange-013"}]},{"id":"topic-03","title":"の平成１９年１１月都営住宅（世帯向・単身者向等）の募集","agenda":"の平成１９年１１月都営住宅（世帯向・単身者向等）の募集","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"今の説明の中で、品川区内の都営住宅の募集はどういう状況か尋ねました。","respondent":"齋藤住宅課長","answer":"まだ都から資料がきておりませんので、届きましたら皆さんにお配りしたいと思います。","id":"exchange-014"},{"speaker":"井上委員","kind":"質問・要望","question":"職員の参加が増えなければいけない、区の中での割り当てのような話もありまして、その辺を担当課に確認をするというお話もあったかと思うんです。現状がどうなっているのか、どうなのかというところも含めて、お知らせをいただきたいと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"本多委員長","kind":"意見","question":"午後からの道路大会への出発につきましては、１２時５分ごろに放送を入れますので、第３庁舎前のマイクロバスにお集まり願います。閉会を宣する〕 ○午後 ３時４９分閉会との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/325823?Template=document&Id=3892#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":7232,"voices":41}},{"id":"h19-20071105-6","meetingId":"h19-cm11","date":"2007年11月5日","dateIso":"2007-11-05","committee":"区民委員会","time":"午後１時０３分～午後２時２６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"これは表彰関係経費の中に含まれるんですか。これは別の扱いになるんか尋ねました。","respondent":"中山地域活動課長","answer":"今年度、初めての事業としてこういう贈呈をするものです。いわゆる団塊の世代の地域連携を目指しての事業の中でご報告申し上げたものですけれども、項目というのは、新たに予算化しているものです。","id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"質問","question":"それともう１点、どっちが主体になってやっているのかなというのがちょっと気になっていたので。表彰が主なのか、ボランティア講演会とどっちが主体になっているのかなと、その辺が気になったので教えていただければと思うんですが。","respondent":"中山地域活動課長","answer":"若干の休憩の後、そのまま残っていただき、講演会を行おうというふうに考えているところです。","id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"せっかくそういうことですので、これからも各町会・自治会、それから地域センターがうまく情報を吸い上げて、きちんとした表彰を続けていただきたいということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003","title":"町会・自治会支援"},{"speaker":"飯沼副委員長","kind":"質問","question":"推薦のあった約１２０団体というのは、どこかに登録をされているような団体という受けとめ方でいいのかどうかと、選定の基準とか何かあるのか。見ると、地域的にすごく網羅されているなと思うんですが、その辺の基準がどうなっているのか説明を求めました。","respondent":"中山地域活動課長","answer":"要綱を定めて、ご説明にも申し上げたとおり、例えば無料でボランティア的な講習会を行っているような団体だとかをあわせて推薦したというものです。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"取組指針の(2)のところのリーフレットの内容の件なんですが、新しい積極的なライフスタイルであるという意識というのを、もう少しこういったイメージ・内容なんだというのを説明するよう求めました。","respondent":"田村環境課長","answer":"ウォームビズというのは、サマールックと対比しますとなかなか区民の方は見えづらい。それぞれ事業所に合った形で進めていただきたいということで、ライフスタイルに積極的に取り込んでほしいという内容で情報提供するものです。","id":"exchange-005"},{"speaker":"稲川委員","kind":"質問","question":"成果というんですか、エネルギー消費は使えば使うほど上がっていくんだろうと思いますが、下がれば。非常に中も暑いという状況の中で、例えば区民の人たちから「暑過ぎるんじゃないか」とか苦情があったのかどうか、その辺をお伺いしたいんですけど。","respondent":"田村環境課長","answer":"冒頭のごあいさつの中で「品川区はこういう取組みを進めているので、現状を見ると、その辺は理解いただいているのかなと。多少暑いなと思っても理解いただいているかなと思います。","id":"exchange-006"},{"speaker":"山路委員","kind":"質問・要望","question":"電気量を幾ら削減して、優秀なところは表彰したり、そういうことをやっている。「品川区としてこれだけの電気量、ＣＯ２を削減していますよ」ということをきちっと内外にアピールして、啓発していくということをしていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"意見","question":"周知の中のポスター関係に、ＩＳＯ事業所ネットワーク、エコクリーン事業所というのが出てくるんですけど、今現在、ＩＳＯ事業所ネットワークはどのぐらいの事業所が対象になっているのかというのと。","respondent":"田村環境課長","answer":"こうしたポスターを配布する配布先の中に、おおよそのＩＳＯ事業所ネットワークということで、現在２５０あります。","id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"質問","question":"これは助成企業だけなんですか。それともほかのも含めての数になっているのかなと。","respondent":"田村環境課長","answer":"今、配布先を２５０と言いましたが、現在の加入者数が、平成１５年度が１０５、平成１６年度が１４０、平成１７年度が１５６、平成１８年度が１７２ということで、企業のＩＳＯの認証取得をしているということです。","id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"質問","question":"これを認定したあとに、これも３年か４年目ぐらいで、もう１回見直しというのはなかったですか。１回認定するとそのまま認定はずっと続くんか尋ねました。","respondent":"田村環境課長","answer":"平成１７年度で３３、平成１８年度で３９ということなんですが、事業とすれば今現在生きています。地球に優しいお店とうまくリンクできれば、平成２０年度を最後にそっちに切りかえられないかというので、現在検討を進めているところです。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"２号炉ではいおう酸化物は法規制値を超えてしまっている状態があったんですけれども、この有害性の中身というのは、これの濃度が濃くなることで実際にどういうふうな有害性があるのかということを説明していただきたいんですが。","respondent":"秋山資源循環推進課長、田村環境課長","answer":"窒素酸化物、ＮＯｘといわれるもので、いわゆる光化学スモッグですとか、そのような中身になります。塩化水素については……。 私の方から、いおう酸化物についてですが、いおうと酸素が結合してできるもので一酸化いおう等、６種類のいおう酸化物の総称を言います。排ガス中のＣＯ２と反応してＨＣｌ、塩素を発生し、硫酸塩や炭酸塩となるという内容です。","id":"exchange-011"},{"speaker":"安藤委員","kind":"意見","question":"こういうものが排出されてしまうことにどういう影響があるのかというのはすごく不安だと思いますので、むしろ普段よりも低い値を示したというのは、何でこのようなことになるのかなというのがちょっとよくわからなかったんだけれどもとの意見を述べました。","respondent":"秋山資源循環推進課長","answer":"８月２７日から９月１日に、これは工場が排出したもの以外にも排出源がありますので、その周辺の大気の結果です。今回のシミュレーションは、通常の周辺の大気の測定結果にこのシミュレーションの計算結果が足されるというふうにお考えいただければと思います。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問","question":"乱れやすくなって、これがときには自己基準ですとか、あるいは環境基準を超えるような値が出てしまうということなんでしょうか。立下げという作業をなるべくやらないということが、そういった不安定なガスを発生することを防ぐということにつながるわけなんか尋ねました。","respondent":"秋山資源循環推進課長","answer":"炉が安定するまでごみを入れずに、都市ガスでずっと温度を上げていきまして、温度が上がった状態で初めてごみを投入するという作業をしております。立上げ、通常の立上げ、立下げ時においては規制値をオーバーするようなことはあまりないというふうに聞いております。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"そういった意味で、１１月に焼却炉をとめて、定期補修時にリレーの交換等をやるということなんですけれども、それまで、この不具合が起きたリレーというのはそのまま使用しているということになるのかということで、それで大丈夫なのかと不安があるんですけれども、そこら辺はいかがか尋ねました。","respondent":"秋山資源循環推進課長","answer":"そのリレーの不具合ということで、現在は遮断器が入った状態で「入」の信号が出ておりますので、問題なく操業しているというふうに聞いております。","id":"exchange-014","title":"町会・自治会支援"},{"speaker":"安藤委員","kind":"質問","question":"今は手動で送っているということで、継続していることなのかということと、１１月の定期補修というのは、具体的には何日ぐらいかというのは決まっているのかどうか、説明を求めました。","respondent":"秋山資源循環推進課長","answer":"手動で送っているです。それから、１１月の焼却炉の停止については、細かい日程はまだ把握はしてございません。","id":"exchange-015"},{"speaker":"稲川委員","kind":"質問","question":"１ページ目に、本当に何かが生じて、煙を外に出す前に安全停止という形のとり方でいいんですか。メーカーに対して何らかの損害賠償じゃないですけど、そういうのをする予定があるのか、その２点だけ。","respondent":"秋山資源循環推進課長","answer":"通常の故障の修理対応ということになるかと思いますので、それが大きくほかに広がっていくということではないので、特にこちらの方は。ちょっとその状況がわかりませんので。","id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"質問","question":"東京電力からの受電に復帰する試験を実施したとあるんですが、これは今回初めて実施したわけか尋ねました。","respondent":"秋山資源循環推進課長","answer":"初めてというふうに聞いています。","id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そうすると、今回はこれで、トラブルが起きた原因がわかったわけですが、今度はリレーの交換をした後で、もう１回どこかで試験をするわけですね。メーカー側の方の問題ですから当然して来るんでしょうけど、先ほど稲川委員からもあったんですが、本当は知りたいなという気もするんですけれども。","respondent":"秋山資源循環推進課長","answer":"今回の試験は、そういう意味ではできなかったということですので、リレーの修理後、ですから定期補修完了後にもう１度やるというふうに聞いてあります。","id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ですから、そのやった後に、これは事務組合の方だからうちは言えないけど、委員会で多少話も出ている中で、そうしたらその結果も報告してほしいということで、事務組合に対して要求できないかなと、その辺は考えられませんか。","respondent":"秋山資源循環推進課長","answer":"品川清掃工場と、今年の１０月１日に連絡調整会議というのを設置いたしまして、報告等を密に行うということにいたしました。そういう中で今回できなかった試験のその後の状況であるとかについては、こちらからも報告を求めていきたいし、報告がいただけるものと考えています。","id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"１回決めると同じ業者さんのままのときもあるということで、ここの管理という面では、その辺まで報告しておいていただきたいなという感じがしました。正式なものじゃなくて今のは僕の記憶ですから、今後のことの考え方だけ、ちょっともう１回確認したいと求めました。","respondent":"秋山資源循環推進課長","answer":"そういう連絡調整会議等の場でありましたことについては、委員会の方にも報告をさせていただきたいと思います。契約のことについては清掃一部事務組合の関係になりますので。","id":"exchange-020"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"どういうふうにリレーが流れなくて、ここに１号炉と２号炉の焼却炉が書いてありますけれども、灰溶融のところはとまらなかったんですか。その辺をちょっと説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"飯沼副委員長","kind":"質問","question":"それはとまっていないんですか。そのまま動いていたということか尋ねました。","respondent":"秋山資源循環推進課長","answer":"停止したかどうか、申しわけないんですけど、今の段階では影響がなかったと。焼却炉の１号、２号ということで来ておりますので。","id":"exchange-022"},{"speaker":"飯沼副委員長","kind":"質問","question":"灰溶融はそのまま１号が動いていたという解釈でよろしいですか。その点も説明を求めました。","respondent":"秋山資源循環推進課長","answer":"今回と同じような事象が過去にあったということは、品川清掃工場では聞いてございません。今回の調査・分析の結果を受けて、その情報を全工場で共有化して、再発防止を図るというふうに聞いております。","id":"exchange-023"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"ほかのところでこういう事故があったのかということを伺ったので、２号炉と書かれているんですが、この辺の法規制の基準がありますね。この数字というのはどういうふうにして導き出したのか、時間を追って測っていたのかどうか、その辺を具体的に説明を求めました。","respondent":"秋山資源循環推進課長","answer":"一般廃棄物処理の結果をとるときに、自己規制値という自主的に決めた規制値で届出をして、操業中はそれを守るという値になってあります。","id":"exchange-024"},{"speaker":"飯沼副委員長","kind":"意見","question":"ということは、これ以上高いところはなかったという、測った中での１時間値で高かった数値が最高これであったという解釈でいいわけですね。重金属類でいろいろ心配されるものがあるんですが、その辺というのは測定しているのか測定していないのかとの意見を述べました。","respondent":"秋山資源循環推進課長","answer":"排ガスの測定なんですけれども、２カ月に一遍、２６項目のものを測っております。その中には重金属類も含めて、２カ月に一遍測定をしています。","id":"exchange-025"},{"speaker":"飯沼副委員長","kind":"質問","question":"その辺というのは公表することになっているのか、特別そういう基準にはなっていないのかどうか。実際に今回のときに測定されて、前のところとの比較があったのかどうか、その辺はどうなんか尋ねました。","respondent":"秋山資源循環推進課長","answer":"２４時間測定の結果がリアルタイムに出ているですし、２カ月に一遍については、清掃一部事務組合のホームページ等で公開しているということです。","id":"exchange-026","title":"町会・自治会支援"},{"speaker":"飯沼副委員長","kind":"意見","question":"その水銀の濃度が自己規制の数値の２.２倍ということなんですけれども、その辺の評価というのはどういうふうに受けとめていらっしゃるのか。私は厳粛に受けとめてほしいなと思っているんですけれどもとの意見を述べました。","respondent":"秋山資源循環推進課長","answer":"絶対量としては、通常のものよりは当然低いということで清掃一部事務組合の方では、大気環境への影響は極めて小さいと判断できますです。","id":"exchange-027"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"起こった事故については、区民の方にも広報していただきたいなと思っているんですが、インターネットで開いて見る部分には何も載っていないんですが。","respondent":"秋山資源循環推進課長","answer":"先ほどもご説明しましたけれども、影響が極めて小さいということで、ホームページ等での公開というのは清掃一部事務組合としては考えていないです。","id":"exchange-028"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"広報をする必要があると思いますので、清掃一部事務組合の方に、その辺はぜひ伝えてほしいと求めました。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"先ほど、連絡調整会議を設置したというお話がありましたけれども、それは品川区と清掃一部事務組合との連絡調整会議だと思うんですが、こういう会議を立ち上げた問題意識と、これからどのようなペースで、どのような協議をしていくのかというのをお伺いしたいと思います。","respondent":"秋山資源循環推進課長","answer":"先ほどご説明いたしましたように、最低でも年１回、こういうような問題に一緒に対処していこうということで立ち上げたものです。","id":"exchange-030"},{"speaker":"渡部委員","kind":"質問・要望","question":"実際、同じものが二つとない機械だと思いますので、メーカーの方々にもきっちり責任等確認してもらってできればと思います。要望といいますか、空にしてやってくださいというお願いを。","respondent":"秋山資源循環推進課長","answer":"全部空にしてやってしまうと、通常の状態とはまた違ったことになってしまうので、通常の運転中にやるということをしております。このメーカーの責任で、その他のものについては同じように点検、もし必要であれば交換ということをメーカーの方に言って行うという予定です。","id":"exchange-031"},{"speaker":"山路委員","kind":"意見","question":"早速見せてもらいまして、友達にも送ったんですけれども、すごくいいんですね。品川に今住んでいる住民の１人としての実感と感覚にうまくマッチングしていると思ったんですけど、品川観光協会に著作権はあるのか、そこをちょっとの意見を述べました。","respondent":"金子産業振興課長","answer":"先ほども言いましたとおりなんですが、編集、あるいは発行責任というのはすべてＪＴＢパブリッシングの方にありまして、観光協会は協力をしたということだけですので、例えば何がしかの収入が入ることはございません。","id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"所管がちょっと違うけど、区民委員会から要望を出してもらいたいんですけど、両面通行で真ん中に駐車場があるんですよ。これは答えられないと思うので、要望にしておきます。","respondent":"金子産業振興課長","answer":"今のお話につきましては、交通安全担当の方には伝えておきます。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問","question":"そういったところにどういう影響を及ぼすのかということを、つかんでおられたのかどうか、どういう声を聞いているのかというのをちょっとお伺いしたいんですけれども。","respondent":"金子産業振興課長","answer":"３、４と３日間、あるいは徒歩でお店の方に行かれていました。そういう意味では、開店当初ということはありますけれども、今後も大井町のにぎわいに資するということは間違いないのかなと考えているところです。","id":"exchange-034","title":"町会・自治会支援"},{"speaker":"安藤委員","kind":"質問","question":"どういう不安があるのかとか、そういった活動を今からでも行うような用意といいますか、お考えはおありか伺いたいと思います。","respondent":"金子産業振興課長","answer":"大きな都市において、電器というものに限りますけれども、大きな動きが出てきているのかなというふうには思っております。これについて改めて調査をする考えはないんですけれども、そういうところに関しては、今後とも引き続いて伺っていくということです。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"区商連の方々にお話を伺っているということもあると思いますけれども、区商連のトップの方に「どういう話を聞いていますか」と聞いても。ぜひ、じかに町場の商店に入っていって、生のお話を聞いていただきたいなというのを要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"山路委員","kind":"質問・要望","question":"どういう商法で、品川区にどういうメリットがあって、区民の苦情とかいろいろな相談に乗ってあげていただきたい。正確な回答を区民に話してほしいと求めました。","respondent":"金子産業振興課長","answer":"それについてはヤマダ電機さんの方も対応するとおっしゃっていますので、その場合にはまた、改めて申し入れをしていきたいと考えています。割り振りをしていくのかということについては、私どもお聞きしていないので、その辺については参考にしてみたいと思っています。","id":"exchange-037"},{"speaker":"山路委員","kind":"質問・要望","question":"ちょっと要望しておきたいのは、大事なところですから、やっていただきたい。最も重要な文化と歴史をつくってきた地域だと思いますので、それを意識した上で、今後もいろいろ展開をしていただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"そこにぜひ心を砕いてほしいのと、大型店というのは、今、入っているところがいつまでいるかという保障もないですよね。そういった、まちを壊してしまうというあたりについても、まちづくりという視点で、ぜひ考えていただきたいんですけど、その辺かいかがか尋ねました。","respondent":"金子産業振興課長","answer":"これにつきましては、当然のことながらそれがなくなる、あるいはそれが衰退していってしまうというのは避けていかなければならないと考えています。","id":"exchange-039"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"ぜひ調査をして、じかに声を聞いて、手立てをしてほしいと求めましたがいかがでしょうか。私は職員を増やしていただきたいんですけど。","respondent":"金子産業振興課長","answer":"それから、区によっていろいろな要素がプラスになったりマイナスになったりしておりまして、単純に比較することは非常に難しいと思っているんです。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/598842?Template=document&Id=2500#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":22885,"voices":104}},{"id":"h19-20071105-7","meetingId":"h19-cm11","date":"2007年11月5日","dateIso":"2007-11-05","committee":"厚生委員会","time":"午後１時０３分～午後２時４６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"須藤委員","kind":"意見","question":"既存施設をセンターとするということなんですけれども、この場合は、昭和大学病院とか、そういった大きな病院を発熱センターとする考え方と理解しておいていいのかどうかとの意見を述べました。","respondent":"倉橋品川区保健所保健サービス課長","answer":"発熱センターというものは、資料にありますとおり、区が設置するものを発熱センターと言っております。発熱センター同様の機能を持った発熱外来として、同様に連携、協力して対応していく予定です。","id":"exchange-001"},{"speaker":"須藤委員","kind":"質問","question":"既設の施設といったら、区としては、どこをその発熱センターとするものなのかを教えてもらいたいんです。","respondent":"倉橋品川区保健所保健サービス課長","answer":"現在の計画では、区内５カ所程度ということで、今、委員からご指摘いただいたような診療協力病院です大病院、そして、区が設置する発熱センター、１から３カ所程度を予定していますが、場所等につきましては、一部未定のところがあります。","id":"exchange-002"},{"speaker":"須藤委員","kind":"質問","question":"町医者に行ってどうのというのではなくて、区が設置するセンターとしては、どういうところを考えていらっしゃるんですか。まちの人がわからなければ意味がないと思うんで、そのあたりを教えてください、という質問です。","respondent":"倉橋品川区保健所保健サービス課長","answer":"今回実施いたします品川区保健センター、南部のほうで１カ所を予定しておりますが、ちょっと公表を控えさせていただきたいと思います。設置運営訓練だけでなく、広報などとも連携をとって、有効な方策となるように努力してまいる予定です。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今回のこの訓練というのは、一般の方は一切関係ないということで、ここに書かれている方だけで保健センターで行うということなんでしょうか。その２点をお願いします。","respondent":"倉橋品川区保健所保健サービス課長","answer":"常に実施できるように、ソフトウエアの部分、手順の部分を整備してまいりたいと考えています。評価などをお願いする予定ですので、専門的な評価ということで、一般には特に公開しない方針で実施する予定です。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この５カ所というのは、もしこういうふうな事態になったら、こういうところに発熱センターができますよということをお知らせしていくわけですよね。そのお知らせできる時期とか、５カ所が、おおよそここら辺と決まる目途というのはないんですかということなんです。","respondent":"倉橋品川区保健所保健サービス課長","answer":"それと同じということではございませんけれども、場所等につきましても、公表等につきましては慎重に対応してまいりたいと考えております。実際の設置のときにつきましては、慎重に対応して、機能できるように公表等をしてまいりたいと考えています。","id":"exchange-005"},{"speaker":"宮崎副委員長","kind":"質問","question":"ちょっと伺いたいんですけれども、その後というふうになるのか、そこら辺。区内５カ所となっているんですけれども、どういう想定をされていて５カ所なのか、そこら辺のところはどうなんか尋ねました。","respondent":"倉橋品川区保健所保健サービス課長","answer":"したがいまして、そこがまず第一に対応するということで、ご指摘のとおりです。第二段階以降につきまして、先ほど、ご説明いたしましたように、各協力病院等が対応するということになっております。","id":"exchange-006"},{"speaker":"宮崎副委員長","kind":"質問","question":"そうすると、５カ所というのは、距離での想定ですか。例えば患者数だとか、そういうことではなくて、距離での想定で５カ所ということになっているんか尋ねました。","respondent":"倉橋品川区保健所保健サービス課長","answer":"主に距離ですが、大体、人口割からいきましても、ほぼそれに相当する地区割であると検討しています。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"１１番の保健事業等というところでは、その後の、保健事業に対しての国とか東京都からの財政負担の状況というのはどうなっているのかということ。それから、自己負担額が５００円となっていますけれども、これは、５００円ということでいくのか、そこら辺のことについて、まず説明を求めました。","respondent":"冨岡高齢事業課長","answer":"財政の支援について決議をしていただいたりして、第１回定例会で、場合によっては保険料については補足していくと聞いております。５００円につきましては、あくまでも広域連合が私どものほうに、５００円の自己負担を取るようにという形で事業を委託してくると伺っております。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"１１月２０日の広域連合の議会の中で条例が決定されて、そこで基本的なことが決まっていくということですが、では、条例の提案というのはいつごろに出されるのか、そして、その条例の中で決まっていく基本的な中身というのがどういう中身なのかということについて説明を求めました。","respondent":"冨岡高齢事業課長","answer":"議案説明会が１１月８日、９日あたりだったと予定が出ておりますので、そのあたりで上程がされるかと考えています。ご報告申し上げているところの部分がさらに細かく出てくると聞いておりますが、細かいものについては、まだ聞いておりません。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうことですか。１０月１０日に協議会があって、５００円に関しては、そこら辺の品川区としての方向性というのはどうなっているのかということをお聞きしたい。","respondent":"冨岡高齢事業課長","answer":"保険料率とか、均等割額とか、そういうものは載せていくと聞いております。それから、健診の部分ですが、これまでの経過、あるいは国民健康保険等との調整が必要ですので、それを踏まえながら、現在、検討しています。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"せっかくこういうふうにいろいろと協議会のほうから出されているわけですから、この資料をもっと委員のほうにも出していただきたいと思うんです。１０月１０日の資料については、こういう資料で公開されている資料があるんでしょうか、そのことを一つ説明を求めました。","respondent":"冨岡高齢事業課長","answer":"それ以後については、１０月１０日の資料と同じもの以外については、公開されているとは聞いておりません。まだ行政内部の資料だと考えます。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"８割が国民健康保険だと思うんですけれども、今回の保険料がどうなっているのかという比較をぜひ出してほしいと、前回も要望したんです。だからぜひ、そういう比較の資料を出していただきたいと思うんですけれども、いかがか尋ねました。","respondent":"冨岡高齢事業課長","answer":"難しいというのがありまして、今の段階では、ちょっと難しいかなと考えています。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"特別区の国民健康保険料ということで、１人当たりの所得別の保険料が出ていますけれども、こういうふうに実際に出ているじゃないですか。これが、今の国民健康保険料というふうに考えられないんか尋ねました。","respondent":"冨岡高齢事業課長、木下福祉高齢事業部長","answer":"これについては、確かに出ておりますのでつけられておりますけれども、これと比べて、これ以上の資料については、たしか出ていないと考えています。平成２０年度、後期高齢者医療制度が始まるときの数字と、平成２０年度の国民健康保険を正確に比較するのが難しいということであります。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"前回もそのことは散々要望として出しておりますので、この次にはぜひ、広域連合のほうで出されているわけですから。今の国民健康保険料に比べてどうなっているのかというところは、見られていないか尋ねました。","respondent":"冨岡高齢事業課長","answer":"後期高齢者については１人ということで出てまいりますけれども、一つ一つ比べていくというのは目安にはしていただきたいですが、これをもって完璧に比べるというのはちょっと難しいと理解します。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"生活に直接かかわってくる問題ですから、そこのところは、ぜひしっかりと見ていただかないと困ると思います。所得の高い方が１０万円も少なくなるという保険料というのは、何とか是正できないのかなと思うんですが、その点に関してはいかがか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"さらなる減額ができないかどうかということを、今、協議会のほうで検討している。６２自治体の中では、今、鋭意検討している最中であります。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回は多分１２４％ということで、ちょっと意味がよくわからないので、制度を教えていただきたいんです。","respondent":"冨岡高齢事業課長","answer":"旧ただし書き所得と申しますのは、国民健康保険は住民税をもとに保険料を出しているわけですけれども、総所得額から基礎控除を引いた額に対して掛ける掛け方を旧ただし書き方式というふうに言っていると聞いております。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"基礎控除というのは、単身であれば、年金控除の１２０万円プラス３０万円というふうなことでいいんですか。これに年金控除が１２０万円プラス３０万円の１５５万円をプラスした額が、年金収入ということで考えていい、そういう金額か尋ねました。","respondent":"冨岡高齢事業課長","answer":"こちらの３枚目のところに、参考ですけれども、「旧ただし書き所得範囲の中間値を換算したもの」ということで、１万円から１５万円、１６０万５,０００円ということで出ておりますので、その数値でよろしいかと考えています。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この計算の仕方で、国民健康保険みたいに所得割というのは、基礎控除額を引いた所得掛ける幾つとかという係数みたいなものがあるんでしょうか。そこら辺の計算の仕方を説明するよう求めました。","respondent":"冨岡高齢事業課長","answer":"わかりやすいのが、５０万円に、上にあります所得割率０.０６８４を掛けますと３万４,２００円になるかと思います。５割引いた、２割引いた額でそれぞれ出して、合算したものです。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"葬祭事業も国民健康保険のほうでやっていたわけですから、それから、区としてもお願いしたいということを要望をさせてほしいと求めました。７５歳過ぎたら健診はそんなに必要ないという中身でしたけれども、特定健診と同じ中身でされるということで確認させていただいていいんか尋ねました。","respondent":"冨岡高齢事業課長","answer":"特定健診のうちの必須項目について、広域連合で実施する、それを区のほうに委託すると言われております。それから、ほかのことにつきましては、先ほどの自己負担等と含めまして、また今までの経過を踏まえながら、今も調整して検討しています。","id":"exchange-019"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"ちょっと伺いたいんですけれども、基本的なところで、軽減措置の７割、５割、２割軽減のところなんですが、その基準はどういうふうになっているのか。２枚目のところには人数等が書いてあるんですけれども、基準がちょっとよくわからないので、教えてほしいと求めました。","respondent":"冨岡高齢事業課長","answer":"２割軽減につきましては、今と同様に計算しまして２３８万円というような形で、イメージ図ということで、この数字を基準にしています。やはり、受診をされる方とされない方の公平性という観点から、一定程度の自己負担金は必要だろうという判断に立ったと聞いております。","id":"exchange-020"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"これは、後期高齢者の医療制度ですから、現在の国民健康保険の条件よりももっと緩和していく必要があるんじゃないかと思うんですよ。結局、そこのところの考え方はどういうふうに持っておられるのか、お聞かせほしいと求めました。","respondent":"冨岡高齢事業課長","answer":"一つ一つの項目の検討の中で、広域連合の協議会で検討しているところでございまして、課長会として加わりながら対応してまいりたいと考えています。","id":"exchange-021"},{"speaker":"宮崎副委員長","kind":"意見","question":"今、課長会で加わりながら、というお話なんですけれども、要するに、そこで区としてどういうスタンスでいくのかということを、私は聞いているんですとの意見を述べました。","respondent":"冨岡高齢事業課長","answer":"最終的な判断というのは、当然、広域連合がするものですけれども、私どもといたしましては、今まで同様の国民健康保険と同様の判断に立って考えてまいりたいと考えています。","id":"exchange-022"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"後期高齢者というのは７５歳以上の制度ですから、やっぱり、国民健康保険と同じ条件だったら非常に厳しすぎるんじゃないかなと思うんです。こういう制度があっても、ほとんど使われないということになっていくんじゃないかなと思うので、そこのところも要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"品川区の後期高齢者の、平成２０年度、平成２１年度の人数を教えていただきたい。東京都では１２万人となっているんですが、緩和措置というんですか、その品川区の人数がわかったら説明を求めました。","respondent":"冨岡高齢事業課長","answer":"約３万１,０００人と把握しておりますけれども、平成２１年度につきましては、まだ予測をしてございません。それから、被扶養者につきましても、今のところでは、手元に数値を持っておりません。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もしできるものだったら、ぜひ追加していただきたいと思うんですが、いかがでしょうか。ぜひしていただきたいと思うんですが、そこのところは検討するとしたら、やっぱり福祉高齢事業部で検討するということになるんか尋ねました。","respondent":"冨岡高齢事業課長","answer":"検討をして調整をしていますので、今の段階では、ちょっとご提案を申し上げられないです。現在も国民健康保険は７万円ということで、たしか実施をしているということは伺っておりますので、また詰めてまいりたいと考えています。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"検討中ということですので、ぜひ、健康を守るという観点から項目も増やしてほしいと求めましたし、葬祭事業と自己負担についても、ぜひ、今までどおりにできるように要望をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"須藤委員","kind":"質問","question":"厚生委員会の１人として。６２市区町村が集まって広域連合という形で、それぞれ２３区と、説明を求めました。","respondent":"冨岡高齢事業課長","answer":"こちら側のほうは４３対５７ですけれども、市部は５０対５０とかということで、なかなか足並みがそろわない。一つ一つ決まりつつある部分ですので、６２の意思を一つにするというのはなかなか難しいということは、今さらながらわかったです。","id":"exchange-027"},{"speaker":"須藤委員","kind":"質問","question":"もう一つ、高齢者の医療制度を後期、前期に分けて、国のほうでこういう施策を持って行ったんだけれども、そういうことについては、別に何もなかったか尋ねました。","respondent":"冨岡高齢事業課長","answer":"すっぱり７５歳で切った段階での話を受けて、私どもの聞き及んでいる範囲では、聞いておりません。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"高齢者住宅は、入居できた方にとっては、ほんとうにこれで、住むという基本的なところが安心できるという喜びの声をたくさん聞いているわけですけれども、ここ２、３年の応募者と、実際に入れた人数について、説明を求めました。","respondent":"冨岡高齢事業課長","answer":"平成１８年度につきましては、１３７名というふうに２６名ほど減っております。平成１９年度につきましては、まだ途中ですが、１０月１日現在、１２名入居をいたしております。","id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"一つちょっと確認させていただきたいのが、平成１８年度末で東京都のが終わりましたけれども、ちょっと教えていただきたいんですけれども。","respondent":"冨岡高齢事業課長","answer":"１年ぐらい前からご意向を伺いまして、一部入れるようにしますからということでご案内をし、お入りになった方もおいでになります。高齢者住宅は２５m2ぐらいということで、あっ旋のほうもいたしましたし、すべてできる限りのことはさせていただきました。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"では、家賃助成が切れる方で、高齢者住宅を希望された方は入れたということでよろしいんか尋ねました。","respondent":"冨岡高齢事業課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"宮崎副委員長","kind":"質問","question":"平成１７年度は１６３名で、入居された方が１７名とか、入れてない方のその後の追跡調査みたいなものはやっているんでしょうか。どういうふうに対応されたのか、どのぐらいの方がどうしたのかわかったら、教えてほしいと求めました。","respondent":"冨岡高齢事業課長","answer":"それから、２階とか、３階も敬遠される傾向があります。どうしても急いで退去する必要があるとかということが出た場合につきましては、あっ旋とか、ご紹介をして何とか対応をさせていただいているです。","id":"exchange-032"},{"speaker":"宮崎副委員長","kind":"質問","question":"実際に登録は４０名で、１５名前後入れるということなんですが、その残りと、申請そのものが１５０名前後だと思うんですけれども、これからいくと１割ぐらいしか入れないということになるんですけれども、そういうところはどういうふうにされているのかというのはわからないか尋ねました。","respondent":"冨岡高齢事業課長","answer":"大家さんが早く立ち退いてくれとか、そういう急な立退きに対して、なかなかお部屋を貸していただけないという問題が一番かと思います。宅建品川支部と連携をとりまして、そういう内容については、対応させていただいているです。","id":"exchange-033"},{"speaker":"宮崎副委員長","kind":"意見","question":"たしか２番目と言われたんだけれども、翌年はどこかへ引っ越して行っちゃったんですけれども、やっぱり非常に期待している方も多いんです。長期基本計画をつくるとなっていますので、こういう、特に収入の少ない方の住宅建設は必要だということを述べておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"平成１８年度のまとめというのが区のほうでできていますので、ぜひこれを、厚生委員会の中でも報告をしていただきたいと思っています。そういうところでは、ぜひ、この報告をしていただきたいということで要望をしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"須藤委員","kind":"意見","question":"平成１８年度の法改正ということを限定しまして、どうぞ委員長、よろしくご配慮をお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"本間委員","kind":"意見","question":"ただいま、須藤委員のお話がありましたように、最初はどうかなという形もありましたけれども、今のお話のとおりで、平成１８年度の法改正に伴う部分があるということで、一度、介護保険制度推進委員会とは別に、この場でご報告願えたらありがたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"須藤委員","kind":"質問","question":"後日、案内がくるんだけれども、日程的に、何時から何時ごろまでやっているかぐらいわかれば幸いだと思うんです。時間が何も書いてないので、そのあたりだけ教えていただければ、手帳にちゃんと書いておこうと思っています。","respondent":"太田健康課長、高橋障害者福祉課長","answer":"８階の大ホールですけれども、１時から始まりまして、終了３時１０分ということで予定しております。先着６０人ということで、これは、１１月１２日から、電話で品川区保健所のほうで受付けするです。 私のほうから、席上配付しております、品川地区特別支援学校の設置計画について、説明します。東京都特別支援教育推進計画の第一次実施計画を平成１６年１１月に策定したものですが、中学部は平成１８年度に中央ろう学校に再編し。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/928192?Template=document&Id=3186#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":26527,"voices":100}},{"id":"h19-20071105-8","meetingId":"h19-cm11","date":"2007年11月5日","dateIso":"2007-11-05","committee":"建設委員会","time":"午後１時０３分～午後４時３６分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を64件整理しています。","topics":[{"id":"topic-01","title":"平成１９年陳情第６号 東急電鉄の「（仮称）戸越５丁目マンション計画」に関する陳情","agenda":"平成１９年陳情第６号 東急電鉄の「（仮称）戸越５丁目マンション計画」に関する陳情","exchanges":[{"speaker":"中塚委員","kind":"提案","question":"「今回提案する１３階建ての建築計画は、」とありますけれども、商店街のど真ん中というのが今回の建築物の大きな特徴なのかなと思うんですね。","respondent":"齋藤住宅課長","answer":"商店街の方にはこの標識設置前にお話をいただいておりまして、これまでもお話し合いをされていると聞いております。あいたスペースについては、連たん性が損なわれないように商店街と協力をしたいと業者の方はおっしゃっておられると、このように聞いております。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"いろいろとお肉屋、魚屋から雑貨屋も含めてつらがきちんとそろっていて、それがこのにぎわいや集客力をつくっているんだと思うんですよね。この図面を見る限り、表部分は駐車場ですから、区のほうはこの連たん性はどんなふうにご覧になっているんか尋ねました。","respondent":"齋藤住宅課長","answer":"１点目、要するに３階を超えるようなものを建てようとすると、どうしても奥を使って高いものを建てる。もう１つは、小さな再開発をしないと建てられないということもありますので、商店街の方もお悩みなんだろうと考えております。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"私が伺ったのは、それについてどんなふうにお思いになっているのかという点を伺いたいので、それについてご答弁をお願いしたいと思います。伺いたいのは、この商店街にどういった影響が考えられるのか、教えていただけますか。","respondent":"齋藤住宅課長","answer":"このマンションの１階部分に店舗が入るという説明で、連たん性を損なわせるということを決めつけることもなかなかできないだろうと考えます。いつまでも、ちょっと固くないもので３階建てのものを建てるか、私どもとしてはどうこう申し上げるということではございません。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"建築基準法は２９号線が都市計画決定されてから事業決定がされていないわけですから、せり出す建物というのも十分可能だと思うんですね。その法律上のことについて少し教えていただきたいのは、これはどういうものが可能になってくるのか、それについても教えていただけますか。","respondent":"齋藤住宅課長、片田建築課長","answer":"前半のほうは繰り返しになりますけれども、固いものを建てようとすると、下がらざるを得ない。ただそれだけなんです。これの規制は建築基準法ではございませんで、都市計画法の第５３条および第５４条に、その敷地の許可の考え方が説明されてあります。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"伺いたいのは、この商店街、こんな活気あふれる商店街の中にこういう建物ができるときに、区はどういうスタンスで業者に対して相談をされるのか。建てるに当たって業者へどういうふうに接しておられるのか、その姿勢が問われるんじゃないかなと思うんですけれども、いかがか尋ねました。","respondent":"齋藤住宅課長","answer":"それは持ち主の方が判断されることでございまして、その個々の商店の方々がどのように考えられるか、これはその方々の考えだと。法令の範囲内で建物を建てることは、それは持ち主の方の自由であって、区として指導するということは考えておりません。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"法律的には、いわゆる切り離しさえ可能な構造にすれば、つらはそろえることが都市計画法上、可能なわけですよね。２つですけど、そういう建物にするような働きかけがあってしかるべきではないのかなと私は思うんですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"井上委員","kind":"質問","question":"この計画のところで、地域が近隣商業地域と第１種住居地域になっているんですけれども、用途地域の地域を見ても、ぽつんとへこんでいる部分なんですが、そこは第１種住居地域にかかっている部分というのは、この計画ではないのか尋ねました。","respondent":"片田建築課長","answer":"左の変更前のほうがわかりやすいかなと思いますが、ちょうど二点鎖線で現状の６ｍ道路から、「都市計画道路ライン」と書いてあります。ここの寸法で約２０ｍということで用途境、それを見る限り、建物本体は近隣商業地域の中にすべておさまっているということになってあります。","id":"exchange-007"},{"speaker":"井上委員","kind":"質問・要望","question":"いろいろな住民の方のこれに合わせたいという要望があったけれども、積極的に取り組んでほしいと思うんですが、そういうところでの取り組みの姿勢をちょっとお伺いできればと思います。","respondent":"齋藤住宅課長","answer":"２つご質問があったかと思いますが、１つ目の絶対高さ制限、あるいは景観に配慮すべき地域だというふうには、今のところは考えておりません。したがって、１つ高いものが建つと、一律に現状のままの計画が正しいんだということは必ずしも言えないんだろうと認識しております。","id":"exchange-008"},{"speaker":"井上委員","kind":"質問","question":"ここでも１２台あるいは１７台の車が駐車場と入るということと、駐輪場が６０台確保されるということで、交通の部分とか防災に関する点での問題は危惧されることはないんか尋ねました。","respondent":"齋藤住宅課長","answer":"そういう危惧があるので、都市計画道路が入っているということです。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問・要望","question":"ちょっとお聞きしたいんですが、具体的な住民の要望というのはまだ見えないんですが、話し合いの中でどの程度まで出ているのか。その２点について説明を求めました。","respondent":"齋藤住宅課長","answer":"１４階、１３階ではなくて、６階にしてほしい。そこのところで事業主の方と折り合いがどうもつきそうにないということです。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"その中で急に１３階、１４階というのは、これは間違いないと思うんですよ。その辺を区のほうとしてもやはり十分働きかけていただいて、推移をもう少し見ていただきたいなというのを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"阿部委員","kind":"質問・要望","question":"この要望の中でも、協議のテーブルに着くように指導ということなんですが、今後の協議の予定というのは、もうないのでしょうか。それとも、工事に限ってなさるとか、何かその辺の通知があれば説明を求めました。","respondent":"齋藤住宅課長","answer":"ただ、高さを下げることは難しい。このようなことです。","id":"exchange-012"},{"speaker":"阿部委員","kind":"質問","question":"店舗の部分とか住民の扱いですとか、そういったところも含めた話し合いというのは、東急電鉄としてはもう全くしないんだと。ただ、工事では今後の話とかといった、そういったことに限ってなら、お話をするんだということなんか尋ねました。","respondent":"齋藤住宅課長","answer":"プランニングのものについては、もう変更の余地は基本的にはないというのが東急電鉄の考えです。","id":"exchange-013"},{"speaker":"阿部委員","kind":"質問","question":"１つ伺いますけど、ここに店舗を予定されていますが、これは例えば、以前にお店を営んでいらっしゃった方が、また戻ってきてお店をするということか、その辺がわかれば説明を求めました。","respondent":"齋藤住宅課長","answer":"カラオケや電気店がありましたが、どういう権利関係になっているかわかりませんけれども、等価交換ということで、その方が戻られるかもしれない。ただ、いずれにしましても私どもとしては承知しておりません。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"確認","question":"改めて確認をしたいんですが、それが２度も３度もあったわけだけれども、そこら辺の経緯をもう一度教えていただけますか。","respondent":"阿部都市計画課長","answer":"今、委員ご指摘の２９号線の件ですけれども、今お話がございましたように、区議会のほうでも３度ほど採択になってあります。現状としてはこういうことです。","id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"この計画が今お話を伺ったら、これは確認申請を出したとするならば、大変難しいものが出てくるだろうなと私は思っています。建築基準法もあるわけですから、ここは議会ですから、法を超えた判断をするというのはなかなかできわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"三上委員","kind":"質問・要望","question":"ちょっと１つ駐車場の関係で確認をさせていただきたいんですけれども、１３階建てにした場合には１２台。これは、そう考えていいんか尋ねました。","respondent":"片田建築課長","answer":"今、委員のおっしゃるとおりでございまして、将来、事業がなされて行ったときには、その２台の用地については入っていないということ。したがって、残ったところに設置していくようなことになってくると思います。","id":"exchange-017"},{"speaker":"三上委員","kind":"意見","question":"買収されてしまったら、その台数が減ったということで、それは区としても認めていっていいのかどうか。これはどういうふうに考えますかとの意見を述べました。","respondent":"片田建築課長","answer":"既存不適格といったような考え方になりますので、仮に設置の変更等、あるいは別な不適行為がなければ法的にはカウントされると。ただ、いわゆる隔地駐車という考え方もあるように、３００ｍ以内のところに隔地駐車場というようなものを設置ができるということです。","id":"exchange-018"},{"speaker":"三上委員","kind":"意見","question":"今のような話というのは、区と事業者との話し合いの中、また、地元の皆さんとの話し合いの中ではそれはきちっと表に出ている話として認めていいのか、どうなのかとの意見を述べました。","respondent":"齋藤住宅課長、片田建築課長","answer":"業者の方との話し合いは建築課で担当の者が話をしていますが、住民の方にはご説明していないというふうに考えております。 変更後は、事業者の先ほどの５台の計画案でもありましけれども、隔地駐車ができないだろうかというような相談は、確かに窓口に来てあります。ただ、話し合いの経過を見て、検討の課題にはなろうかというふうに考えてあります。","id":"exchange-019"},{"speaker":"三上委員","kind":"質問","question":"それはどうなんですか。それは防災の計画ですから、ちょっと担当部署が違うかもわからないけれども。","respondent":"伊勢住環境整備担当課長","answer":"７ｍだとか、そういうふうな数字があります。高さも違ってくるとは思いますけれども、基本的に耐火性の建物で延焼遮断を行うということですから、一定の高さが必要になるということです。","id":"exchange-020"},{"speaker":"三上委員","kind":"意見","question":"そういう部分についての、他人様の財産についてどう考えるかという、これも考えてあげなきゃならない部分もあると思います。そういった点で、私は非常に複雑な、今日の案件が出されてきたなというふうに、現実は悩んでいるところですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"意見","question":"私は、やっぱり先ほど言いましたように結論は出すべきだと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"三上委員","kind":"質問・要望","question":"私は、結論を出すということについては、それはそれでいいと思いますけれども、まだちょっと疑問の部分があるので、本日のところは継続にさせていただきたいなと、こういうふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"中塚委員","kind":"意見","question":"私も結論を出すべきだと思います。これから本格着工すれば、いよいよ住民の方々の願いというのは業者に届きにくくなりますから、今時点できちんと結論を出すべきものだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"須貝委員","kind":"質問","question":"たくさんのお客さんももちろん住民の皆さんも抱えているわけですから、やはりもっと話し合いを持っていただいて、今は解体工事中です。継続です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"藤原副委員長","kind":"意見","question":"陳情の具体的なところに解体工事を当面中断するようにとか出ていますので、継続してしまうと次の委員会等の日程を考えてしまうと、どんどん延びてしまいますので、私は、きょうちゃんと結論を出すべきだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"井上委員","kind":"意見","question":"第４番目の協定書を締結した後に着工するよう指導してほしいという協定書の問題など、先ほどの道路が先か、建物が先かという問題についても。それは別として、結論を出すということでお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"石田（秀）委員","kind":"質問","question":"丁目の中で本当に４丁目が入った中で、どうしてもこの２９号線は必要だ、それはそれで決定が出ている。代替案というのを追加してほしいという、この代替案をお伺いすると、後面６階というお考えがあるみたいだけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"中塚委員","kind":"意見","question":"周辺の商店街という環境との調和、あともちろん工事協定書についても気持ちはよく理解できますので、採択すべきだと思います。それと関連してですけれども、今若干２９号線の話が出ましたけれども、私は２９号線の計画もやめるべきだというふうに思っておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"}]},{"id":"topic-02","title":"の羽田空港跡地利用基本計画（素案）","agenda":"の羽田空港跡地利用基本計画（素案）","exchanges":[{"speaker":"井上委員","kind":"提案","question":"三者による協議ということなんですが、例えば品川区として参加をされている方たちがどのような提案をしたのか、品川区としての提案がもしあったのなら説明を求めました。","respondent":"阿部都市計画課長","answer":"この基本計画についても、こういう方向性で行くよというのも３月で合意をして、その合意に基づいて、今回、素案をまとめたものです。先ほど説明申し上げましたけれども、基本的な方向性については了承しておりますし、それに従って今回の素案をまとめたということです。","id":"exchange-030"},{"speaker":"井上委員","kind":"質問","question":"この素案は、主に東京都から出されたものかということと、ほとんど大田区の敷地内ということでしたので、今後、そういう意味では、どういった形で整備が進められていくと考えたらいいのか尋ねました。","respondent":"阿部都市計画課長","answer":"逆に川崎市と区との区界の部分ですので、そういう三者で検討いたしまして、その有識者会議の指導助言を受けながら進めてきたというものです。","id":"exchange-031"},{"speaker":"井上委員","kind":"質問","question":"その先の計画のところで品川区が何かかかわっていくとか、いろいろな予算の関係で出てくるものとか、そういうことはもうなくということですか。それとも大田区と都が整備していくということでいいのか。","respondent":"阿部都市計画課長","answer":"三者協については、品川区も当然入っていますので、最終的にはその三者協の中で決めていく形になろうかなというふうに思います。具体的に今後どう進めるかというのは、今後の課題ですので、今の時点で具体的な事業をどうするということを決めているわけではございません。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"それとも計画（素案）というのはほかにまだしっかりとあるのか教えていただきたいのと、どういう協議をされたのか、その議事録的なものというのはあるのかどうか説明を求めました。","respondent":"阿部都市計画課長","answer":"素案はこのものすべてです。議事録については、東京都のほうが窓口をやっていますけれども、議事録は作成してございません。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問","question":"それとまた基本的なことですけれども、この基本計画の事業主体というのは、それぞれが協議しているという話はありましたけれども、事業主体はどういう形になるのか、総事業費とか、補助金とか、それはどういう形になるのか教えていただけますか。","respondent":"阿部都市計画課長","answer":"事業主体の話ですけれども、先ほど申し上げたんですが、土地処分をどうするか、それがまだ決まっていませんので、事業主体は、例えばどこが何をやるのか、そういうものは一切決まってございません。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問","question":"どこが何をやるか、いわば事業主体はまだ決まっていないというお話ですけれども、少なからず国か都か大田区か品川区か、それとも若干またがるのか、説明がよくわからないので教えていただけますか。","respondent":"阿部都市計画課長","answer":"ですから、先ほど申し上げたように土地処分の候補も決まっていないという話で申し上げました。ですから、そういう意味で、それは今後どういう進め方をするのか、今後の検討条件になるということです。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問","question":"最後に、品川区もこの協議に参加されているということでちょっと伺えたらと思うんです。どういう見通しなのか、航空需要の増加の根拠というんですか、その辺はどんなふうな議論がされていたのか教えていただけますか。","respondent":"阿部都市計画課長","answer":"これが４０万７,０００回ということで、約１１万回ぐらい増えるという状況ですので、航空需要は増えていくという予測があります。もう１点は、国際便は定期便が就航するですので、そういう意味での今委員がおっしゃったような航空需要は増大してくるだろうというふうな考えです。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に、今の３０万回弱が４０万回に増えていく話ですけれども、そこの需要の伸びは、もう少し詳しく教えていただければ、どういう背景が伸びるというふうに予測していくのか、もうちょっとそこだけ詳しく教えてほしいと求めました。","respondent":"阿部都市計画課長","answer":"ただ、現況は今のままでめいっぱいですので、発着枠は増加できない。何年後になるかという、その詳細は持ってございませんけれども、そんなに余裕があるという話ではないというふうには聞いております。","id":"exchange-037"},{"speaker":"石田（秀）委員","kind":"質問","question":"３５７号もここから出たところは非常に、今でさえ京浜島の手前は混んでいるわけですよね。そういうところに何か品川区も参画するという気があるのかどうか、そういう気があるのかどうか、そこについてお伺いします。","respondent":"阿部都市計画課長","answer":"ここの６ページの図に、斜めでグレーのところに「神奈川口構想で検討されている連絡道路」、６ページの川崎市の上に斜めで書いてあります。そういうこともいたしながら、何かできるかどうか、それを今後検討していきたいというふうに思っています。","id":"exchange-038"}]},{"id":"topic-03","title":"大崎駅西口Ｃ地区","agenda":"大崎駅西口Ｃ地区","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ちょっとお聞きをしたいんですが、平成２０年１２月までに解体ができるんだということなんだけれども、これは先に整備というのはできないのか。平成２３年２月まで行ってしまうわけで、隣も含めて交通広場があそこでは非常に求められていて、それはいかがか尋ねました。","respondent":"青木都市開発課長","answer":"その場合には、委員のご指摘を踏まえまして、その協議の中で検討させていただきたいと思います。現在のところ、特にそこまでのスケジュールが決まっているものではございません。","id":"exchange-039"},{"speaker":"中塚委員","kind":"質問・要望","question":"要綱に基づいて近隣説明会という話でしたけれども、開催はこの１０月４日の１回切りだったのかどうかを教えていただきたいなと。その辺をちょっとどういうことなのか教えてほしいと求めました。","respondent":"青木都市開発課長","answer":"これもやはり４日に住民の方々からもご指摘がありまして、事業者側の説明としましては、まずは引っ越しは既に終わっております。その後の工事スケジュールから考えてやらせてほしいというようなご理解を求めた説明をしておりまして、内装撤去から徐々に始めているという段階です。","id":"exchange-040"},{"speaker":"中塚委員","kind":"質問","question":"１回で終わっているというのは、この解体のときも、説明会を義務化しましたよね。ぜひ説明会が１回というのは、きちんと指導をして開かせるべきではないのかなと思うんですけれども、その辺はいかがか尋ねました。","respondent":"岩田まちづくり事業部長、齋藤住宅課長","answer":"解体に伴う、これは要綱で説明会をお願いしているわけですけれども、必ず説明会をしてくださいと。だから、そういう中の説明会ということなんでしょう… 個別の事情はまちづくり事業部長が申し上げたとおりです。解体工事説明会は何回かやる場合もありますけれども、こうこうやりますとか、１回で終わることが多いです。","id":"exchange-041"},{"speaker":"中塚委員","kind":"確認","question":"今で言う解体工事をする業者というんでしょうか、１回の説明会の中で、そういう説明がされたかどうかも確認したいんですけれども。振動いろいろあるわけですから、きちんと調整を図るテーブルを区としてきちんと持たせるべきではないのかなと思うんですけれどもいかがか尋ねました。","respondent":"青木都市開発課長","answer":"特に事業者のほうから皆さんに対して説明はしなかったようですけれども、いろいろな事業者が輻輳して工事を実施しておりますので、各工事の進捗状況。","id":"exchange-042"},{"speaker":"中塚委員","kind":"質問","question":"ソニーがどうかわかりませんけれども、よく古い建物を壊すと、図面上ないとされている場所からも出てくる場合も多々結果としてよくあるわけですよね。説明すべき、そういうことはきちんと近隣説明会という形で私はやるべきだと思いますけれども、最後にいかがか尋ねました。","respondent":"齋藤住宅課長","answer":"建物本体ですので、何回も業者が決まらないと説明会を開いて説明しなければいけない、そういうものではございません。適切に対応するように指導するのが私どもの役目でございまして、２回の話ではございませんで、解体でしたら一般的に１回が多いです。","id":"exchange-043"}]},{"id":"topic-04","title":"本日は、ご案内のとおり、耐震化促進計画","agenda":"本日は、ご案内のとおり、耐震化促進計画","exchanges":[{"speaker":"井上委員","kind":"意見","question":"あるいは文書の形になって計画というふうに出されるものかということが１点と、第４回定例会のほうで報告ということで、そこの２点をまずお答えくださいとの意見を述べました。","respondent":"片田建築課長","answer":"今回、中間のまとめということでご報告させていただいた考え方については、計画の骨子になるというものと一応考えてあります。素案についても、まとめた中で決定をとった上でご報告させていただきたいと考えております。","id":"exchange-044"},{"speaker":"井上委員","kind":"質問","question":"最終的に、中間のまとめなので、素案として出されたものが報告されて、決定というのは、来年の３月、今年度中の決定案ということで、その辺はどういうスケジュールか尋ねました。","respondent":"片田建築課長","answer":"言葉が足らなかった部分がありますけれども、基本的には中間のまとめを当初の予定としては９月中に行うということで考えてございました。１２月末になるか、１月早々になるかわかりませんけれども、できる限り早い時期に公表をしていきたいと考えています。","id":"exchange-045"},{"speaker":"井上委員","kind":"質問・要望","question":"その辺でどれぐらいの精度を見込んだデータなのかということを教えていただきたい。その具体的なものはどういうことがあるかということを区民の方が直接目にして、こういうふうに書式を整えようとする予定があるのかどうなのか。","respondent":"片田建築課長","answer":"区が進めてきている長期基本計画の中の総合実施計画、ただ、とりまとめを行っていきたいということで考えております。２１ページのほうの総合的な施策における取り組み、ここの中では区がこれまでやってきた木造住宅の実施状況とか、対応していきたい。","id":"exchange-046"},{"speaker":"中塚委員","kind":"質問・要望","question":"その理由や背景を中心に伺いたいと思うんですけれども、資料を見ると感じますけれども、そこを一歩踏み込んだご説明をほしいと求めました。大規模な地震もありますけれども、こういったところをどういうふうに分析した上での今回の中間のまとめなのか、そこもあわせてご説明いただけますか。","respondent":"片田建築課長","answer":"そういうことも含めて、そういうような施策を進めてくれということで、いろいろ平成１７年に見直してきたというような経過があります。考え方をきちっと調整しながら、そういうことも含めて、施策の中に取り込んできたという経過があります。","id":"exchange-047"},{"speaker":"中塚委員","kind":"質問・要望","question":"住宅の耐震化をいわゆる評価した理由、過去の阪神・淡路大震災の教訓をどういうふうに踏まえた耐震改修促進計画なのか、そこをもう一度説明ほしいと求めました。","respondent":"片田建築課長","answer":"２３区がもう既に動いてございまして、環状に広がる、いわゆる密集地域が広がってあります。そういうことも含めて対応していくべきであろうということを含めて、委員がおっしゃるような区の独自性がないというものではないと考えております。","id":"exchange-048"},{"speaker":"中塚委員","kind":"質問・要望","question":"残っていないですか。あわせて、今回、目標を９０％と設定したわけですけれども、耐震化の目標を設定したその理由は何か、変更点についてご説明ほしいと求めました。","respondent":"片田建築課長","answer":"確かに現在の私どもの進めている改修に当たっての支援施策ということでは、６ｍ道路以下に面しているということを１つの条件としてございました。","id":"exchange-049"},{"speaker":"中塚委員","kind":"質問・要望","question":"同時に地震火災を防ぐという大きな要因ではないかと思うんですけれども、そういう視点を区は分析されているのかどうか教えていただきたい。初期消火を十分に可能とするためにも、建物の耐震化というのは必要ではないかと思うんですけれども、そういう視点というのはいかがか尋ねました。","respondent":"片田建築課長","answer":"木造住宅の４ページの左上ですけれども、木造住宅の耐震化の現状ということでの分析で、整備地域ということでブルーのハッチを引いてありますが。","id":"exchange-050"},{"speaker":"中塚委員","kind":"質問・要望","question":"診断の部分で助成という考えが出されたわけですけれども、そこの変更点、新たに踏み込んだ理由を教えていただきたい。マンションですから、この耐震化を進めるための呼び水的に考えているのか、それともまた別の考えがあるのか。","respondent":"片田建築課長","answer":"マンションは立体的な密集といったことも考えられるわけでございまして、マンションについても踏み込んだという経過があります。現在２,０００m2ぐらいの規模を想定していった中で、区の負担としてどのぐらいが適切かといったような形で今考えているという状況です。","id":"exchange-051"},{"speaker":"中塚委員","kind":"質問・要望","question":"所得の少ない方へのそういう制度というのはどういうふうな工夫が考えられているのかいないのか、教えていただきたい。「家具転倒防止等の推進」と書いてあるんですけれども、これは従来と何か変わる点があるのか、どういう考えなのか教えていただけますか。","respondent":"片田建築課長","answer":"なかなか経済的な負担がありますし、特に高齢者を中心とした方向での考え方を持ってありますので、そのような状況です。関係課との連携、調整の中で進めていきたいと、このように考えてあります。","id":"exchange-052"},{"speaker":"中塚委員","kind":"質問","question":"その課題はどのようなものがあると思っているのかをお伺いしたい。電話も含めて１０件、文書等は４件という話でしたけれども、なかなか地震に強いまちづくりというのが進まないものですから。","respondent":"片田建築課長","answer":"だから、いろいろな状況がわかってきてありますので、それを今後の施策の中に組み込まれる要求については検討してまいりたいと。やはり啓発をすることが一番大事だと思ってありますから、今後そういうことについての施策についても検討していきたいと、このように考えてあります。","id":"exchange-053"},{"speaker":"阿部委員","kind":"質問","question":"この９０％というのをどういうふうにとらえられているのか。ちょっとその辺の考え方を説明するよう求めました。","respondent":"片田建築課長","answer":"確かに今の耐震化の現状からすれば、かなり高い目標値ということで一応私どもも説明しています。ただ、私どものほうとしても今後実施した中でそういう課題を浮き彫りにしながら、必要な応対を考えていきたいと考えています。","id":"exchange-054"},{"speaker":"阿部委員","kind":"質問","question":"この中で一応８０％、６０％というような数字が出ているんですが、これは９０％はぱっと見てもないんですね。区有施設であって、耐震化が９０％、１００％のレベルに行かないのは何か理由があるんか尋ねました。","respondent":"片田建築課長","answer":"防災の拠点となるような施設については基本的には１００％ということで目標にしているものです。それ以外の施設についても、ここには目標値としては掲げていない部分もありますけれども、基本的には一応９０％という目標の考え方です。","id":"exchange-055"},{"speaker":"阿部委員","kind":"確認","question":"確認ですが、これについては少なくとも平成２７年度までには９０％はクリアする。１００％であってもおかしくないと思うんですけれども、そういったことでよろしいんか尋ねました。","respondent":"片田建築課長","answer":"優先的に区のほうとしても耐震化を進めていきたいということで、優先順位をつけて進めてきてありますので、目標としては９０％ということで考えています。","id":"exchange-056"},{"speaker":"須貝委員","kind":"質問","question":"でも、これは耐震診断をしたわけではなくて、目視で大体を判断したということでしょう。その辺をちょっとお聞きしたい。","respondent":"片田建築課長","answer":"今のご説明なんですけれども、３ページのちょうど下のほうに説明書きを星印で記載していますけれども、今ご説明しましたように。マンションについてはなかなかそれは難しいというところがありますので、このような推計値を発表するという考え方です。","id":"exchange-057"},{"speaker":"須貝委員","kind":"質問","question":"先ほど自然更新ということで、この中にはもう既に耐震化されていても建て直しをするというのが、おそらくマンションでも建屋でもあると思うんですね。そうすると、１,０００件という目標値がさらに減るという考え方ができると思うんですが、その辺はどのようにお考えか尋ねました。","respondent":"片田建築課長","answer":"それまで、これらの推計値に基づく理論値として平成２７年度までに目標の９０％を達成する上で、どのぐらいのところを考えなきゃいけないかです。そういうものを類推した推計ですので、若干、更新の状況によってはこの数字も変わってくるというふうにも考えられます。","id":"exchange-058"},{"speaker":"須貝委員","kind":"質問","question":"やっぱり耐震診断の数も本当にまだ、今、２００件ですか。難しいと思うんですけど。","respondent":"片田建築課長","answer":"区のほうとしては、やはり意識啓発とかそういうＰＲを含めたことが基本的に本当にきちんとしていただかないと困る、ということを考えてあります。わかりやすく説明していきたいと、そのように考えていますが、そういうねばり強い取り組みが必要だということです。","id":"exchange-059"},{"speaker":"須貝委員","kind":"質問・要望","question":"全額がなるのかどうかの問題はありますが、そういうことを踏まえて、やはり何か考えなければいけないのかなと。わかっていてもできないということを是非都や国のほうへ訴えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"石田（秀）委員","kind":"確認","question":"ほかのところでぜひまた一生懸命質問しますが、ここでは基本的な確認だけをしたいのですが、木造住宅がある。だけど、予算のこともあるから、ここだけである程度この部分は地域を限定してやっていこうということなのか、そこら辺の考え方を再度説明を求めました。","respondent":"岩田まちづくり事業部長","answer":"先ほど建築課長のほうの説明が少し不十分だったかもしれないんですが、この整備地域内で、かつ６ｍ未満の道路に面した建物に限定しておりました。「施策の方針」の２つ目、耐震改修の支援を区内全域に拡大をいたします。","id":"exchange-061"},{"speaker":"石田（秀）委員","kind":"意見","question":"例えば、どうせその改修の仕方なんていうのは、ほとんど建て方によって決まってくると思っているわけ。１２万円出してあげれば、あとは建替えがあり、私はそんなところまでちょっときめ細かくやってあげたほうがいいんじゃないかなと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"井上委員","kind":"質問","question":"先ほど１つだけ答弁漏れなんですけど、自然更新のところで、その５ページでいけば、３,９５２棟というのは、精度がどの程度と確信をしているのか。さっきの９０％もすごく高い目標じゃないですかということも含めて、先の計画というのがいくと思うんですけど、どのくらいと思えばいいのか。","respondent":"片田建築課長","answer":"５年後あるいは７年後にどの程度の申請が出てくるかということはわかりませんけれども、適用した中でこういう目標値なり推計値を出してきているです。","id":"exchange-063"},{"speaker":"本多委員長","kind":"質問・要望","question":"前回の委員会におきまして、井上委員より道路大会参加に関する議会運営委員会における審議状況等、確認を求められた件についてです。本件につきましては、議運において申し合わせ確認事項を変更することはない、ということを確認いたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/325823?Template=document&Id=3894#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":47643,"voices":144}}]);
